/* 平成29年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h29.committeeSessions.push(...[{"id":"h29-20170613-14","meetingId":"h29-cm06","date":"2017年6月13日","dateIso":"2017-06-13","committee":"行財政改革特別委員会","time":"午後１時００分～午後３時０５分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","topics":[{"id":"topic-01","title":"今後の委員会運営","agenda":"今後の委員会運営","exchanges":[{"speaker":"筒井委員","kind":"質問","question":"品川区の将来人口の推計についてなのですけれども、最初の総人口のところで、既に今年度３８万人を超えていると思うのですけれども、この将来推計値ですと、約１万人少なく出しておられるので、やはり１万人ぐらいの差が出ているということで、いま一度そうしたことも踏まえて人口の推計を取り直したほうがいいのではないかということが１点と、あと平成で推計をとっていますけれども。","respondent":"柏原企画調整課長","answer":"先ほどのご説明のときに、ちょっと触れずに申しわけなかったのですが、こちらの人口推計は日本人と外国人に分けさせていただいています。","id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"それと、設置に当たっては、国に計画案を提出する必要があるということもかつて何かどこかで答弁があったのですけれども、計画案の提出と、実際の相談所の開設はいつごろを予定しているのか伺いたいと思います。それがどうなるのかをお伺いしたいのと同時に、身近な品川区として、自治体として相談所を設置することの意義とかメリットというのは、品川区としてはどのように考えているのか伺いたいと思います。","respondent":"高山児童相談所移管担当課長","answer":"それの前提としましては、計画案の策定ということが必要でございまして、これに当たっては東京都との十分な協議を経て計画をつくらねばならないというようなことで伺っておりますので。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"人口ビジョンのほうに移るのですけれども、これは全体を理解するために伺いたいのですけれども、単純に生産年齢人口のピークだけが随分早く訪れる推計となっているのですけれども、その理由は何なのかというのと、それと本文といいますか、総合戦略のほうについている前文のほうの５８ページに人口推計の方法というのが入っているのですけれども、ちょっとわかりづらいので。","respondent":"高山児童相談所移管担当課長、柏原企画調整課長","answer":"ここに至りまして、モデル的確認実施区というところを入口に、さまざまな情報を得るというところまで、ようやく１年かけてこぎ着けたというところが、今年度、平成２９年度につきましては、内容については。人口ビジョンの部分です。大きく２点ご質問いただきましたが、後半のほうのご質問を先にお答えといいますか、ご説明したいと思います。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"あと２点質問します。人口ビジョンのほうの全体的な理解のためにちょっと伺うのですけれども、人口ビジョンということですから、何か単なる推計ではないと思うのですけれども、これを踏まえて策定された総合戦略の基本的視点という中に、将来的な人口減少を見据えつつ、生産年齢人口を維持し、安定的な人口構造を確保するために子どもを産み、育てやすい環境を整備し、出生率の向上と安定を目指す。","respondent":"柏原企画調整課長、大串福祉計画課長","answer":"そうした方々が住み続けていただくために、それを将来的に継続的にというところで申しますと、子育て世代、それからお子さん、さらには品川区でお子さんを産んでいただいて、そのまま住み続けていただくというのが。前提といたしましては、これは本年２月に出て、それ以降まだ国のほうから何かといったところがないというのが現状だといったところ、それから、区としての取り組みというか認識といったところになろうかと思いますけれども。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"それと、基礎自治体のあり方に関することの人口動向ということですと、人口の多い、少ないをやっても仕方がなくて、要するにそれを見て何を進めるかというものに対してあらかじめ幾つか調査するに当たっては、そのポイントを見据えていかないと方向性があっちに行ったり、こっちに行ったりしてしまうのかなというイメージがありますので、ぜひその辺を。","respondent":"鈴木（ひ）委員長","answer":"今日は概要説明をしていただいていますけれども、この後にこれから先の１年間に、項目としては議会運営委員会の中で挙げられた項目と、それから備考ということで進めていくわけですけれども、これをでは具体的にどんなことをやっていきたいか、今のようなご要望ですとか。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問・要望","question":"安心いたしましたというか、承知いたしました。今漠然と内容に入っていますので、これをやり出すと行財政改革特別委員会は説明をもらって１年分を今日やってしまうような形になりますから、その辺を配慮してばーっと説明していただいて、最後に要望とかという形にしていただかないと、終わりが見えなくなってしまいますので、そういうのもありまして、今ちょっと確認しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"意見","question":"そういった部分で、区として今課題と考えていることというのは何かというのを概要ですので、大まかでいいですのでお聞かせください。","respondent":"高山児童相談所移管担当課長","answer":"具体的には、児童相談所には一時保護所という附帯の施設が必要なのですけれども、そういったものも含めますと、おおむね土地の面積でいきますと、品川区レベルの規模の区でありますと。","id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"質問","question":"今ご説明いただいたとおり人材が本当に大切かなと思うのですけれども、１,０００m2以上ある土地を確保して、また相談、一時保護、こういうことを進めていくわけですけれども、どれぐらいの規模の人員設計になっていくのか、確保していこうと考えているのか伺いたいと思います。","respondent":"高山児童相談所移管担当課長","answer":"必要数については、所要人員につきましては、今後積み上げてまいりたいというふうに考えております。","id":"exchange-008"},{"speaker":"松永委員","kind":"確認","question":"もう一つ最後に、総合庁舎の今後の設備・機器等の更新についてなのですけれども、今この議会棟の３階にあります全然使われていない噴水があると思うのですけれども、それはずっとこのまま放置されるのか、今後のあり方について伺いたいと思います。","respondent":"柏原企画調整課長、立川経理課長","answer":"地元の方々からも、あのプールに関して、プールということだけではなくて、何か有効的にこの広さを活用できないのかというようなご意見もいただいていますので、現段階では特に何かという具体案はないのですけれども。それで、委員は放置という言葉を使われましたけれども、考え方といたしましては、撤去もかなりの費用がかかるですので、今の状態をそのまま存続させたいというふうに考えているところです。","id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"最後の噴水なのですけれども、やはり結構人目につく場所なので、何か、例えばオリンピック前までに何とかするとか、何か考えていただきたい。もし、壊す費用がかかるのであれば仕方がないかなとは思うのですけれども、ぜひ要望ですので、何か改革をお願いいたします。","respondent":"立川経理課長","answer":"今後の運用につきましては、いろいろな観点から研究してまいりたいなというふうに考えております。","id":"exchange-010"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと資料について伺いたいのですけれども、まず庁舎のほうですけれども、必要最低限の更新とか経費節減に努めていくというのは別に全部否定するつもりはないのですけれども、庁舎本体については更新とか建て替えするというのが既定路線の説明になっているかなというふうに思うのですけれども、もしそうであるならば。","respondent":"柏原企画調整課長","answer":"さらに区有地もその間に入っているという状況を考えたときに、そういったところもいろいろな面で総合的に考える必要はあるだろうという考えでいるというものです。","id":"exchange-011"},{"speaker":"安藤委員","kind":"質問・要望","question":"都の見解等を伺いながらということですけれども、ぜひこれだけいろいろ行政需要が求められているときに貴重な土地だと思いますので、この委員会としてもちょっと議論の俎上にのせていく必要があると思うので、ぜひそういう都の見解等も情報収集していただいて、報告していただきたいというふうに要望したいと思います。区としては、この状況をどう考えているのか、現在の見通しだけちょっとお伺いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"安藤委員","kind":"質問・要望","question":"２点だけ質問します。といいますのは、ここではちょっと先ほど説明がなかったのですけれども、環境影響の方策の後、去年８月に品川区への配慮事項というのが実際出されて、この委員会に報告されていたのですね。条件闘争ではなく、地元自治体としてやらなければいけないのは、反対表明を行うということだと思うのですけれども、いかがでしょうかというのが２点目の質問です。","respondent":"中村都市計画課長","answer":"ですので、区民に対して理解を深めるような説明会をさらに行っていただきたいというふうに考えておりますし、またこの新飛行経路の案が実際に実施されるような場合についての安全対策ですとか、そういったものを確認していくというものも国から出された案を検討する際には。","id":"exchange-013"},{"speaker":"安藤委員","kind":"質問","question":"ちょっと最初の質問のほうの説明が不十分というところで、内容そのものについて理解されていないと感じているというのはわかったのですけれども、その後ちょっと、区へも同じような意見が寄せられているみたいな答弁の内容がちょっとわからなかったので、もう一度そこだけ説明をお願いします。","respondent":"中村都市計画課長","answer":"そういったところが、主に区民の皆様からいただく意見で、区が認識しています。","id":"exchange-014"}]},{"id":"topic-02","title":"その他","agenda":"その他","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"私はそこまで児童相談所の問題について自分で研究したことがないものですから、品川区の中にある児童相談所を視察させていただければなと思っていたのですけれども、先ほど横須賀市というお話があったのですが、品川区がなぜ金沢市の視察を行うのかということ自体も私はよくわかっていないのですけれども、この中に一時保護所というのですかね、そういったものもあるものとないものがあって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"渡部委員","kind":"質問・要望","question":"だけれども、金沢市ですとか、ちょっと横須賀市は人口がどれぐらいかわからないのですけれども、品川区が４０万人弱の人口の中で何かをやっていこうとしたときに、それに近い、広さは別として人口規模で似たようなところでやっていけているのであれば、そういうところの話もちょっと聞いてみたいなという思いがあって、品川児童相談所はそこにありますし、それは東京都の所管の中でやっていますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"横山委員","kind":"質問・要望","question":"ですので、数字だったり見える部分だけ、わかりやすい部分だけではなくて、どういったところにメリットがあって、どういったところに課題があるのかというところをしっかり捉えていきたい、方法とあと手段、課題と成果というところ、いろいろな視点で議論できたらいいなというふうに考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"つないではもらえるかもしれませんけれども。そういったものをちょっと列挙していただきたいなと。人口流入の中で、どういう方たちが先ほど申し上げたような観点でこれから増えていくことが予想されるのかとか、現状、所得層がどのように分布しているのかというようなところ、少なくとも現状の部分で、何かフロー図でわかるようなものがあるのか、そういったものがあれば提示をお願いしたいなと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"安藤委員","kind":"提案","question":"これも要望したいというふうに委員長にお願いします。それと、羽田空港については、この間の委員会質疑でも、率直に言って区は国のメッセンジャーの役割しか果たせていない状況で、ある意味無理もないというのは、この計画の当事者は国ですから、直接の責任者は国ですから、そうなってしまうのですけれども、ですから、議会とか委員会として国に直接質問できればと思いますので、これも提案したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"筒井委員","kind":"質問・要望","question":"私から、今回のまず基礎自治体のあり方に関することについてなのですけれども、児童相談所移管というのは、今回実現の方向性に向かっていると思うのですけれども、その他品川区として特別区長会の意見というのは重なり合うところがあるかと思いますけれども、児童相談所以外で東京都から移管してほしい事業とか分野はあるのかということ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"大倉委員","kind":"意見","question":"児童相談所移管については、皆さん先ほどから言われるように視察を、私たちも見たりはさせていただいたのですが、もう一度そういったところをまたこの行財政改革特別委員会でやるというところで、もう一回見するのは非常にすばらしいかなと思っていますので、ぜひよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"若林委員","kind":"質問・要望","question":"会派からも今要望等させていただきましたけれども、私もちょっとワンポイント、児童相談所の移管については、視察に行くということを要望させていただいて進めていただきたいのですが、先ほどちょっとあった都の児童相談所へ既に職員を派遣されていると。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/788161?Template=document&Id=6030#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":42110,"voices":90}},{"id":"h29-20170614-18","meetingId":"h29-cm06","date":"2017年6月14日","dateIso":"2017-06-14","committee":"オリンピック・パラリンピック推進特別委員会","time":"午後１時００分～午後３時２０分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を47件抜き出しています。","topics":[{"id":"topic-01","title":"調査事項概要","agenda":"調査事項概要","exchanges":[{"speaker":"新妻委員","kind":"確認","question":"１点、大井ホッケー競技場の整備についてというところで、確認します。聞きとれなくて申しわけありません。もう既に会場のほうには看板が掲げられていて、工事に入りますということが周知されておりますけれども、来年１月頃から工事に入るということですが、先ほど全面的にここが閉鎖されるというようなお話があったと思うのですけれども、これは、公園内には入れなくなるということでよろしいでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"先ほどご説明しました来年１月頃からの工事につきましては、あくまでもメインピッチの第一球技場だけの話しです。","id":"exchange-001"},{"speaker":"本多委員","kind":"意見","question":"資料の５枚になりますけれども、平成２９年度の開催周知事業というＡ３判の資料の（１）ですけれども、【仮称】ふくしまつり２０１７＆１０００日前フェスタということで、本日が１１３６日前なので、１０００日前は１０月末ごろになると思うのですが、資料に書かれている以外の１０００前フェスタについて現時点で固まっていることがあれば概要をお知らせください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"フェスタにつきましては、これまで平成２６年から続けてまいりました。今年は、委員ご指摘のとおり１０月２８日が、正式には東京２０２０大会の１０００日前に当たります。","id":"exchange-002"},{"speaker":"本多委員","kind":"質問・要望","question":"その下の（３）ブラインドサッカー出前体験教室で、それぞれ教室を５回開催予定なのですが、最終回はミニゲーム大会を実施ということで、これはまさに周知事業で、こういったことを充実していただきたいと思うのですが、この委員会はオリンピック・パラリンピック推進特別委員会ですので、ぜひこの委員会のメンバーの中からこういうミニゲームに参加するぐらいの。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"本日はこの特別委員会の、実質的に最初ということで、今後の運営の内容については後にしまして、この東京五輪の概要にかかわって幾つか、品川区の基本的な視点について、冒頭伺いたいと思います。そして、大会に向けて品川区として、ＬＧＢＴ差別をなくして理解を広げていく、具体的な事業について、現在のところの位置づけや方向性について、どういう状況なのかお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"それから今後、大会について様々な問題についても取り組んでいくと、大会組織委員会からはそういう話も聞いています。今の性的差別の問題等も、大会組織委員会と歩調を合わせて、品川区にできることを全てやっていきたいと考えています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"私はこの東京大会を、ＬＧＢＴの差別をなくし、スポーツを通じて誰もがありのままの自分で、その可能性に挑戦し、卓越した躍動感あふれる各種目を通じて、その姿に力をもらって社会に貢献する、こうした大会の成功につなげていきたいと思いますけれども、東京大会を通じて品川区のＬＧＢＴ差別をなくす準備状況について、先ほど歩調を合わせるというご答弁がありましたが、現在の進捗状況と。","respondent":"安藤文化スポーツ振興部長","answer":"そのような中で、オリンピック自体の考え方については、区独自でどこまでできるか、わかりませんけれども、大会組織委員会と協力を共に、連携しながら、進めていきたいと思います。それから、品川区は重要な２競技の開催自治体です。","id":"exchange-005"},{"speaker":"中塚委員","kind":"提案","question":"３年後ということで、区としてどこまでできるのか、しっかり準備をする期間があると思いますので、進めていただきたいと思いますけれども、私はＬＧＢＴについて、この特別委員会のオリンピック・パラリンピックの推進に関する区民のスポーツ振興や機運の醸成、この中でもしっかりと議論をしていきたいと提案したいと思います。なぜならば、スポーツには差別を克服する力を持っていると、私は思うからです。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"区といたしましても、区長をトップとした推進本部というものができておりますので、そうしたところできちんと議論をし、区としてどういうふうにしていくかという論議をしていきたいと思いますし、オリンピックを皮切りにということではありますが、オリンピックがないとしても。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはりスポーツには、ＬＧＢＴを含めあらゆる差別をなくす力を持っていると思います。東京大会の開催自治体である品川区が、例えばですけれどＬＧＢＴフレンドリー宣言を行って、そのための事業を準備して積極的に進めていって、その中で東京大会を開催して、誰もが祝福される大会として迎えられるように、今から準備を進めることを求めたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"ですから大会組織委員会として進んでいることがあると思うのですけれど、その歩調を合わせてというところで、そもそもの大会組織委員会の考え方なのかお聞きいたします。なので、やはりそういうところを推進しようという立場で、連携ということだと思いますけれども、ぜひそういった機運を、オリンピック・パラリンピック推進特別委員会から盛り上げていっていただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった中で多様性と調和というのは、どんな方でも様々な形で、オリンピックを契機に楽しんでいくということが基本となっていますので、そうした組織委員会の理念も踏まえつつ、区としても独自に検討してまいりたいと思ってあります。","id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"提案","question":"ここはあくまで特別委員会なので、常任委員会との仕分けはぜひお願いしていきたいと思います。これは意見だけです。それができるか、できないかは、決まっていないからまだわからないとしても、そういうものはいつ頃、区からもきちんと確認作業をして、期間中の練習会場、事前キャンプは別として、そういうことをどうしていこうと思われているのか、一つお聞きしたい。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"特に募集につきましては、一旦締め切らせていただきましたけれども、そういったアイデアにつきましては、オリンピック・パラリンピック準備課としてはいつでも大歓迎です、ともに協力して様々やっていけたらと思いますので、お話しいただければと考えているところです。","id":"exchange-009"},{"speaker":"藤原委員","kind":"質問","question":"きょうから１年始まるわけですから、改めてお伺いしたいんですけれども、品川区の立ち位置といいますか、今日の資料の中でも大会組織委員会からのホームページの抜粋した資料がありますね。資料のことだけならばいいのですけれども、連携はとれているのですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ほかに特別区の課長会、担当部長会等もございまして、そうしたところで東京都の幹部、あるいは大会組織委員会の幹部より、情報提供をしてくれることもあります。そうした意味で、連携はとれているところです。","id":"exchange-010"},{"speaker":"たけうち委員","kind":"質問","question":"区内開催競技のチラシですけれど、下のほうがちょっと切れていますよね。目が不自由な方用のお知らせだと思うのですけれど。これは、たまたまブラインドサッカーのところで入れているだけなのか、それともオリンピック・パラリンピックなので、様々な方が参加されたり、情報を必要とされる中で、今回これが入っている意味というか、位置づけというか、どういう考えで入れているのか、教えてください。","respondent":"中山障害者福祉課長","answer":"ホームページなどに載せるとき、ＰＤＦファイルではなくテキストファイルで載せると、今は品川区のホームページも音声対応になっておりますので、視覚障害の方が情報を取りやすくなっている状況です。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問・要望","question":"資料について伺いたいのですけれども、今回オリンピックの種目別の一覧が出たわけですけれども、パラリンピックの一覧というのはないのでしょうか。あればぜひ出していただければと思います。ホッケー競技場の整備費が４８億円と記載されておりますけれども、この内訳というのはわかりますでしょうか。そして、ビーチバレーボールの会場の資料はないのでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"１点目のパラリンピック競技の一覧ですが、こちらの大会会場一覧に、オリンピック競技と、一番右の欄にパラリンピックの競技が載ってありますので、こちらをごらんいただければと思います。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"パラリンピックのほうは、そうするとまだ種目決定していないということでいいのでしょうか。それを確認させていただきたいということです。ほかの会場についても、まだ資料はないということで、よろしいでしょうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"委員ご指摘のとおりです。","id":"exchange-013"},{"speaker":"中塚委員","kind":"質問","question":"品川区における障害者スポーツの現状について、ご報告がありました。伺いたいのは、こうした事業を通じる中で、障害がある方がスポーツを享受するに当たって、解決が必要な事柄とはどんなことだとお考えか、既に様々な事業をされていると思いますので、その実感や実態からも、障害がある方がスポーツを享受するに当たって、解決が必要な事柄とは何か、この点を伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"杖をつかれた方の横に一人つきまして、ここはどんな景色かとか、今は海のそばだから風が吹いているというように説明しながら、ウオーキングを楽しんでいる姿も見受けられました。介助というのでなく、障害をお持ちの方と一緒にスポーツを楽しむ、これが一番だと考えています。","id":"exchange-014"},{"speaker":"中塚委員","kind":"質問","question":"障害を持っている方にお話を伺うと、様々なスポーツをする環境をもっと整えてほしいという声をよく伺うのですね。今やっていることだけでなく、要するに見ている中で自分もやってみたいという思いになるということですけれど、現状、障害がある方が品川区でできるスポーツは何種目あるのか、これを広げていくにはどういうことが必要なのか、基本的な考えを伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"そういう意味で、私どもで知らないパラスポーツも、まだたくさんあります。そのため、何種目あるのか聞かれると、それこそ障害をお持ちの方ができるスポーツを皆さん考えているところですので、たくさんの種類ということしかお答えできません。","id":"exchange-015"},{"speaker":"中塚委員","kind":"確認","question":"、 また、東京２０２０大会のパラリンピックについて、障害者スポーツやバリアフリーについてですけれども、５月１１日にパラリンピックの準備状況を確認するため、国際パラリンピック委員会と大会組織委員会の事務折衝が行われた際、簡単に言うと都内ホテルのバリアフリー対策について、ほかの国際都市に比べて遅れているという指摘があったと、報道がありました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（真）副委員長","kind":"質問","question":"今の質問は、バリアフリーに関することで、昨年の委員会の中でも、バリアフリーについては担当課長に出ていただいて質疑しています。きょうは総括的な質問ということで、個別の問題はまた別の機会にするべきだと、それは委員長から諮ってもらわないといけないことですが、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"中塚委員","kind":"質問・要望","question":"一言だけよろしいでしょうか。選手にしても、日常的なスポーツの環境にしても、宿泊というのは大事なテーマだと思いましたので、意見を述べさせていただきました。ぜひ客室の確保や料金の設定など、幅広く障害者スポーツの振興に向けて、取り組んでいただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"本日は概要ということですけれど、時期的に今言っておきたいと思うのが、去年どなたかおっしゃったなと思ったのは、いながわ委員だったでしょうか、オリンピック・パラリンピックということですけれども、私はパラリンピックに入らないようなスポーツも、もっと全体的にみんなに理解していただきたいというのがあって、今年７月はデフリンピックの年です。もし何かお考えとかあれば、伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"委員会として取り上げるかは、正副委員長間で話し合わせていただきたいと思いますので、それは後日、また検討します。","respondent":"木村委員長、小川オリンピック・パラリンピック準備課長","answer":"ただいまのご意見ですけれど、正副委員長で検討させていただきたいと思います。ほかに何かありますか。なければ以上で、(2)障害者スポーツの推進に関することの、概要説明を終了いたします。こうした動きを踏まえ、品川区といたしましても、区独自の品川文化プログラムを実施したいという考えです。","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問・要望","question":"この文化プログラムとはどういうものかということを、もう少しご説明いただきたいと思い、質問させていただきたいと思います。この資料にあるオリンピズムの根本原則について、文化プログラムとはオリンピックの中でどういう意味として位置づけられているのか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"文化プログラムという正式な定義に基づかなくとも、各地域から始まり、国を挙げ、地方を挙げて文化的な要素のあるイベントを各場所で開催し、文化的に国として大きく盛り上がり、またそれを一過性のもので終わらせることなく、オリンピックが終わった後も。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問・要望","question":"この理念の具現化が、なぜ文化プログラムに位置づけられているのか、そこを伺いたいと思います。単なる手続とか、誰に承認を得るとか、そういうことではなくて、オリンピックを通じて文化プログラムはむしろとても大事に位置づけてきたわけですから、品川区としても具体化するに当たって、これがどういうものなのか、そこをしっかりと、現在の認識をご説明いただきたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"オリンピズムの根本原則に掲げられていることはこちらが全てですが、品川区といたしましては、伝統的な文化、新たに様々な文化的なイベントを既に組まれているところですので、そうした部分で全て品川区の文化ということを、このオリンピックを機会に魅力を発信し。","id":"exchange-022"},{"speaker":"藤原委員","kind":"質問","question":"課長の答弁を伺って、私もオリンピック・パラリンピックの文化プログラムという形は、とてもわくわくしている一人なのですけれども、オリンピック・パラリンピックということで担当する課長がご説明、答弁してくださっていますけれども、文化観光課長、ここは様々な意味で連携、かかわっていかないといけないと思うのですけれど、大枠で、具体的なことよりも今の思いと、どういうふうにかかわって、連携して。","respondent":"鈴木文化観光課長","answer":"日頃から、文化活動については区としても支援しておりますので、そういう活動をされている方にも情報提供をしながら、またあわせて支援をしながら、より多くの方に取り組んでいただくという発想で、今後もしっかり続けていきたいと考えております。","id":"exchange-023"},{"speaker":"伊藤委員","kind":"質問・要望","question":"大枠の確認です。申請して認定されるというお話ですけれど、ロンドンでは１７万件という話がありました。ということは、実際に例えば地方自治体、つまり品川区がプログラムを精査して、ＩＯＣ理事会には当然、承認を求めるのでしょうけれども、実務的なことは品川区がやっていくのかということの確認が一つです。それから、文化というのは非常に裾野が広いですよね。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"文化といっても様々なものがありますが、そちらのほうはできるだけ多く、品川区としては伝統的なもの、新しいもの、障害者芸術といったことも含めて、様々捉えていきたいという思いがありますので、既にやっている品川区の文化的なイベントとあわせ。","id":"exchange-024"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"教えていただきたいのですが、品川区は会場所在の地方公共団体で、申請をして公認プログラムマークがあると。別に私は、企業が営利活動をしてもいいと思うのですけれど、そういうことも含めると数多くのものが出てきたとき、区はオリンピック憲章に基づいてやるということですが、このマークの仕分けというのは、どういうふうに考えるべきですか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"この後、報告事項で、しながわ文化プログラムのマークにつきましてもご紹介いたしますけれども、品川区といたしましては、委員ご指摘のありましたとおり、区内の団体であればスポンサーであろうが、なかろうが、幅広い文化イベントをしている皆様に。","id":"exchange-025"},{"speaker":"石田（秀）委員","kind":"意見","question":"そういう考えをどこかで持たないと、申請するのが大変で、このマークをもらうのは大変です、あとは組織委員会が判断しますと言っているのでは、マーク一つのことで、盛り上がるものも盛り上がらないのではないかと思うので、そこら辺のハードルを下げる意味というか、それは区として強くやっていけると、今の答弁で大体わかったのですけれど、そう理解していて、いいのかどうか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"応援プログラムマークにつきましても、これから具体的なところが明らかにされていくわけですけれども、基本的に最初の主体登録は、町会ですとか商店街連合会が使う場合には、主体登録は必ず区を通じてやるというふうになってありますので。","id":"exchange-026"},{"speaker":"いながわ委員","kind":"質問","question":"既にオリンピック・パラリンピック準備課では、出前体験教室というのをやっていて、私もある小学校でこういうものをやっているのですかと聞いたら、いや、全然そんな話を聞いていないとＰＴＡの方が言っていて、全然周知されていないというか、そういう部分をもっと早くやるべきではないかと思うので、本日は概要なのでそれぞれ言いませんが、ブラインドサッカーに関しては。","respondent":"熊谷指導課長","answer":"先ほどの応援校につきましては、１０校のうちの１校となっていますので、私としてははっきり言って都内の６２市区町村の中で、オリンピック・パラリンピック教育を一番やっているのが品川区だと自負しております。","id":"exchange-027"},{"speaker":"伊藤委員","kind":"確認","question":"確認といいましょうか、大枠の質問ですけれど、表題が「オリンピック・パラリンピック教育」で、目標を３つ挙げられております。聞きたいのは、これは当然、オリンピック後も大切なことですよね。そうすると、例えば年間３５時間程度のオリンピック・パラリンピック教育学習は、今後どう展開していくのか。","respondent":"熊谷指導課長","answer":"そういったことが重要ではないかと思っていますので、２０２０年で終わるのではなく、その後を見据て教育を行っていくことが重要だと考えております。","id":"exchange-028"},{"speaker":"伊藤委員","kind":"確認","question":"だから３５時間程度のオリンピック・パラリンピック学習をどう展開していくのかとか、世界ともだちプロジェクトも、今までもやってきたでしょうし、これからも当然やっていかなければいけない事業なので、そのことの方向性と、それから区独自の教材の作成と活用もいいのですけれど、終わった後そのレガシーをどういうふうに活用していくかとか、やはり様々な観点で見ていかないと、教育は永遠のテーマだから。","respondent":"熊谷指導課長","answer":"３５時間程度のオリンピック・パラリンピック学習をということでありますけれども、これも非常に大変難しいところであります。","id":"exchange-029"},{"speaker":"中塚委員","kind":"質問・要望","question":"オリンピック・パラリンピック教育について、冒頭、歴史や意義を正しく理解できるようにというご説明がありました。ならば、オリンピックが平和の祭典である意味について、子どもたちに知る機会をぜひつくっていただきたいと思うのですけれど、どのように位置づけているのか、伺いたいと思います。","respondent":"熊谷指導課長","answer":"「ようい、ドン！」でも、そうした平和の大切さということで、特に聖火リレーを通じて１９６４年の大会では意味づけられていますので、そうしたことを通じて、子どもたちに伝えていきたいと考えております。","id":"exchange-030"},{"speaker":"中塚委員","kind":"質問・要望","question":"おっしゃるとおり、オリンピックの目的そのものが平和の祭典ですから、子どもたちの成長、発達に沿った学習教材を使って、進めていただきたいと思います。オリンピック憲章には、このオリンピックの目的は、人間の尊厳の保持に重きを置き、平和な社会を奨励し、スポーツを人類の調和のとれた発展に役立てるとされておりますので、子どもたちの学年に沿った教育を進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"藤原委員","kind":"質問・要望","question":"１点、指導課長もブラインドサッカーの体験をもちろんなさっていると思いますけれども、したことによって感じたこと、そして感じたことにおいて、どういうふうに子どもたちに、どういう思いというか、つかんでもらいたいか、あると思うのですけれど、ホッケー、ビーチバレーボールもありますけれど、私も自分で体験したことについてお伺いしたいので、その何をつかんでもらいたいかということを改めて。","respondent":"熊谷指導課長、小川オリンピック・パラリンピック準備課長","answer":"ブラインドサッカーは、ほとんど見えない状況で、全く視野がない状況の中でやっていくということで、本当にやってみると怖いなと、プレーをするどころではなく、実際にやってみることでわかることはたくさんあるのですが。そうした中で、常に私どもの事業につきましては、レガシーということを考えながら打ち出しているわけですが、教育委員会につきましても、こういった体験教室は引き続きやっていただきたいという思いもありますし。","id":"exchange-032"},{"speaker":"たけうち委員","kind":"意見","question":"オリンピック・パラリンピック教育の中で、例えば世界ともだちプロジェクトですとか、スマイルプロジェクト、様々ありますけれど、これを見ますと一つ一つが、先ほどとかぶりますが、認可プログラムの様相を呈しているというか、そういう面でいくと、文化プログラムに入ってしまうといけないのですけれど、学校単位とかクラス単位とか、そういう形でこういったものも工夫しながら教育を、学びながら。","respondent":"熊谷指導課長","answer":"学校として、学年として、文化プログラムに参加するということも重要だと思いますので、これから子どもたち、学校での文化プログラムに参加ということも検討してまいりたいと思います。","id":"exchange-033"},{"speaker":"たけうち委員","kind":"質問・要望","question":"私、昭和３８年生まれなので、３９年の東京オリンピックのときは一応生まれていましたけれども、何の記憶も残念ながらない中で、本当に今の子どもたちは非常に恵まれていると思いますし、ただ、私は２回経験できる、しかも今回はしっかりと様々なことを勉強した上で経験できるということは、非常にありがたいと思う中で、先ほど藤原委員からもありましたが、競技体験教室をもしやるようなら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"それで、私がお伺いしたいのは、せっかくここまでやってきたのであれば、例えば今、この教育を受けた子どもが、大学２年生ぐらいまでいきますか。では、優先的に競技の場で子どもたちにボランティアをやらせてくれるか、もしやらせてくれるようなら教えてもらいたいですけれども、競技開催地のボランティアはぜひ子どもたちに担わせていただきたいというのが１点です。お考えを教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"具体的にいつ決まるかですが、やはり大会組織委員会、競技連盟ともにまだはっきりした返事がございません。区といたしましては引き続きそうした思いを伝えていきたいと考えています。","id":"exchange-035"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ぜひそれはお願いしておくのと、ブラインドサッカーはプレ大会をやるということですので、その辺も含めて入れていただいて、ブラインドサッカー協会とは、今、いい関係にあると思いますので、ぜひ一緒にやっていただきたいと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-02","title":"しながわ文化プログラム","agenda":"しながわ文化プログラム","exchanges":[{"speaker":"いながわ委員","kind":"確認","question":"１点だけ確認したいのですけれど、「わ！しながわ」というのは、品川区が行うシティプロモーションの中で広報広聴課がつくって、その下に「しながわ文化プログラム」と入れたのだと思うのですけれど、要はローマ字や英語で表記されたものをつくったほうがいいのか、それともここは日本ですから、日本語を理解してくださいということでいくのかどうかという思いがあります。「わ！しながわ」も「ＷＡ！","respondent":"小川オリンピック・パラリンピック準備課長","answer":"現在、しながわ文化プログラムにつきましては、このマークでまず行かせていただきたいと考えています。当然、シティプロモーション担当の「わ！しながわ」と連携して、このロゴマークを作成したわけですが、まずこちらを浸透させていきたいと考えています。","id":"exchange-037"},{"speaker":"つる委員","kind":"質問","question":"今、いながわ委員からもありましたが、ロゴマークの決定過程を教えてください。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"この事業を制度設計いたしますとき、まず、せっかく「わ！しながわ」というマークがありますので、このマークを活用したいということと、しながわ文化プログラムというものを全面に出したいということから、下につけて、このような形で区として決定したものです。","id":"exchange-038"},{"speaker":"つる委員","kind":"提案","question":"せっかく文化プログラムとしてやるわけです。３年あるわけですから、これで一つ決定し、今後変わらないというふうになるかもしれないですけれど、品川区独自の文化プログラムですから幅広く様々できると思うのです。そうした意味で、先ほどいながわ委員からも提案がありましたけれど、基本ベースはこの「わ！しながわ」では、今までと何か違うのですか、下に追加していますと。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"そういった中で、最終的にこちらに決定したです。そうした中で、まずはこちらのマークで出発させていただきたい。今、いただきましたご意見につきましては、今後の参考にさせていただきたいと思います。","id":"exchange-039"},{"speaker":"つる委員","kind":"質問","question":"候補が幾つかあったということで、少し安心しました。それならば、最初に複数の案があったと説明がないと、これがポンと出てきて、そうですかということになるのでは、やはりアイデアは幾つか、当然庁内も含めて、区民公募なども含めて、ある程度あって、それでこういうふうになったというのであれば、なるほどそういう意識を持ってやっているのだなとわかります。やはり説明の仕方もあると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"石田（秀）委員","kind":"意見","question":"かぶる部分もあると思いますが、私はこの「わ！しながわ」というもの自体の、しっかりとした費用対効果というか、周知の効果というか、そういうものがされていない。されていない中で、もう一点言えば、シティプロモーションの中でも動画にしても、わけのわからないものをつくらせて、よくわからないうちに終わったのかなと思うぐらいで、そういう中の一つが「わ！それだけ言っておきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-041"},{"speaker":"中塚委員","kind":"質問","question":"様々ご意見を伺いましたけれど、オリンピックをやるに当たって文化プログラムをやると。そこを伺いたいのです。そのコンセプトに沿ったロゴをつくるのであれば、わかるのですが、従来、自治体のＰＲ用につくったものをそのままオリンピックに、少し手を加えて使うということが、果たしてよいのかと率直に疑問に思うのですけれど、その点だけ伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"こちらのロゴマークに、例えば２０２０ですとか、オリンピック・パラリンピックという文言を使うと問題になります。ただ、文化プログラムという単語自体に知的財産権はございませんので、しながわ文化プログラムという表現については何ら問題もございません。","id":"exchange-042"},{"speaker":"藤原委員","kind":"質問","question":"だから、やはりこのロゴマークもいいかもしれませんけれども、本当にこのロゴで満足されているのでしょうか。本当に１００％満足してやっているのですという思いならいいですけれども、もう少しデザイン的に、文化という意味であるならば、もう少し考えて、私にはデザイン的な才能などないから、このように言えてしまうのかもしれませんけれど、ふと思ったので、その辺について、どう思われますか。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"ただ、今回の文化プログラムのマークにつきましては、組織的にこういったことで決定させていただきましたので、まずこれで出発させていただきたいと思います。委員ご指摘のご意見につきましては、貴重なご意見として承りたいと考えています。","id":"exchange-043"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"具体的に、視察について希望を述べたいと思っています。ＮＰＯ法人虹色ダイバーシティです。代表は村木真紀さんですけれども、この間の活動実績を見ても、視察を行い、オリンピックとＬＧＢＴについて話を詳しく伺って、議論を深めることができたらと思いますので、正副委員長でご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"鈴木（真）副委員長","kind":"質問・要望","question":"冒頭にＬＧＢＴのお話がありましたけれど、先ほど石田秀男委員からもお話がありました。これは総務委員会、教育委員会も絡んでまいります。その辺をよく踏まえた上で正副委員長で検討してまいりますので、この場で内容的に、視察に行きますという部分でもお答えはしにくい状況ですので、その辺ご理解いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"中塚委員","kind":"質問・要望","question":"もちろん、この場で返事を求めているのでなく、正副委員長でご検討いただきたいという趣旨です。このテーマは、品川区でいえばオリンピック・パラリンピック準備課、人権啓発課、教育委員会、様々かかわるので、特別委員会が一番ふさわしいのではないかと思いますので、ご検討いただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"石田（秀）委員","kind":"提案","question":"私ももう一度勉強しますが、先ほど言いましたように区民の約半数が参加をするイベントというものを、そういうことをちょっと調査して、そこの視察にどういうふうにやったらこういうふうになるのだというのがわかってきたら、提案しますので、それも入れていただけると、機運醸成にはおもしろいかなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/400453?Template=document&Id=6516#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":44475,"voices":141}},{"id":"h29-20170615-10","meetingId":"h29-cm06","date":"2017年6月15日","dateIso":"2017-06-15","committee":"議会運営委員会","time":"午後１時００分～午後２時０７分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","topics":[{"id":"topic-01","title":"議長会への要望事項","agenda":"議長会への要望事項","exchanges":[{"speaker":"石田（秀）委員","kind":"質問・要望","question":"最初の、埋蔵文化財の管理、保存、活用について国の補助制度の拡充を求める要望というのは、これは都はあまり今このことについては関係がないというか、国と各地方自治体というところがありますので、国に宛てて出させていただこうかと考えていますが、最終的には、我々はこれを４点書かせていただいて、昨年は自民党もオリ・パラも出したのですが、ここへ出してこなかった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"塚本委員","kind":"質問・要望","question":"３点目は、これは新しいものですけれども、幼児教育の無償化に関する要望ということで、今、国のほうでもこういった議論が大きく進んでいる中で、特にここに関しては、国・都に強く要望していきたい、しっかり実現してもらいたいという思いを込めてですけれども、０～２歳児を含む幼児教育の完全無償化というところでの要望をさせていただいておるところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"質問・要望","question":"１点目は、関係区と十分協議すること。２点目には、騒音とか落下物とか、様々な可能性があるわけですから、その影響を明らかにすること。どうしても交付金があるということで、差し押さえが各自治体で随分力を入れて取り組まれるようになって、かなり多くの区民の皆さんを苦しめているという実態がある、そういうところは見逃せないところなので、きちんとこういう交付金制度はやめると、そういう要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"皆さん、ご承知のとおり、保育園の待機児童はずっと課題になっているので、これは質と量とともに改善をしなければいけないということで、要望に出させていただきました。次に、オリンピック・パラリンピックですが、これも引き続き、オリンピック・パラリンピックの開催に向けた環境整備等については、喫緊の課題だということで、要望を出させていただきました。以上４点です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"我々は、２点出させていただきました。１点目は、学校教員の人事権と教員給与、品川区に東京都から移譲してほしいと。理由は、品川区は独自に小中一貫教育、義務教育学校をスタートさせたのですが、その中で教員の出入りがこんなに多くては、できるものもできなくなると思いますので、むだな経費とむだな時間は省くべきだと考えまして、このように要望書を提出していただくということを決めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"通るに際して、これとこれとこれをしなさいという具体的な要望で、通過することは、上空を飛行することはいいというふうなことが前提のことになっていると私は読めたのですけれども、そこの点についてはどうなのかという、この２点を伺いたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"これは地域で言うならば、こういうことをやってくれ、地域のためにこういうことをしてくれなければだめだということも、我々はご意見として聞いている部分で、では、その部分についても我々としては触れて、それは特別区の議長会に出していただいて、地域事情も理解をしてほしい、それに伴って国、東京都に要望を上げてほしいということで、こういう案文にしたという理解をしていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"たけうち委員","kind":"質問・要望","question":"これはあくまでも財政支援を国、都に求めているわけでして、当然、新規開設と、既存施設でも、南委員おっしゃったように、大分弾力化をできるところまでやった経緯があります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"南委員","kind":"確認","question":"さっきも言ったように、きちんと文言整理をするというところはもちろんあるわけですけれども、それまでの間に、この委員会として、例えばさっき私が指摘させていただいた定数拡大のこの部分については、考え方がみんなで共通して、そういうことだったらいいよねみたいになっていって、報告になって、議長のところで整理して提出する、そういうことになるのだろうと思うのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"意見があったら手を挙げて言ってくださいとさっきから言っているから、そうしてください。父母の皆さんに、区民の皆さんに、品川区議会はもう少し私たちの状況を知ってもらいたいというふうに、そんなふうに変な意味で伝わってしまうといけないので、だから今、多くの皆さんの求めていることは、保育園の増設です。そういうところを踏まえて要望を上げていくということが大事なのではないかと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"大前提として、南委員にお聞きしたい、共産党の方にももしあれだったらお聞きしたいのは、議長会要望をやりましょうと、そのときに、まず我々がしたことは、議長が今まで何度も議運に出られて、議長会でこういうことがありました、資料は事務局にあります、どうぞそれを見ていただければと、全部を説明することはできないのでということで、我々はその資料を事務局にお願いして見せていただいて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"南委員","kind":"質問・要望","question":"聞かれたので発言したいと思います。そして、私が伺いたかったのは、この場面で、この議運で一致できることを出すという、そういうことではないのかというふうに聞いたのですけれども、どうも今の説明では、違うみたいな発言もありますけれども、一致しなくても、議長の裁量のところで出すという、そういうふうになって、そういう経過があるというふうに理解していいのですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"渡部委員長","kind":"確認","question":"そのように理解していただいて結構です。こちらでの意見が終わりましたら、後ほど私のほうでもあらあら最終的な意見は述べさせていただいて、一応こちらの議運の中での話し合いはこのような形ですねというご確認をさせていただいて、議長に報告を上げる、そのような流れを考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"南委員","kind":"質問・要望","question":"やはりこの品川区議会の要望としてまとめて出すわけですから、偏った内容であってはならないと思うのです。要望事項の１つの文言に対して、提出を受けた機関は、これが品川区議会の総意なのだという受けとめを当然するわけです。ですから、そういうことで温度差がこんなに違うものを１つのところにまとめて出すということは、私はこれは正しいやり方だと思わないのですけれども、それはどうですか。","respondent":"渡部委員長","answer":"従来どおりの進め方を、従来の手続きを踏んで説明していますので、特段そのようなことはないと思いますし、私も過去何年間か議運に出ましたが、全く同様な議論の中で議長のほうにおまとめいただいていますので、特段今年初めてということを今やっているわけでもございません。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"だから、この扱い方については承知はしているつもりでいます。ですから、失礼な言い方はやめていただきたいと思います。それで、羽田の問題に戻っていいですか、さっき言わなかったので。石田委員が、昨年は要望に上がらなかったので、品川区議会として自民党会派から上げたという、そのことはそういうふうに受けとめております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、先ほど言ったように、議長会に出た書類、それから経緯があって、どれを国、東京都に出した、どういう文言修正があった、その書類は読んだのですかとさっき聞いたのに何も触れられていないから、そういうことになってしまうのだけれども、読んでいらっしゃれば、今みたいな発言はないと思うのですよ。議長会で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"だから、それについて我々としては、品川区として、当事者区でもあるので、それは自民党の中でもどうしようかと思ったけれども、それは自民党の中で、去年は結局、国、東京都に要望は届かなかったけれども、どうしようかと自民党の中で考えて、だけれども、やはりこの部分については言っていかなくてはならないだろうということで我々は要望をさせていただいたと、そう言ったのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"今の石田委員の最後に発言されたような、そういう中身で私は受けとめて、先ほどからの発言は聞いていたつもりです。ですから…。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"南委員","kind":"意見","question":"やはり委員会として、本当に粛々と言うところは言う、しかし、そうではない意見は出し合うというところで、委員長を通して議論を進めていかないとまずいと思うのです。だから、そのことを私は言っているのです。だから、それはきちんと発言を聞いてから言ってください。手を挙げて言うように、そういう議会にしましょうよ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"南委員","kind":"質問","question":"羽田の問題です。先ほど石田委員がおっしゃったとおり、私もそういうふうに認識をして伺っておりました。したがって、払拭に努めることが一番だというふうにおっしゃっていたわけですけれども、その不安を払拭させるのは、それはもちろん私たちも同じように考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"南委員","kind":"質問","question":"私自身は、今回のこれを提出するに当たって、過去のものは見ていません。しかし、この間の議運メンバーがずっと積み重ねて見てきている、そういうことを前提にして議論をし、そして今日に臨んでいます。したがって、赤ペンも入れていないし、コピーもしていない、そういうことであります。よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"意見","question":"南委員に、共産党は、今、飯沼委員が３年もいらっしゃったからということなのだけれども、議長が全てここで話をできるわけではなくて、資料を事務局にあるので読んでください。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"石田（秀）委員","kind":"意見","question":"それを、先ほど来言ったように、ほかの委員も議運に出ていたと言うけれども、そういう方々が、きちんとそういうことも理解されているなら、共産党として、そういうものをとって、そういう経緯も踏まえることは、別に議長を経験しようがしまいが、会派としてやれるわけであって、そういうことをやってもいないで、私はやっていないからどうだみたいな発言はおやめになったほうがいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"私は、羽田の問題で言えば、今、石田委員がおっしゃった、こういう項目は、それはそれとしてわかるところです。そこのところはわかっていただきたいと思います。それで、それについて全く触れずに、議長を経験したどうのこうのということを同じことを繰り返すのは、やはり不適切だと思いますので、だから、やめて、そして建設的な話し合いをしていくべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-024"},{"speaker":"飯沼副委員長","kind":"質問・要望","question":"もう１点なのですが、高齢者のところもたくさんご意見が上がっていて、一致点は多いと思うのですが、共産党は要望に挙げています４点目「特養ホームの介護報酬を元にもどすこと」と書いてあるのですけれども、特養の建設をするに当たっても、働いている職員の方々の処遇改善をするに当たっても、やはりこの介護報酬が引き下げられてしまったがために、今、特養が、法人についても、企業についても。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"第２回議会報告会報告書","agenda":"第２回議会報告会報告書","exchanges":[{"speaker":"南委員","kind":"意見","question":"そのときは、そういう方が来るということで設置をするのに、開会時間が若干ずれるということになっていくことも予想されるのではないかと思うのですけれども、その辺はどうなのか。だから、どういうふうに、区民の方がおいでになるのは別に何時までに来なければいけないとか、そういう制限をするものでもないのかと思うので、どんなふうに考えていらっしゃるのか。","respondent":"久保田区議会事務局長","answer":"事務局としましては、できるだけぎりぎりで来ましても、開会時間に影響のないように、設置は急いで行いたいと思ってあります。","id":"exchange-026"},{"speaker":"南委員","kind":"質問","question":"当然そういうことだろうと思うのですけれども、例えばこういう設備を用意しましたのでどうぞというふうな案内をホームページ等々でするわけですよね。そのときに、設置にある程度の時間がかかるかもしれないので、できるだけお早めにみたいな、そんなことは案内してはいけないのですか。","respondent":"久保田区議会事務局長","answer":"ホームページには、時間がかかるというか、できるだけ早く来ていただければということのご案内はする予定です。ホームページの記載の方法についても、わかりやすく使いやすいということをモットーで今までやってありますので、そういった工夫は当然ながらやっていきます。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/560108?Template=document&Id=5228#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":22395,"voices":74}},{"id":"h29-20170705-10","meetingId":"h29-cm07","date":"2017年7月5日","dateIso":"2017-07-05","committee":"議会運営委員会","time":"午前１０時３０分～午前１０時４９分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/560108?Template=document&Id=5230#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":6879,"voices":29}},{"id":"h29-20170706-10","meetingId":"h29-cm07","date":"2017年7月6日","dateIso":"2017-07-06","committee":"議会運営委員会","time":"午前１１時００分～午前１１時０２分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/560108?Template=document&Id=5232#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":880,"voices":7}},{"id":"h29-20170710-6","meetingId":"h29-cm07","date":"2017年7月10日","dateIso":"2017-07-10","committee":"区民委員会","time":"午前１０時００分～午前１１時０７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を18件抜き出しています。","topics":[{"id":"topic-01","title":"臨海部広域斎場組合の火葬料の改定","agenda":"臨海部広域斎場組合の火葬料の改定","exchanges":[{"speaker":"中塚委員","kind":"提案","question":"住民負担を増やすという内容だと思うのですけれども、臨海部広域斎場組合議会において、８月に開かれますけれども、品川区はこの提案について賛成をするのか。私は反対すべきだと思いますけれども、その点いかがかというのが一つです。５区でそれぞれ分担をしていると思いますので、品川区に限定すると幾らになるのか。品川区に照らしたときに幾らになるのか、その金額を教えていただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"８月の組合議会に提案させていただいて、品川区は賛成する予定ということで事前に区長にも報告しています。５区全体の負担増です。概算で３,０００万円強増額という形になりまして、各区の負担で申しますと、大体数百万円から１,０００万円台という形になります。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問","question":"品川区は賛成ということですけれども、なぜ人件費および電気料金等の上昇を住民に転嫁をするのか、それに賛成なのか、その理由を伺いたいと思います。５区でいうと３,０００万円強、各区でいうと数百万円から１,０００万円ほどの負担増ということですけれども、こうした住民への負担を転嫁しないと安定した運営が維持できないということなのか伺いたいと思います。","respondent":"提坂戸籍住民課長","answer":"ほかの４区の考え方も基本的には似たような形で区長のコメントをいただいているところでございまして、結局皆さんいつかは亡くなるのですけれども、利用する方、利用しない方に、そのときに葬儀の主催者の方に公平にご負担いただくというスタンスです。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"人件費や電気料金の負担をなぜ住民に転嫁するのか、冒頭は上昇に伴いということでしたけれども、先ほどは使う人、使わない人のバランスという話がありましたが、つまりはどうして今回の改定を行うのか、改めてなぜ住民に負担を求めるのか、ご説明いただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"長期的には、先ほどもご説明しましたが、開設後１３年を経過してまいりますので、今後火葬の件数というのは１０年、２０年ずっと増えていくという想定が出ております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問・要望","question":"私はこうした施設は社会的に必要なものだと思いますので、それを利用する、しないで住民に負担を求めるというのは間違った考えだと思います。最後に一点、先ほど赤字になると言い切ったのですが、そこについての説明がなかったのですね。今回の上昇分を住民に転嫁しないと赤字になるとおっしゃったわけですから、具体的にどう赤字になるのかご説明いただきたいと思います。","respondent":"提坂戸籍住民課長","answer":"その方とのバランスということも考えて利用する方には相応の負担をお願いしたいということで、先ほどの赤字分ということですと、平成２８年度の件数で割り返しますと３,０００万円強の赤字が出ますので、その辺を利用する方に公平にご負担いただきたいということで。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"最後に一言。５区全体で３,０００万円程度の赤字だと、これは当然自治体が負担すべき役割だと思います。先ほどから使う人、使わない人とありましたけれども、品川区の公共施設を見ても、一生のうちに１回も使わない公共施設もあれば、よく使う人もいれば、それは細かく見ればありますよ。なので、使用する、しないで住民の負担を求めるという考えは改めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"組織区５区の区民の方が６８％は民間斎場ということですよね。品川区民の数字を教えてください。それと、人件費および電気料金等の上昇に伴いということですけれども、具体的に人件費の部分はこれこれこういう方たちの人件費がどう上がったから、上がるからということも説明していただけますか。具体的に教えてください。","respondent":"提坂戸籍住民課長","answer":"ごめんなさい、平成２７年度と平成２８年度については大体横ばいなのですが、今後いろいろな人件費のほうで負担というのが増えるので、その辺の負担増が見込まれるところがあるので、平成２９年度の金額が今ちょっと出ていないのですが。","id":"exchange-006"},{"speaker":"藤原委員","kind":"質問・要望","question":"それで、なぜこういうふうに伺うかというと、私も中塚委員とちょっとというか今回だけは同じで、こういうところこそ誰もが、やはり生老病死って四苦八苦の四つ目の四苦八苦だから、生老病死は避けられないから、皆さんが亡くなって、日本の中全体という言い方だと地域的にはまだ土葬があるところもあるかもしれないけれども、基本的には火葬するわけですから、誰もが火葬するわけですから。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"人件費を含む総務費ですが、先ほど申し上げた３５０万円程度の増になっておりまして、それ以外の衛生費等も含めますと、全体で平成２６年度と比較しまして平成２８年度の決算額が２,２００万円増となっています。これから１日の炉の回転数等が上がってきますと、もちろん委託の部分、先ほど人件費とご説明しましたけれども、そういうものも含めてそういったことに対する備えですとか、それからこの適正な価格に設定するということは。","id":"exchange-007"},{"speaker":"藤原委員","kind":"質問・要望","question":"部長の説明でよく理解できました。この資料の中で「この間、人件費および電気料金等の上昇に伴い」と出ているから、この２つ、電気料とか人件費という形で伺ったのですけれども、私も地域というか知り合いの方にやはり聞かれる、いつの間にか上がっちゃったねというときに、やはり議員ですからその辺きちんと説明をしなくてはいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"塚本副委員長","kind":"質問・要望","question":"そういう中で、使っていない方に配慮しなければいけないという考え方がどういうところなのかというをもう少しお考えを聞かせていただきたいのと、率直に言うと、そういう考え方はあまりこの斎場に関して言えば聞かないので、あまり必要ない考え方かなと思うのですが、いかがでしょうか。","respondent":"提坂戸籍住民課長、堀越地域振興部長","answer":"その辺はちょっと存じかねますけれども、やはり率直に利用料金を比較させていただいて約倍ぐらいの開きがありますので、その辺でバランスを取らするということで、臨海斎場を利用していただく方については。ちょっと今説明させていただいたのですが、施設の使用料の考え方というのはいろいろあると思うのです。原価ですとか今後の需要というのは先ほど私のほうからも説明させていただきました。","id":"exchange-009"}]},{"id":"topic-02","title":"東京２０２０公認文化オリンピアード「品川薪能」の開催","agenda":"東京２０２０公認文化オリンピアード「品川薪能」の開催","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"もう一つは、ぜひやっぱり多くの方に来ていただきたいという意味では、子ども料金の割引とか、障害がある方の割引とか、なかなかこういう文化・芸能・芸術に触れる機会のない方への配慮、親子スペースをつくるとか障害者スペースをつくるとか、いわゆるバリアフリーのことも含めてそういった方、今回第四回目か、そういう視点も加えながら名実ともに誰もが多くの方が。","respondent":"鈴木文化観光課長","answer":"野外ステージの設営についても、実は能の舞台をいろいろ野外で行ったり仮設でやったりする事業者の方がいらっしゃって、ノウハウをお持ちなので、今回は前日に搬入と設営をしまして、当日リハーサルや本番、次の日に撤収という３日間で済むということで。","id":"exchange-010"},{"speaker":"中塚委員","kind":"質問・要望","question":"ぜひダイナミックに魅力を持って進めていただきたいのと、もちろん周辺の方の理解を得ながら、協力を得ながら進めていただきたいということと、今回はかなわなかったけれども磁気ループだったり障害があったり外国籍の方だったり非常に幅広い方に、やはり行政が関わって企画をするというならではの支援といいますか、そういう企画といいますか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"始まる本当に一、二時間前とかに曇ってきたなというときに、どこに問い合わせればいいのかというのがすぐにわかるように。何かこれだとホームページも品川区のホームページは見づらかったりもするので、ホームページの一番トップにあるとか連絡先がどこかすぐにわかるようにということとか、その周知などについて伺いたいと思うのですけれども。","respondent":"鈴木文化観光課長","answer":"当然、細かい対応ができるように区のホームページに限らず対応するのと、それから当日はやはり比較的この時期は天候が安定している時期ではあるのですけれども、今気象レーダーとかも１時間単位で見られますので、少しでも雨のリスクがある場合には。","id":"exchange-012"},{"speaker":"藤原委員","kind":"質問","question":"予算額が５００万円ですけれども、これは具体的にどういう形か教えていただければ。","respondent":"鈴木文化観光課長","answer":"それと、あとはチケットの売上げと喜多能楽堂の負担で約６００万円程度、そのあと残る半分近くを区で分担ということで、区も共催で実施するという、ほかにも幾つか似たような事業はありますが、そのスキームを使って実施するものです。","id":"exchange-013"},{"speaker":"藤原委員","kind":"質問","question":"私も開催することはすばらしいと思うのですけれども、区外の方や外国人にも多く鑑賞してもらいたいということなのですが、区が税金で５００万円出すことですよね。区民ではない方にも区民の税金を使っていくという基本的な考えなのですけれども、その辺はこれからも文化という意味においては区外の方にもお金を使っていってもいいではないかという考えを基本的にしていくのでしょうか。","respondent":"鈴木文化観光課長","answer":"それともう一つは、今回Ｓ席４,０００円、Ａ席でも３,５００円ということで、ご覧いただく方には一定程度の負担をいただくということで、その売上げも事業実施の経費に繰り込むということで。","id":"exchange-014"},{"speaker":"藤原委員","kind":"質問","question":"チケットも買ってくださる、全て無料ではないということで、ちょっとしつこいのですけれども、この報告事項の前で、誰でも亡くなると、先ほどそういう質問をさせていただいて、誰でも亡くなるということで税金を投入するべきということで質問をしていた流れになってしまうのですが、課長、今回税金を５００万円使って、この事業すばらしいですよ、チケットも買っているわけですけれども。","respondent":"鈴木文化観光課長、小川オリンピック・パラリンピック準備課長","answer":"あわせて、先ほど申し上げましたように、区の魅力発信や区のこういう文化に関する取組みというＰＲ、また外国人の方も含めた来訪者の増加ということで、その目的に対しての投資ということで考えておりますので。ご質問の文化オリンピアードのこちらのマークですが、こちらにつきましては課長のほうから説明があったように組織委員会のほうでやっている参画プログラムという中での事業の一環ですが。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"ケーブルテレビでの放送というのはあるのでしょうか。私、すごく個人的な意見になってしまうのですけれども、見に行きたいのですが、やはり未就学児の子どもがいるから見られないというのと、あと家族がいるとやっぱりその分席料も上がってしまってなかなかお高くなってしまって。でも、すごく見たい気持ちもあるのです。なので、ケーブルテレビでの放送はどうなのかなと思って、そこら辺を教えてください。","respondent":"鈴木文化観光課長","answer":"ただ、先ほどの中塚委員の話にもありましたように、お子様や小さなお子様連れの家族の方にもご覧いただく機会というのは文化振興の上で必要ですので、これは薪能に限らず、能楽堂さんでやっていただく事業や区の区民芸術祭でやるこれらの中で。","id":"exchange-016"}]},{"id":"topic-03","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、区民委員会にかかわる項目","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"自民党からの質問で、文化観光で歴史館が出たと思うのですけれども、学芸員を具体的に人員配置みたいなご答弁が出ていたと思うのですが、ストレートにこれから品川歴史館の学芸員はどうなっていくのか、具体的に伺いたいのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問・要望","question":"ちょっと大井が立て続けにこういう形で出ていて、やはり私たちの仕事というのは区民の安心・安全というのも大切な仕事の一つですから、大井署管内といいますか、立て続けに出ているのですが、解決していただきたいという思いはあるのですけれども、その辺についてお伺いできればと思います。","respondent":"菅生活安全担当課長","answer":"区としても、警察あるいは町会のパトロール等と連携をしながら、新たに犯罪が発生しないようにまた今後防犯対策を進めてまいりたいと考えています。","id":"exchange-018"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/681247?Template=document&Id=2784#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":19591,"voices":51}},{"id":"h29-20170710-7","meetingId":"h29-cm07","date":"2017年7月10日","dateIso":"2017-07-10","committee":"厚生委員会","time":"午前１０時００分～午前１１時４３分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件抜き出しています。","topics":[{"id":"topic-01","title":"はじめに、予定表の１、議案審査(1)第４７号議案、品川区社会福祉基金条例の一部を改正する条例","agenda":"はじめに、予定表の１、議案審査(1)第４７号議案、品川区社会福祉基金条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"この条例の運用益金の処理というところでは、運用から生ずる収益は一般会計に入れて、その目的を達成するための経費に充当するということなのですけれども、その処分というふうなところ、目的に必要な場合は処分することができるということで書かれているのですけれども、目的の高齢者福祉の進展のために活用されるというところでは、具体的にどのようなときに活用されることがあるのかということだけ。","respondent":"大串福祉計画課長","answer":"そういった形で、基金の使い道に関しては、今後ともさまざまな形で検討を加えながら、一番ご遺族の、このご寄贈いただいた方のご意志に沿うような形、これが一番重要かと考えていますので、そうした中で検討を重ねていきたいというふうに思っているところです。","id":"exchange-001"},{"speaker":"鈴木（真）委員","kind":"確認","question":"今の、ご意志に基づいてというお話があったのですけれども、基金型にするか使用型にするかというのは、受けるときに確認をするということで対応するのですか。そこだけ確認をさせてください。","respondent":"大串福祉計画課長","answer":"とはいえ、やはりご遺族のご意向としては、名前を残してということをいただきましたので、果実運用型と取り崩し型、これを併用するような形で、条例化については対応させていただき、今後、何らかの形で使うときには、そういった形でご遺族の方に相談をさせていただきながら。","id":"exchange-002"},{"speaker":"若林委員","kind":"確認","question":"中身そのものとは違うかもしれませんけれども、少し確認をさせてください。","respondent":"大串福祉計画課長","answer":"２つご質問いただきました。こちらはまず２月１６日にいただいたところです。寄附の申し出がありまして、一旦、寄附金という形で充当させていただきました。","id":"exchange-003"}]},{"id":"topic-02","title":"第４１号議案、平成２９年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第４１号議案、平成２９年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"浅野委員","kind":"質問・要望","question":"今回の補正予算について少し質問させていただきたいのですが、国民年金関係届出書等の電子化ということで、合理化が図られるということと、あと紙で送ることのリスクと言うのでしょうか、そういうことも削減をできると聞いております。その代替として電子化で、ＣＤですとかＤＶＤですとかと言われておりますけれども、そういうような媒体に移すことによりまして合理化も図れると伺っております。","respondent":"三ッ橋国保医療年金課長","answer":"他市区町村の状況の関係ですけれども、２３区で申し上げますと、実際に実施している区は５区ございまして、港区、江東区、足立区、板橋区、千代田区となっております。そのほかの部分につきましては、これから検討中や、実施していく予定という状況になっております。","id":"exchange-004"},{"speaker":"浅野委員","kind":"質問・要望","question":"こちらの補助ということで、１人当たり塾代が小学校４年生から中学校２年生までは１０万円が上限ということで、一体これは今現在何人受けておられるものなのかということと、小学校４年生から中学校２年生までの何％の方が受けられているのかということを教えていただきたいのと、中学校３年生につきましても１人当たり１５万円から２０万円に上限を拡充、こちらの見込みはどのように考えられているのか。","respondent":"矢木生活福祉課長","answer":"高校１年生、高校２年生については５９人、高校３年生、高校４年生については、高校４年生は定時制、通信制になりますが、これが合わせまして３２人で、それぞれ７割前後の方のお申し込みを想定しています。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問・要望","question":"中学校３年生につきましては、７割から８割程度を想定されているということで、これは随分高い想定かと考えていますけれども、それだけの需要が今のところありそうだということなので、こちらもしっかりと対応していただければと思います。続きまして、ＡＥＤの設置補助ですけれども、２７浴場ということで伺いました。この点に関しまして、今後の浴場の動向でしょうか。この点について教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"生活保護費のほうは我々も要望していた部分の中で拡充を図っていただきまして、ぜひ進めてもらいたいと思います。うまくコミュニケーションをとって、利用できる人に対しては実施できるようにお願いしたいということを要望します。それからＡＥＤ設置に対して、公衆浴場の方も当然いろいろな研修を行っているのかと思うのですけれども、その研修についてどう考えているか、この２点をお願いします。","respondent":"川島健康課長","answer":"ＡＥＤの設置、私どももできるだけ早くと考えていますが、あまり制約といいますか縛りをかけないようにということで、こういう表現をさせていただいたのですが、議決いただきましたら速やかに購入していただくようにお話をして、なるべく早く設置できるように。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"質問","question":"補助金ですから、区が買うのではなくて、先方が買うということで、この金額で個別に買っていくのですか。逆に言うと、区が買ってしまったほうが、数が多ければ金額的にもいいのかと思ったのですが、それはもう全て個々の浴場が自分たちで買う、契約は自分たちでやるということになるのですか。","respondent":"川島健康課長","answer":"今回の助成金は浴場組合に対してのものですので、浴場組合でまとめて購入して、浴場組合のほうに私どものほうで助成金を支出するという形になっております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"国民年金システムなのですけれども、紙媒体を電子媒体にということで、今回、１５届出書が対象で、まだ対象外の帳票などがあるということなのですけれども、幾つぐらい対象外というのがあるのかということと、その対象外というのは今後電子媒体となっていくという見通しがあるのかということが１点、それから電子媒体の報告書は、今度品川区で作成することになるということで。","respondent":"三ッ橋国保医療年金課長","answer":"その中身ですけれども、例えば資格関係の訂正・追加ですとか、細かい部分がございまして、そのような部分は電子媒体化にすぐ対応できないとなっております。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それで先ほど、対象者について、塾のところは言われたのですけれども、大学受験料というところは何人ぐらいが対象というふうに考えられているのかということと、それからこの塾代の年間１人当たり上限額、１０万円、２０万円、１５万円と、受験料の８万円も含めて、この額というのは、今回東京都のほうからの補助金が１０分の１０ということなのですけれども。","respondent":"矢木生活福祉課長","answer":"２点のご質問でございました。大学受験料の対象者数ということで、先ほど申し上げた高校３年生、高校４年生、３２名が受験料の対象者数です。次に２点目、塾代の上限額が都の基準かという質問ですが、ご指摘のとおりです。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからあと、生活保護世帯で、高校を卒業した後に大学や専門学校に進学して、卒業まで行くというのが本当に相当大変なことだと思っているのですけれども、今の制度でどこまでそれを支援する仕組みになっているのか、またそれを支援するにあたり課題になっていることがどういうことなのかについてもお聞かせいただきたいと思います。","respondent":"矢木生活福祉課長","answer":"続きまして生活保護世帯の高校から大学へ進学し、大学を卒業された方、今年度７名いらっしゃいますが、こういった方にどのような支援があるかですが、それにつきましては、正直申し上げて高校の段階では一時扶助という形で学級費等は出てありますが。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのような中でも、頑張って生活保護の中で高校を卒業した後、専門学校や大学まで行って卒業しているという、先ほど、今年度は７名ということだったのですが、どれぐらいの方が実際に行かれているのか、また、途中で経済的な理由だったり、さまざまな理由で退学をせざるを得なくなるような、そういう方がどれくらいいるのかということも、わかったら教えていただきたいと思います。","respondent":"矢木生活福祉課長","answer":"もう１つ、これは何年か前にできた制度ですが、厚生労働省社会・援護局長通知「生活保護法による保護の実施要領について」の第１－２－（７）に規定されていて、よく（７）分離というふうに申し上げるのですけれども、高校を卒業する段階で、あなたは就職するのですか。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ありがとうございました。そういう点で言えば、やはり貧困の連鎖を断ち切る、子どもがお金の心配をせずに資格であったり大学であったり、進学ができるようにという点では、今回これは本当に大きな一歩としての前進だと思うのですけれども、さらにそういう支援の充実というところで、区のほうからも声を上げていただけたらというふうに要望させていただきたいと思います。","respondent":"川島健康課長","answer":"区として、民間企業のほうに設置を進めていくという話になると、恐らくまた少し内容が変わってくると思いますので、区民の方にとって安心・安全につながるような設置の助成ですとか、そういった形の施策を検討していきたいと考えています。","id":"exchange-013"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点だけ。先ほど、生活保護の塾代のところで、小学校４年生から小学校６年生の対象者は４８名だけれども、支給され、使っていたのは２名だということだったのですけれども、これは塾に行く子が少ないということなのか、それともなかなか１０万円では足りなくて利用ができないということなのか、実態と合わせてみてどういう２名なのかを少し伺いたいと思います。","respondent":"矢木生活福祉課長","answer":"実際、お金を払った後に、申請しようとしたけれども領収書をなくしてしまったという方も相当数いらっしゃると思いますし、こういうことを含めましても、今回の補正とともに、私どもの今まで行っていた取り組みを再構築いたしまして、一貫して。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"さまざまなご答弁ありがとうございました。生活保護世帯の塾代、受験料の支援の話について、大学進学率がなぜ品川区は全国平均に比べて約９ポイント高いのかというのを、２３区共通していることなのかを含めて、何かわかっていることがあればお聞きしたいと思います。","respondent":"矢木生活福祉課長、川島健康課長","answer":"大学進学率が高いのはということでご質問いただきましたが、これにつきましては地道な学習支援ですとか、品川の立地条件等々があるものと、複合的な要因かと考えています。２３区につきましては、申しわけございません。使った場合は区のほうにもきちんと報告を上げていただくということ、それからしまう場所も、中にしまい込んでしまうとすぐ出せませんので、カウンターですとか受付のところ。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"去年９月にこの４件の陳情が審査されたところで、私も意見を申し上げたところなのですけれども、そのときに、区として受動喫煙防止対策基本方針というのがあるということで、その中身については平成１５年につくられたため、実態に即さない部分もあるので内容を見直すという方向でも答弁があったのですけれども、その後この基本方針については見直しがされたのかということを１点お聞かせいただきたいのと。","respondent":"川島健康課長","answer":"健康プランの中での喫煙率が低過ぎるというお話ですが、前回も私が同じようにお答えいたしましたが、こちらは健康センターに健康づくりに通われている方で、非常に意識の高い方たちですので、かなりいいほうに振れている調査結果だというふうに思っておりますが、今年度。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当にこれだけたばこの害が、特にたばこを吸う人にとっては決定的だし、受動喫煙でもこれだけ、１万５,０００人もの方が４項目に限っただけでも亡くなっているということを直視した対策が本当に求められていると思うのですね。そこのところも合わせてお聞かせいただければと思います。","respondent":"川島健康課長","answer":"啓発の事業性ということになるのかと思いますけれども、昨年も私ども、健康づくり推進委員の皆様を対象に受動喫煙の健康被害を講演会という形で開催させていただきましたし、それから健康課主催ではございませんが。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それからもう１つ、喫煙のところで、五反田の歩道橋の下が喫煙所なっていて、あそこの歩道橋を降りるときに、たばこのすごいにおいと、それから朝などは本当にたばこの吸い殻だらけという状況になっているのですけれども、屋外の喫煙所についても、喫煙所というのであれば、ただ灰皿を置くのではなく、屋外の喫煙施設のような形で囲って、さらに煙は、今の技術では、煙を無害化するということはできないのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう中で、今回、厚生労働省が通常国会でも法案を提出したいと言ってきていたにもかかわらず、こういう形で提出されなかったというのは本当に残念だし、またオリンピックの１年前、２０１９年にラグビーのワールドカップもありますので、本当に世界からも最低と烙印を押されている状況ですから、それに対しては対策をぜひとっていくことが必要ではないかと思っているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"意見","question":"４件とも受動喫煙の防止の案件だと思うのですが、内容が違うという中で、去年の議事録を読ませてもらいましたが、現状で去年と変わらない、同じような質疑を繰り返している部分だと思いますので、国の方針、都の方針も出てくるのを待つという状況を含めて、継続ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"提案","question":"私は、去年のところでも受動喫煙防止条例というのを制定していくということは必要なのではないかと、この条例に対しては賛成だということで申し上げたのですけれども、でもそのときの審議の中で、とりあえず継続でもいいということでそのときは申し上げたのですけれども、それから約１年近く今たって、国会の中でも、本来であれば通常国会で法制化されるという方向だったにもかかわらず。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-021"},{"speaker":"大倉委員","kind":"意見","question":"陳情に関してですが、内容としては受動喫煙を防止していこうということで方向性は一緒かと。その中で方法や意見が違うということで、区としても今、話がありましたが、都や国の動向を注視していかないとなかなか対応としても難しいという話でしたので、会派としては継続ということでお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/549442?Template=document&Id=3480#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":26034,"voices":85}},{"id":"h29-20170710-8","meetingId":"h29-cm07","date":"2017年7月10日","dateIso":"2017-07-10","committee":"建設委員会","time":"午前１０時００分～午後 ０時４０分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を42件抜き出しています。","topics":[{"id":"topic-01","title":"第４８号議案 品川区立公園条例の一部を改正する条例","agenda":"第４８号議案 品川区立公園条例の一部を改正する条例","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"今日、視察をさせていただきまして、よく状況がわかりました。どれぐらいの人の見込みというか、想定されているのかということを教えていただきたいのと、今日も暑い中での視察だったのですが、日よけみたいなところ、熱中症対策としての日よけが、ちょっと何かパラソルを立てるなり、屋根をつくるなり、何かそういうことのお考えがあるのかどうかというところを確認させてください。","respondent":"溝口公園課長","answer":"ただ、日本スケートボード協会に、今回、整備にあたっていろいろ確認していくと、譲り合いながら滑る競技という形なので、もうちょっと多い人数でも利用は可能かとは思いますが、大体、ほかの先進事例等を参考にしていくと。","id":"exchange-001"},{"speaker":"新妻委員","kind":"質問・要望","question":"スケートボード場に関しては、オリンピックの競技にもなったということで、今後、人気も高まってくると思いますけれども、将来のオリンピアンがここから出てくるぐらいの、何かそのような、品川区として、これは要望としますけれども、スケートボード協会とも連携されているということですので、大会の誘致ですとか、ぜひやっていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"運営の実際はどうなのかということで何点かお伺いしますが、まず１点目は、使用するまでの手続というのはどのようになるのかということです。２点目が、プールのように監視員などがついたりするとか、トラブルが起きた場合の対応などはどうされるのかということであります。３点目は、料金を取るとありますが、どこに払うのか。一旦どこかへ出て、また戻ってきた場合は２００円かかるのか。","respondent":"溝口公園課長","answer":"非常用とか、そういったものも、呼び出しボタンというものを現地に設置したいと考えておりますので、安全に利用していただくような対応を図っていきたいと考えているところです。","id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"大分、イメージがわいてきましたが、では登録制にした上で、登録した人が券売機で、利用する際に料金を払うというようなイメージと理解しました。もし間違っていたら補足をお願いします。なぜ有料にするのか、改めてお伺いしますと同時に、また、今回の有料化というのは、いわゆる受益者負担の考えというのも含まれているのか、その辺もあわせてお伺いします。","respondent":"溝口公園課長","answer":"それほど法外の値段を取って運営しているとは考えておりませんので、こういった形、今までにお話しした考えに基づいて、今回のスケートボード場については有料施設として使用し、区民の方にご利用いただきたい考えております。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問","question":"料金の話もありましたけれど、法外だと言う人もいれば、そうではないと言う人もいるでしょうけれど、子どもにとっては法外なのではないかという気が私はするのです。児童センター、ティーンズプラザなども無料でやっていますし、ここだけ有料化するのは私はおかしいと思いますので、無料にすべきと思うのですけれども、いかがでしょうかというのが１つです。それもあわせてお伺いします。","respondent":"溝口公園課長","answer":"そういった中では、やっぱり一定の料金というのは発生して、そういったものを払うことによって、しっかり自分たちがスポーツ競技を楽しめる、そういった施設になると考えているところですので、改めて無料にするというのは考えていないというのが今現状です。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"先ほどちょっと、受益者負担の考えも含まれるのですかということもお伺いしたので、その辺をあわせて、もう少し説明をいただきたいと思います。","respondent":"溝口公園課長","answer":"そういった考えについては、これまで、区のほかの施設と同様の考え方です。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問・要望","question":"フットサル場のほうなのですが、基本的に夜間のほうをフットサルということで、日中はテニスということなのですが、予約のとり方について、例えば数カ月前からはフットサルとしての申込で、もしもそこがあいていたらテニスコートとしてもというような方向性に持っていけると、要はこれから使う割合によって、どういうふうになっていくのかというのがわかりやすい、把握しやすいと思うのですけれど。","respondent":"溝口公園課長","answer":"テニスコートの日よけなのですけれど、今回、敷地面積的に、フットサルとしてぎりぎりの面積になりますので、中にベンチを置いたり日よけを置いたりすると、今度、テニスの方はいいのですけれど、フットサル場として機能しなくなりますので、その辺は、申し訳ないのですけれど。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"フットサルの場合は、当然、ぎりぎりにしかとれていないので、ですから、その中に休憩所とか、そういうのは設けるのが難しいのはわかります。ただ、テニスになってくると、やっぱり日よけは必要で、何でしょうか、固定しなくても、移動できるような形でのベンチであったり、そういうものでもいいと思うのです。その辺の考え方をお聞きしたいと思っていますが、いかがでしょうか。","respondent":"溝口公園課長","answer":"ですから、料金設定については、これまでのほかの運動施設と同様に、同じような料金設定の考え方に基づいて、小学生以下、中学生以上でやらせていただいて、ソフト的なところで、さまざまなイベントまたは教室といったものを開くことによって。","id":"exchange-008"},{"speaker":"西本委員","kind":"意見","question":"最後に意見です。なので、ここは一律的に考えるのではなくて、これは振興していますよ。所管違いでごめんなさい。それを、小学生、中学生、高校生、大学生ということの状況を考えながらの設定も１つの表現の仕方なのではないかと私は思いますので、今後、検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"簡単に一言だけ。利用者を、まず登録制にするということを、先ほどからお伺いしましたけれども、やはり１回３０から４０人、マックスで入れるということですけれど、運動の性質上、事故も起こらないとも限らないのですけれども、保険はどうなっていますか。","respondent":"溝口公園課長","answer":"基本的には保険というのは、当然、公共施設でありますので、そういったところの、今までの自治体賠償保険とか、そういったものは対象になると考えておりますが、基本的には個人で利用していただきますので、保険については、登録する際に。","id":"exchange-010"},{"speaker":"大沢委員","kind":"質問・要望","question":"そういう意味では、メッカにする上では、今後の考え方として、区のみで対処するのではなくて、民間のそういったノウハウ、やはり外に対する周知というか発信の仕方は大いに民間側の力も活用すべきではないかと思いますけれど、今後の展望、あり方について、どのようにお考えになるか。今後１１月にオープンということですけれども、オープンを前にして、その辺の考え方だけ教えていただきたいと思います。","respondent":"溝口公園課長","answer":"そういった中で、民間のノウハウというか、公園管理という視点だけでなく、そういった、利用している団体といったところとも連携を図りながら、当施設がより有効に活用できるようにしていきたいと考えているものです。","id":"exchange-011"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"すみません。限られるという言い方はおかしい。それをやるときに、プロテクターというのですか、必ずヘルメットを着用して、膝、肘のプロテクターを、ちゃんとした運動靴を履かないと、何というのでしょう、入ってはだめですよなどという規定を設けるのかどうなのかというのも、それはまた違う要綱か何かに出てくるのかわからないですけれど、その辺もどうなるかを教えていただきたい。","respondent":"溝口公園課長","answer":"今回、スケートボード場利用にあたっては、当然、ヘルメット、また肘当てというのを、プロテクターというのを必ず着用していただかないと利用ができない。","id":"exchange-012"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"よく道などでやっているのを見ていると、「俺はうまいから」という人というのは結構いるわけじゃないですか。俺は大丈夫なんだよ。むしろ、そういうのがない人もすごくいるのではないかという部分があるので、それはしっかり、最初の登録のときに全てもう説明していただいて、利用者に気持ちよく使っていただけるようにしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"筒井委員","kind":"意見","question":"私からは３点ほど。２点目としましては、スケートボード場の利用の際に、リストバンドなどの配付を考えているということなのですけれども、そうしたリストバンドを配付する場所や、また、そもそも料金をどうやって徴収するのかという。最初は期待値が相当高いと思うので、特に初年度は大変混乱すると思うので、その辺の対応はどうされるのかということが２点目。以上３点、お願いします。","respondent":"溝口公園課長","answer":"その発券された券を管理事務所のほうに行って券を見せることによって、リストバンドを渡す。そのリストバンドがついているか、ついていないかで、スケートボード場に料金を払ったか、払っていないかというのを確認しながら進めていきたいと考えています。","id":"exchange-014"},{"speaker":"筒井委員","kind":"質問","question":"利用者同士のけんかなどが発生する可能性はありますので、そういった場合は早く対処しなければならないと思うのですけれども、そういった管理体制はどうなっているのかということと、また先ほど、ヘルメットや道具の共用をお考えということでしたし、また競技の特性上、設備の傷みが結構、ほかのフットサル場等より早いと思うのです。以上２点、お伺いします。","respondent":"溝口公園課長","answer":"そういったものについては、日常の管理の中でしっかり対応していきたいと考えていますし、今後またいろいろセクション、また状況が変わって、利用者等の声を聞きながら、変えていけるところについては、さまざまな手法を考えながら改修にあたっていきたいと考えているものです。","id":"exchange-015"},{"speaker":"安藤委員","kind":"確認","question":"すみません。これまでの質疑や説明でもし出ていたら大変申し訳ないのですが、小学生だけの利用というのは、基本的に応じないということなのでしたっけ。同伴ということでしたっけ。そこだけ確認させてください。","respondent":"溝口公園課長","answer":"ただ、とはいえ、保護責任者１名につき小学生以下の方３名ぐらいまでは面倒を見られるというのを、スケートボード協会の方からも聞いておりますので、そういった中での運用をしていきたいと考えているものです。","id":"exchange-016"},{"speaker":"安藤委員","kind":"意見","question":"反対なのですけれども、子どもの貧困も言われている中、中学生に対して１回２００円の負担は決して軽くない。これからオリンピックもパラリンピックも控える中で、お金のあるなしではなく、多くの子どもたちに、スポーツに接する環境をつくるべきだと思いますので、これは有料化条例ということですので反対します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"賛成します。よりよいものをぜひつくっていただきたいと思いますので、よろしくお願いいたします。賛成です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"}]},{"id":"topic-02","title":"平成２９年陳情第３号 区民住宅「ファミーユ下神明」の家賃助成に関する陳情","agenda":"平成２９年陳情第３号 区民住宅「ファミーユ下神明」の家賃助成に関する陳情","exchanges":[{"speaker":"新妻委員","kind":"質問","question":"普通、入居者お一人お一人、１世帯ごとに、ちゃんと面接なり電話のやりとりなり、対話をしてのご認識を、そういう周知をされているのかというところを１点お伺いしたいのと、あと、この近傍家賃、この周辺の相場と、現在、助成額がなくなった後の、その周辺の相場との相違というのがどれぐらいあるのかというのをお伺いしたいと思います。","respondent":"長尾住宅課長","answer":"周知につきましては、しおり、あと助成決定の通知の中で文書の中にも書いておりますが、説明の中で内容については具体的に周知もしています。","id":"exchange-019"},{"speaker":"新妻委員","kind":"確認","question":"すみません。周知のところをもう一歩、確認したいのですけれども、区の責任としては、こういうふうに、しおりも出しているということなので、それはちゃんとされていると思うのですけれども、本当にご理解いただけているのかどうかというところが、中にはもしかしたら書類も知らないと。","respondent":"長尾住宅課長","answer":"実際の入居の手続に関しましては、現在は指定管理者を通じて行っております。指定管理者を通じての説明ではありますが、入居の手続等に関しましては面接もあります。面接の際などを通じて、しおりも活用しながら説明をしてきているところです。","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"そもそも下神明や西五反田など３館のような、建設型でフラット型家賃の区有住宅を設置した事業目的というのでしょうか、区が中堅所得ファミリー層の定住化を図るアイテムなわけですが、その意図をもう少し詳しくご説明いただきたいというのが１つです。","respondent":"長尾住宅課長","answer":"所得区分の１から４の具体的な数値に関しましてですが、所得区分１がおよそ３５０万円から４００万円程度、所得区分２に関しましては４００万円から４４０万円程度、所得区分３に関しましては４４０万円から５００万円程度、所得区分４が５００万円から６００万円程度と。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、現在の近傍家賃等は調査していない、把握していないということですけれども、それは大変重大、重要なところではないかと思いますので、これは調査すべきだし、そうしないと、今の住んでいる方々が家賃助成がなくなったことでどういう影響を受けるのかというのはやはりわからないと思うのです。ですから、これは調査すべきだと思うのですけれども、いかがでしょうか。その辺を伺えればと思います。","respondent":"長尾住宅課長","answer":"この第５所得区分と第１所得区分の使用料の差額というのが、４万３,４００円という形になっております。ほかの住戸に関しましても同じような考え方で、第１所得区分の方が、その住戸タイプにおける最大の助成額を受けられているという状況です。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問","question":"やはり、数字で見ると結構リアルだなと思ったのですけれど、今、１３万６,７００円の方が１８万１００円になるというのは、全体的な金額で見ればその差なのですけれども、毎月払っている家賃が、１３万円払っていた方が１８万円になるというのは、しかもその人が第１区分の方ですから、年収３５０万円から４００万円ということです。","respondent":"長尾住宅課長","answer":"入居の入れかわりの要因としましては、住まわれている方の世帯人員の増や減であるとか、あと収入の増減であるとか、そのほか、いろんなご都合、個別のご事情があって入れかわっていると認識しております。","id":"exchange-023"},{"speaker":"大沢委員","kind":"確認","question":"周知のことで伺いたいのですけれども、これは助成決定通知書であるとか、いろいろと使用料の負担額というのが決定されたこと、要するに決定して、それは毎年ごとに利用者の方に周知は十分にされていたわけですよね。そこをちょっと確認させてください。","respondent":"長尾住宅課長","answer":"助成決定の通知に関しましては、毎年、その年の世帯年収のご報告をいただきまして、その内容に応じて助成決定をしているところです。その決定手続の中で皆様に改めてご案内をしているところです。","id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"もう一つです。傾斜型とフラット型ということですけれども、傾斜型についてはある程度決まったパーセンテージを払っていく、上乗せしていく。フラット型については、それをなくして、全てそのまま払っていく。ちょっと金額がわからないのですけれども、保たれるのか保たれないのかということについて、おわかりになる程度で伺います。","respondent":"長尾住宅課長","answer":"傾斜型とフラット型の区民住宅につきましては、それぞれ建設当時の考え方が異なりますので、完全に同じ条件で比較ということは難しいと思われますが、公平性の観点から言いますと、傾斜型の家賃の区民住宅に住まわれている方は。","id":"exchange-025"},{"speaker":"筒井委員","kind":"質問","question":"そもそも助成期間を１５年に区切った理由は何なのかということと、あと、先ほど入れかわりが２０から３０世帯もあるということなのですけれども、中堅所得者層の定住という意味では、そもそも住んでいる方の転居は前提としているのですか。その２点をお伺いいたしたいのですけれど。","respondent":"長尾住宅課長","answer":"いろんな事情が、やはり月日がたてば発生してくると思いますので、そういったところは、状況を踏まえて転居されるということも当然あるとは考えております。","id":"exchange-026"},{"speaker":"西本委員","kind":"質問・要望","question":"１つだけ。今回はファミーユ下神明１３２戸なのですが、フラット型になっているのは６３０戸ですから、そのほかの方々からは何か要望など出ているのですか。","respondent":"長尾住宅課長","answer":"特にほかからご要望いただいているといったことはございません。","id":"exchange-027"},{"speaker":"筒井委員","kind":"質問","question":"この陳情を出されたのが平成２９年２月１５日なのですけれども、あれから約５カ月間ほど経過したのですけれども、区はこの入居者に対して、助成期間が終了の理由と、また、ほかの転居に際してのアドバイスなどはされたのでしょうか。","respondent":"長尾住宅課長","answer":"陳情を出されている方、個人に対して個別にというところは、特に現時点では行っていないのですが、今、陳情も出ている状況ですので、その議論を踏まえて、今後の対応は検討していきたいと考えております。","id":"exchange-028"},{"speaker":"大沢委員","kind":"質問・要望","question":"本日、結論を出していただきたいと思います。願意に沿いがたいということで、不採択ということを主張します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"新妻委員","kind":"質問・要望","question":"当然ながら、今ありましたとおり、国の補助が１５年という規定も決まりごとであるということも理解いたしますが、ここの陳情の中にありますとおり、今後転居される方が出てくる中で、これまで築き上げてきたコミュニティの存続に対しても困難だということも心配されておりますので、今後、助成がなくなった後の対応を、できる限り。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"安藤委員","kind":"意見","question":"中間層の疲弊も社会的に今、叫ばれている中で、やっぱり区民住宅そのものの家賃の低廉化というのも考えていかなくてはいけないと思っていますし、この陳情に関しては、一定の家賃の急激な値上がりとならないように配慮するということなのですけれども、これは少なくとも行うべきだし、それは可能だと思いますので、採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"願意に沿いがたいという部分で、理由としては、おそらく区民住宅は、国の助成が１５年でもう終わるということで、１５年間は補助、助成しますということで、もちろん入居するときにご説明もされている。要するに賃貸契約というのは、しっかりそういうのも確認しつつも、ライフプランというのですか、そういうのをつくっていくべきものではないかという、これは完全に個人的な話なのかもしれないですけれど。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"結論を出すということでお願いします。それで、結論としては不採択です。理由としては、１５年の期間設定がされており、それについての周知もなされていた。ただ、今後、入居者の方には丁寧なご対応と、今後の生活に際してのアドバイスはしていただきたいと思いますので、これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"西本委員","kind":"質問・要望","question":"本日、結論を出してください。要望はわかります。それで、いろいろな要望があったからということで、これを許可する、何か方法、手だてをするということであるならば、ほかの人たちはどうなのか。ただ、ほかの方が言っておられましたけれども、なかなか住みにくくなってしまうという方も当然いらっしゃると思うので、その方々への対応というのはしっかりやっていただきたいと考えます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"}]},{"id":"topic-03","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"さらに内訳が書いてあって、１８１人の方が技能系職員ということなのですが、この方は正規雇用なのでしょうかというのを確認させていただきたいのと、それと２３５名の事業係の方、回収作業に従事している方は、この２３５名というのが全てなのでしょうか。それとも、ほかに委託などもしているのか、その辺をお伺いします。","respondent":"工藤品川区清掃事務所長","answer":"事業係の職員の内訳の件です。１８１人というのは、私どもの職員です。収集につきましては、いわゆる燃えるごみ、不燃の収集等があります。こちらは私どもの職員でやっているものです。","id":"exchange-035"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"すみません。もっと、逆に言えば区の作業車より、その下の協力会社というのですか、ほかの資源を集めているところの事故も多分多いと思うので、その辺はしっかり、事故が少ないように、ぜひしていただきたいということが１点と、これは損害賠償額がぴんとこなかったのですけれど、これは品川区がお支払いした額なのか。もし品川区が払うのであれば、損害賠償ということなので、どういう位置づけなのか。","respondent":"工藤品川区清掃事務所長","answer":"当然、任意保険の部分で対物の賠償保険ということで、無制限で入ってありますので、掛け金をかけておりますので、そちらのほうの保険会社から全額支払いを受けるということになります。","id":"exchange-036"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"１つだけ、見分け方の中で、「肉眼で」という中に、「連続的な」という言い方があります。この連続的な変異、連続的変異のないものということなのですが、これはどういうふうに考えるのでしょうか。","respondent":"小林環境課長","answer":"ヒアリの特性でありまして、要は大きいものと小さいものが混在しているということだそうです。同じ大きさだけではなくて、小さいものと大きいものが混在しているものがヒアリです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"普通は似たような大きさだけど、それがまちまちの大きさだった場合は、ちょっと怪しいという認識でよろしいですか。","respondent":"小林環境課長","answer":"１つの判断基準として、そういったところが１つの目安です。もう一つは、先ほど資料の中にもありますように、赤茶色のアリとか、そういうところの判断基準です。","id":"exchange-038"},{"speaker":"安藤委員","kind":"質問","question":"子育て世代の中でも不安が広がっておりまして、保育園の送りなどのときにも聞かれたりしたのです。何点かお伺いしたいのですけれど、まず、移動、国内住宅地への拡散の可能性というのですか、そういうのは率直にどうなのでしょうか。内陸部というか、どれぐらい移動するのかという、その辺をお伺いしたいのが１点です。その１つだけチェックしていればいいのかという、この辺も２点目でお伺いします。","respondent":"小林環境課長","answer":"大きさ感等についてわかりづらいというご意見がありますので、その辺につきましては工夫をしていきたいと思いますが、我々、区のほうで、今、ヒアリ自体持っておりませんので、その辺、何かいい写真があれば工夫してまいりたいと考えています。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問・要望","question":"どれだけ移動するのかというのが。今はコンテナの内部からしか見つかっていないですけれど、その点についてどうなのかというのをもう一度お伺いするのと、それと、資料の４番目の「今後について」というところですが、緊急調査の際の協力とありますけれど、緊急調査というのは、調査する範囲ですとか対象ですとか実施時期とか、もしわかれば教えていただきたいというのが２点目です。","respondent":"小林環境課長","answer":"資料４の緊急調査の時期ですが、これについては、先ほどご説明しましたとおり、今、国と都と区のほうで、詳細についてはこれから決定するというところでございまして、まだ詳細については決まっていないところです。","id":"exchange-040"},{"speaker":"新妻委員","kind":"質問","question":"２点ほどなのですが、１点は所管が違うかもしれないのですけれども、これは当然、今の子どもたちがアリと遊ぶかどうかはわかりませんけれども、好奇心でさわってしまうというようなことがある中で、小学校と保育園、幼稚園には、これは当然ながら周知されているという前提でよろしいのでしょうかということが１点と、あと、アリが入ってくるということは。","respondent":"小林環境課長","answer":"１点目の、子どもへの対応ですが、小学校、幼稚園、保育園、いろいろとあると思います。環境課のほうから、現在の状況と、やはり見分け方の資料を全課に配付・周知をしておりますので、それから各所管のほうから各施設のほうに流れていると認識しています。","id":"exchange-041"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"それを考えると、品川区でコンテナづけで荷物をおろすところがどれぐらいあるかもわからないですけれど、そういうところでもアリがおりてしまう可能性もあるわけですから、そういうのも含めて、毒餌だけではなくて、逆に言えば、まさに先ほど視察に行った八潮などというのは、コンテナがいっぱい通るところでありますので、ちょっとした衝撃でばらばらとアリが落ちてしまって。","respondent":"小林環境課長","answer":"それで、また港湾局につきましても、荷おろしの際に目視調査をかなり厳重に行っているというところは、今、話を聞いているところですので、さらにうちのほうからも、それらが内陸部に入らないように何か対策をしっかり講じるようなことができないかどうかを含めて。","id":"exchange-042"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169461?Template=document&Id=4204#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":35762,"voices":126}},{"id":"h29-20170710-9","meetingId":"h29-cm07","date":"2017年7月10日","dateIso":"2017-07-10","committee":"文教委員会","time":"午前１０時００分～午後 ０時３０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件抜き出しています。","topics":[{"id":"topic-01","title":"第４５号議案 品川区保育の実施等に関する条例の一部を改正する条例、および(3)第４６号議案 品川区私立認定こども園","agenda":"第４５号議案 品川区保育の実施等に関する条例の一部を改正する条例、および(3)第４６号議案 品川区私立認定こども園","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"第４５号、第４６号議案のほうですけれども、対象人数が９名で、年間４万８,０００円ほどの軽減となるとのご説明があったと思うのですけれども、これは１人当たり４万８,０００円の軽減ということなのか、その辺がよくわからなかったので、伺いたいと思います。","respondent":"佐藤保育課長","answer":"私立幼稚園の関係ですけれども、既にご案内のとおり、区内には私立幼稚園で新制度に移行している園はございませんので、利用者負担条例で該当する私立幼稚園に関しては、品川区民で区外の保育園に行かれている方３７名の中で、該当する方がいらっしゃるです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"第４４号議案ですけれども、改正した理由を伺いたいと思います。利用者の負担軽減ということでいいのでしょうか。伺いたいと思います。そして、負担軽減の部分もあると思うのですが、確認のためにお聞きしたいのですけれども、値上げになる方はいないのかということを確認させていただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"２点ほど質問いただいたと思います。なぜ改正するのかというところなのですけれども、ぷりすくーる西五反田の幼児教育部門というのは、本条例によって独自に保育料を定めております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問","question":"今回のこの機会で改正したというのは、今までは区立幼稚園等と同等にしていなかったところもあると思うのです。特に第７階層の所得割額の範囲を広げるというところでは、それで私立幼稚園の階層と同じになったと思うのですけれども、それまでは同等にしていなかったというところもあると思うのですが、今回改正を行った理由も伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"区はこれまでも保育料の軽減を図ってまいりました。その中で、今回の保育料軽減につきましても、私立幼稚園に対する補助金額の所得割階層の区分を参考にしまして、保育料の軽減のために改正した次第です。","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"全体として利用者の負担軽減をしていくところですので、歓迎したいと考えています。ぷりすくーる西五反田のほうでは、多子減額規定において年齢制限がある部分がありますので、今後、ぜひ年齢制限をなくしていっていただきたいと思っているのですが、区のお考えを伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"国の動向等を見ながら考えていきます。","id":"exchange-004"},{"speaker":"南委員","kind":"質問","question":"それと、全体的に基本的な姿勢としては受けとめていきたいとは思っているのですけれども、第７階層を拡大するという、対象拡大そのことは歓迎していきたいと思っていますが、なぜ第７階層のみなのかがいま一つよくわからなく、ほかの階層も所得割額の範囲を広げていくのが当然ではないかと思っているのですけれども、そのあたりのことを２点目としては伺いたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"２点ご質問いただきました。１点目、ぷりすくーる西五反田の第７階層だけがなぜ変わるのかということについて、説明いたします。平成２８年から、ぷりすくーる西五反田の保育料については応能負担としてまいりました。","id":"exchange-005"},{"speaker":"南委員","kind":"確認","question":"今の説明では、第７階層のみにした理由がよくわかりません。確かに補助金の対象拡大で、平成２９年度は９０％にしたというところは、それはそれとして受けとめましたけれども、そのことをもって第７階層だけを対象拡大して、では、ほかの階層では対象拡大がないので、負担軽減について考えなくていいという考え方なのかどうか確認をしたいと思います。改めてこの点を最後に伺っておきたいと思います。","respondent":"吉田保育施設調整担当課長、佐藤保育課長","answer":"小学校３年生の年齢撤廃というところですけれども、こちらのほうは国等の動向を見ながら子ども・子育て支援新制度等に基づきまして対応したいと考えております。その関係で、国の考え方がそこで一回整理をされていますので、区としては、平成２８年度に保育料の改正も行っていますから、その辺も含めまして、また一方で待機児童対策の経費も重なっていることもありますし。","id":"exchange-006"},{"speaker":"南委員","kind":"意見","question":"先ほどから申し上げているように、この３つの条例については賛成していきたいと思っているのですけれども、今の答弁ではやはりよくわかりません。したがって、国の動向と第７段階のみというところ、それから、多子減額規定における小学校３年生以下の年齢制限については、これからしっかりと見守るとともに、要求を引き続きしていきたいと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"松永委員","kind":"確認","question":"ご説明ありがとうございました。私からは、確認で２点ほど伺いたいと思います。第４４号議案について、今回の改正に当たり、親にとってはとても助かるものであると認識しております。今回の改正で、負担額はどのぐらいになるのか。２つ目が、負担額減額にあたり、財源はどのようなところから確保しているのか、確認でお願いしたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"負担額につきましては、第７階層、所得割階層で言うと、今まで２５万６,３０１円から３７万円の方が１万８,９００円負担していたところが、その階層を広げたことで、２５万６,３０１円から８０万３,０００円までの方につきましても。","id":"exchange-008"}]},{"id":"topic-02","title":"第４１号議案 平成２９年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第４１号議案 平成２９年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"処遇改善等加算で、これは何人の方が対象で、１人当たりどのくらい上がるのでしょうか。非常勤の人も対象になってくるのか、伺いたいと思います。（II）のところで、副主任保育士とか専門リーダー、職務分野別リーダーということで、月額４万円と５,０００円が加算されるということですけれども、この研修等を何時間受講する必要があるなど要件を伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"非常勤職員も対象になります。研修の時間数ですけれども、現在、１分野につき１５時間ということで設定がされております。こちらは都道府県が研修の実施主体となっております。","id":"exchange-009"},{"speaker":"のだて委員","kind":"質問","question":"１分野でいいのか伺いたいと思います。そして、やはり今、保育園不足で保育士も足りないという状況も全国ではあると思いますし、東京でもあると思うのですけれども、そういった環境で研修に行ってもらうとなると、なかなか研修に行ってもらう時間もとれないのではないかと思うのですが、それを保障する制度、仕組みというのはあるのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"ただ、今年度につきましては、この研修受講は義務づけられておりません。平成３０年以降につきましては、今後決定するということで聞いております。","id":"exchange-010"},{"speaker":"のだて委員","kind":"質問・要望","question":"そういったところもしっかりと保障していかなければ、実際に処遇が改善されていかないと思いますので、ぜひ区として、国に求めていっていただきたいと思いますけれどもいかがでしょうか。そして、東京都のキャリアアップ補助金なのですけれども、これは保育士以外の方も対象になるのでしょうか。大体１人当たり幾らぐらい、これによって加算されるのかという見込みがあれば、伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"キャリアアップ補助金のほうですけれども、あくまでも平均ですが、今までの分が２万３,０００円、今回新たな拡充分が２万１,０００円になりますので、足しまして４万４,０００円分がキャリアアップ補助金として支給されるという考え方になります。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"やはり一斉に４.４万円上がってくればいいですけれども、なかなかそうではないのではないかという声も寄せられておりますので、実態としてきちんと上がってきているのかというところをどう考えていらっしゃるのか、伺いたいと思います。それから、株式会社と社会福祉法人では手続や要件などが違うのかどうかも伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"社会福祉法人と株式会社のことですけれども、社会福祉法人につきましては、東京都が直接実施いたしますので、区を通さずに同じスキームでキャリアアップ補助金が支給されるです。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"保育園には保育士だけでなくて、調理師、事務員、用務の方もいらっしゃったりしますし、その方々が一体となって園を運営しているわけですから、恒常的な改善をぜひ、職員の配置基準ですとか、そういったところも、公定価格も恒常的に上げていくということが必要だと思うのですけれども、区のお考えを伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"公定価格等につきましては、様々な制度もありますので、それは国や都の動向を注視しながら、区としても対応していきたいと考えております。","id":"exchange-013"},{"speaker":"南委員","kind":"質問","question":"そこの点についての認識はどうなのかということを伺いたいと思います。ただ、前提として補助金を出すことについて反対はしませんが、こういうやり方というのは、いかがなものかという問題意識を持っています。そういう状況を生み出すということについて、区としての認識はどうなのか、よしと受けとめているのかどうか、基本的な考え方もこの際伺っておきたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"先ほどの職層別の処遇改善についてですけれども、４万円の対象者というのは、先ほど全体の３分の１が対象と説明したのですが、対象者のうち、その半分の方は４万円で固定されてしまうのですが、残りの部分については、各園で柔軟に対応していいということになっておりますので。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"それで、やはり基本はこういうやり繰りをするということではなくて、園の中の運営、あるいは職員の働く意欲、そこも非常に大事なわけですから、賃金の部分でそういう意欲を一部でも損なうようなことがないことが、いい保育園づくりのベースになると思いますので、ぜひその点については区としてもしかるべき立場として、そういう考えで頑張っていただきたいと思っています。","respondent":"大澤待機児童対策担当課長","answer":"保育士の配置等についても、私立保育園には運営費として区からかなり加算をしておりますので、きちんと配置できるように、運営費等の補助も続けていきたいと考えています。それから、研修の費用につきましては、都道府県が負担することになっております。","id":"exchange-015"},{"speaker":"南委員","kind":"質問・要望","question":"区としては私立幼稚園も含めた保育園の運営経費を出しているというお話ですけれども、区が出しているからいいというわけではなくて、国とあるいは東京都、そこの責任もしっかり果たさせるようにする必要があると思いますし、私が言うまでもなく、区のほうは当然そういう思いを持っておられると思いますので、改めてそこのところはきちんと対応をしていただきたいということを強く求めておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"渡部委員","kind":"質問・要望","question":"資料の裏面で、処遇改善加算とキャリアアップ補助金で園数の差が出ているのは、先ほどの株式会社立、社会福祉法人立でというところの関係なのか、その差の件を一つ教えていただきたいのと、今回、結構な金額の補助がこういう形で補正が入ってまいりまして、先ほど南委員も処遇改善についておっしゃっていましたが、今回の拡充により都・国の事業あわせ最大で６万強になるのでしょうか、実際、保育士に対して。","respondent":"大澤待機児童対策担当課長","answer":"ただ、できる限り速やかに対応できるように準備を進めておりますので、支払えるようになったら、４月に遡った分を一遍に各園にお渡しして、それから後は毎月運営費としてお支払いをするという形になります。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問・要望","question":"他の委員の方と少し重なる部分もありますが、確認をさせていただきたいと思います。質疑が先ほどあった事業予算の中で、園数の差というもののご説明がありましたけれども、そうすると、例えば、(1)の処遇改善等加算の園数は、見込み数という理解でよろしいのでしょうか。先ほどのご説明ですと、申請をしたら受けつけますということは、やらないところもあるという理解でいいのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"委員おっしゃるとおりに、園数というのはあくまでも見込みですので、取り組まない園も中にはあります。","id":"exchange-018"},{"speaker":"こんの委員","kind":"質問","question":"もしあったとしたら、受けたほうがいいですと声をかけるのか、申請が来るまで待っているという姿勢なのか、そこら辺のところを区の考え方を教えてください。それから、実態調査ですけれども、そうすると、都に出す書類は調査の項目としてはそうなのですが、品川区として独自でされているというところは、月別なのか、やはり都と同じ１年間なのか、もう少し細かく教えていただけますか。","respondent":"大澤待機児童対策担当課長","answer":"処遇改善については、認可については全園実施しております。都のキャリアアップ補助金のほうを去年実施しなかった園がありましたので、それについてはヒアリングして、どういう考え方でしていないのかというのを確認したのが先ほどのお話です。","id":"exchange-019"},{"speaker":"こんの委員","kind":"確認","question":"わかりました。そうしたら、昨年度そういう園があったということで、ヒアリングも行って、園の考え方、事業者の考え方を伺って、今年度はどうかというところを今見ていらっしゃるという理解でいいのかどうかということと、それから、そうしますと、先ほどの実態調査については、追加要件で出ているこのことは、事業者から自身で情報公開をするということの理解でいいかという確認をお願いします。","respondent":"大澤待機児童対策担当課長","answer":"この要件につきましては、各事業者がホームページにアップしたりですとか、各園で取り組むことになっております。","id":"exchange-020"},{"speaker":"こんの委員","kind":"質問・要望","question":"要件のほうですけれども、やはり公開をするということは、様々な方の目に触れていく、国や都の予算がこういうふうに使われていくのだというところも見ていただく非常に大事な機会でもあると思いますので、今、項目の細かい部分は聞きませんでしたけれども、品川区の調査も含めて、もしそこに加えて情報公開ができるのであれば、ぜひそうしたことも考えていかれたらどうなのかという、最後、意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"高橋（し）委員","kind":"質問","question":"幾つかお尋ねします。それから、先ほどの個人別給与額実態調査については、私立認可保育所、地域型保育事業、今裏面に出ている全てが調査対象になるのでしょうか。それから、３つ目で、私、間違えていたら申し訳ないのですが、一般財源の部分があると思うのですけれども、９,８４７万円ですか、これはどこに使われているのか。１０分の１０だとすると、国のほうの制度かと思いますがその３点お願いします。","respondent":"大澤待機児童対策担当課長","answer":"財務情報として集約するかどうかということは、今の時点では考えていません。今後の検討課題だと考えています。調査につきましては、委員おっしゃるとおり、認可、認証、小規模等全て調査の対象になっております。","id":"exchange-022"},{"speaker":"高橋（し）委員","kind":"質問","question":"それぞれありがとうございました。全体の集約についてはぜひ検討していただいて、各施設を比較できるようなものをつくっていただけるとありがたいと思います。調査範囲は、今お話のあったように、給与が出てきたのをまた公表するなり、報告で伺いたいと思います。一般財源については、理解いたしました。ありがとうございました。","respondent":"大澤待機児童対策担当課長","answer":"申し訳ございません。キャリアアップ補助金ですけれども、小規模保育については、都の負担が２分の１ですので、残りの部分は区の負担になります。病児保育についても同様に、半分が都の負担ですので、残りは区の負担ということになります。","id":"exchange-023"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"例えば、無認可保育園だとか、昔でいう保育ママとか、認可外のところも全部含めて、それが経験の中にカウントされるのでしょうか。カウントされる範囲をお聞きしたいのがまず１つと、それから、２番目は、研修による技能の習得と書いてあるのですが、技能の習得というのは、具体的にどういうことをするのでしょうか。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"技能につきましては、研修内容ですけれども、例えば、乳児保育、幼児教育、障害児保育、あとはアレルギー、食育、安全対策、保護者支援、保育実践というような分野ごとに分かれていて、例えば、アレルギーの研修をとった方は。３点目のご質問で、病児保育事業のところなのですが、委員ご指摘のとおり、２病院と、もう１園はどんぐり保育園が病後児保育をやっている関係で３園になります。","id":"exchange-024"},{"speaker":"鈴木（博）副委員長","kind":"意見","question":"先ほどの２番目なのですが、今お話ししたのは、東京都の認可外の保育士に対する事業でもそういうのがあるのですけれども、具体的に、例えば、アレルギーの対応なんて、どこがそれが技能なのか。技能というのは、要するにテクニックということです。非常にプラクティカルなものだと思うのですけれども、要するに、講義を聞いて、話を聞いても、それは技能とは言えないのではないか。","respondent":"大澤待機児童対策担当課長","answer":"研修を受けることによる経験ということで、技能と経験を有する職員が、副主任保育士になったりとか、職務分野別リーダーになるというような考え方です。","id":"exchange-025"}]},{"id":"topic-03","title":"平成２９年請願第５号、認可保育園入園のための制度改善を求める請願","agenda":"平成２９年請願第５号、認可保育園入園のための制度改善を求める請願","exchanges":[{"speaker":"南委員","kind":"提案","question":"確認ですけれども、今の委員長のご提案は、先に質疑はするけれども、採択をするかしないかそのときに、採択する前に意見を諮る、陳述を聞くということですか。それで、ぜひ委員長の提案ではなくて、質疑を始める前に聞いてみたいと思っています。ですから、ぜひそういうふうに計らっていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-026"},{"speaker":"南委員","kind":"提案","question":"共産党以外の会派の皆さんは、質疑が終わった後だとおっしゃるのですけれども、なぜ質疑が終わった後でいいのか、その辺の理由がどの会派からも紹介されませんでしたので、ぜひ聞きたいと思います。ですから、そうではなくて委員長の提案でいいとおっしゃるのであれば、それぞれの会派の理由、一言ずつでいいですから私は聞きたいと思っていますので、ぜひそういうふうに計らっていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"渡部委員","kind":"確認","question":"地域の方々から上がった請願だからこそ真摯にそれは議論しなければならないわけですが、私ども１１名の会派のメンバーがいまして、当然、この請願に際しまして、会派でどのように取り扱うか、また、それぞれ１１名の議員がおりますので、それぞれ地域の事情等も確認をさせていただいた上で、この請願を当然、会派で何日間かにわたって議論をさせていただいて、今回この場に臨んでおりますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"南委員","kind":"提案","question":"そうしたら、皆さん、我が会派以外は、委員長の提案どおりでいいとおっしゃったのですけれども、委員長が審査が終わった後に聞こうと判断された理由は何でしょうか。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"南委員","kind":"質問・要望","question":"その辺の認識を改めて伺いたいのですけれども、審査が終わった後でも陳述を聞こうというふうになった実例が、この数年の間、品川区議会であったなら、それは指摘していただきたいと思うのですけれども大体そうではないです。今回はこの１件だけですけれども、これからも大いにあることですから、自分の関心のある分野とか、関心のない分野というのは、当然人間ですからあると思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"渡部委員","kind":"質問","question":"ですから、そこはしっかりと私たちも議会人として議会活動をしてきていて、真摯にやっているわけですから、南委員が先ほどおっしゃったそれは委員長に対して失礼かというふうになりますし、議会全体に対して失礼な話かと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"理事者とは違うわけですから、当該の方の生の声なわけですから、そこのところを酌み取る努力もしましょうということであって、意見陳述を受けるに当たってわずか１０分程度のことなわけですから、それを後でいいとはならないし、よしんば後にしたとしても、先ほど質疑したから聞かなくいいという判断になったとしたら重大問題であって、私はそういう態度を議会としてとるべきではないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"南委員","kind":"質問・要望","question":"声が小さくてあまりよく聞き取れなかったので、あらためて確認させていただきたいと思うのですが、まず、１番のところです。どこが連携をとれているけれども、認証保育所のところは直接契約で、区の認定を受けていないから、連携体制はとれないと聞こえたのですけれども、かいつまんででいいですから、もう一回説明をしていただきたいというのが１つです。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"現行で対応できるということは、３歳児の枠としては十分ありますので、認証を卒園されて認可にご希望される方は、認可保育園に入園することが可能なので、現行の制度でも入園は可能ということを説明させていただきました。もう一点、区では国の保育園の優先利用という通知がございまして、それに基づいて指数等を決めているところですが、この優先順位に関しましては、ひとり親、特別支援児、兄弟在園、育児休業等となっておりまして。","id":"exchange-033"},{"speaker":"南委員","kind":"質問","question":"こちらの２番のほうから行きますけれども、３歳以上は努力義務だと。そうしないと働き続けることができない。継続した保育がその子どもにされていかないということについて、どういうふうに考えているのかということ、そして、働き続ける側の保護者の方の支援というのも、保育行政として一定、きちんとした体制で臨むべきではないかと思うので、その点についての考え方を伺いたいと思います。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"請願項目２番に関するご質問ですが、具体的な例でご説明いたしますと、例えば、３歳児で１名のあきに３人の申し込みがあった場合、請願の趣旨ですと、短時間で働いている常勤の場合。待機児童になってしまったということは、地域的な偏在だと考えていますので、その点につきましては、平成３０年度において荏原地区に大分重点的に力を入れて開設を進めているところです。","id":"exchange-034"},{"speaker":"南委員","kind":"質問・要望","question":"今のところですけれども、平成２９年度、１名がそういう状況があったということは、私としては非常に残念であります。したがって、近隣区の中で品川区だけがこういう制限を課しているというところについては、できるだけ早く撤廃をしていただけるようにしていただきたいと思っていますが、調査後についてどういうふうに思っているのか、改めてそこを伺いたいと思います。","respondent":"佐藤保育課長","answer":"６区に関しては、揺れ動いていて、まだ回答ができないというところと、あと、７区に関しましては、年齢制限は撤廃しているのですが、例えば、勤務日数が５日ではなくて４日の場合はそれを見なさないなど、何らかの制限をつけているのです。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"来年度は少なくともこういうことで苦労されることがないように条件を整えていただけるようにと思っているのですけれども、その点についてはどうでしょうか。","respondent":"佐藤保育課長","answer":"先ほど来答弁させていただいているとおり、実際に常勤の方よりもパートなどで長時間働いている方が入園できないというデメリットもありますが、一方で、女性活躍推進法の趣旨等も踏まえまして、慎重に状況を確認して判断していきたいと思います。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはりどの子も品川の子ですから、小規模保育事業のほうは連携で入れて、認証のほうはまた２度目の保活をパパ・ママとしてもやらなければいけないというところで負担が重いわけです。この負担軽減のためにもぜひ取組んでいただきたいと思うのですけれども、いかがでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"先ほども言いましたけれども、入園要件を満たしていて、区外の認証保育所を利用されている方がいらっしゃいますので、その方との公平性が保てなくなるということはありますので、認証保育所と認可保育園の連携というのは。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問・要望","question":"しかし、やはり待機児童が解決できていないというのも一方で事実でありまして、やはりそこを解決していくために、認可保育園の増設をぜひ進めていっていただきたいと思いますけれども、本会議では、待機児童ゼロというのがいつか断言できないというお話でしたが、来年の４月の見込みはどうなっているのか、伺いたいと思います。","respondent":"佐藤保育課長、大澤待機児童対策担当課長","answer":"請願２について、先にご答弁さしあげます。制度があるのに使えないではないかという話なのですけれども、先ほどもご答弁申し上げたのですが、年齢制限を撤廃した場合６時間しか働いていないけれども、２０点つくと。その結果を踏まえて対策を検討していかなければならないと考えていますけれども、現時点で開設の見込みが立っている園の０歳から２歳児の定員の合計は今のところ５６９人ということになっておりますので、一定。","id":"exchange-038"},{"speaker":"のだて委員","kind":"質問","question":"１歳児の対策を検討するということでしたけれども、何か今具体的に考えていらっしゃることがあるのか、伺いたいと思います。４月の見込みをお聞きしたのですが、それは答えられないということなのでしょうか。待機児童ゼロはいつになるかわからないという話ですけれども、４月の見込みをお聞きしたので、来年度の４月時点でどうなるかということをお答えいただければと思います。","respondent":"大澤待機児童対策担当課長","answer":"それも含めまして、現状、今の開設の見込みでは、１歳児の部分はまだ足りないという認識をしていますので、そこの部分は待機児童が今の状況では出てしまうだろうと見込んでおります。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ３つの請願項目、どれもやはり切実な問題ですので、区としてもやっていただきたいと思いますし、委員の皆さんにも賛成していただきたい、採択していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"こんの委員","kind":"確認","question":"若干１名、残念ながら待機児童が出てしまいましたけれども、来年度については対応できる体制があるというところもお聞きしましたが、先ほど制度上、やむを得ず認証保育所は直接の契約であって、そして、その中には認定を受けている人受けていない人双方、ここに入園をされているということなので、現状、認証保育所を卒園したときに、認可保育園だけではなくて。","respondent":"大澤待機児童対策担当課長、佐藤保育課長","answer":"認証を卒園された方の大体３割、３０％の方が、私立幼稚園に進んでいらっしゃいます。そのような数が出ております。請願項目２番の制限を求めている他区等の理由についてですが、品川区も同じなのですけれども、法令、国の通知に基づき、実績重視で、様々な審査を厳格に行っているところが多いと考えております。","id":"exchange-041"},{"speaker":"こんの委員","kind":"意見","question":"１の項目についての、認証保育所の３歳児の先が私立幼稚園が３０％あるということなので、やはりその数を聞いても、来年度の新規開設園でも３歳児枠があるというところなので、おおむね現行で応えられていることが、来年でも応えられていくのではないかと予測ができます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"渡部委員","kind":"意見","question":"この請願書が付託された際に、先ほども申し上げましたように、内容についてはそれぞれが調査して、会派のメンバーとも相談をして、態度までしっかりと、こうこうこうだからというところで決定をし、本日臨んでおりますので、特段、意見陳述は必要ございません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-043"},{"speaker":"こんの委員","kind":"確認","question":"先ほどのご答弁をいただいた中で現状も確認ができましたし、また、自民党と同じになりますが、会派としてもしっかりこの点については議論をして本日臨んでおりますので、意見陳述については行わなくてもよろしいかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"南委員","kind":"質問・要望","question":"現状の確認ができたというご意見もありましたけれども、それはあくまでも理事者の説明による確認ですから、やはり請願者の思いとはまた乖離があるということも大いにあり得るわけです。したがって、冒頭申し上げたように、請願者からそういう申し出があったときは、議会としてはきちんと受けとめるという態度が私は求められる、必要なのではないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"松永委員","kind":"意見","question":"私たちの会派でも、今まで時間があった中で、様々議論を重ねてまいりました。そして本日の委員会に臨ませていただいて、様々な理事者の方からも請願の各項目の現状についても聞きましたので、行なわなくてもいいということでお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"南委員","kind":"質問・要望","question":"非常に残念だと思います。とりわけ質問もしないで、説明を聞いただけでわかった、こういう態度は私は請願者に対して失礼だと思います。少なくとも何らかの質問はして、そして、この議論に直接参加をするべきだと。これが望ましい議員としての姿勢ではないかと思いますので、あえてそのことは発言させていただきたいと思います。非常に残念です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"渡部委員","kind":"質問・要望","question":"質問をしないのは、あえてここで質問をしなくてもしっかり確認をさせていただいて、様々な疑問点を一個一個潰してきていますので、会派としての答えを出すためには、事前に相当勉強してきています。２番は話をしていただいていて、状況もわかっています。現に品川区はやってきていますので、これについては続けていただきたいので、この請願に関しましては、今申し上げたような話の中から、不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"こんの委員","kind":"質問・要望","question":"結論を出すでお願いします。大事というか、そちらも必要なのだというお話がありましたが、私もその課題は非常に強く思っておりますので、３歳児とともに１歳児対策についてしっかりやっていただきたいという要望も含めて、１点目、２点目、３点目、それぞれ項目はありますけれども、今回の請願項目については現行、区としては前に進めているという判断をいたしましたので、不採択でお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"南委員","kind":"意見","question":"たった１名であっても、保育園に継続して預けることができない方を出してしまったということは本当に遺憾なことだと思います。品川区も努力はしておられるけれども、そういう現状に対してなかなかマッチされない状況が出ているということに対して、本当に心を痛めて、議会としても品川区もっと頑張れ、そういう姿勢で臨むべきだと思いますので、非常にそういう思いを強くして、採択を主張したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"松永委員","kind":"意見","question":"本日結論を出すで、不採択でお願いいたします。３番に関しても、入園希望をした全員が入園できる、もちろんそうなのですけれども、品川区としても様々な取り組みをしているということで、今回はその２点に関して不採択ということでさせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"結論を出すということです。請願された方の思いは、文章から読み取らせていただきました。ただ、ご説明の中で、１番については、現状で３歳児の方のその先について確保できるという具体的な説明をいただいていますので、新たにそういった連携制度ができなくてもいいのではないかと思います。現状では撤廃というところまでは求めないということです。ということで、この請願については不採択ということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"}]},{"id":"topic-04","title":"専決処分の報告","agenda":"専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"借りた方の状況というのでしょうか、返済能力、職についているのかどうかというのも含めて、無理のない分納を組まれたということでいいのか、確認させてください。","respondent":"廣田子ども家庭支援課長","answer":"借受人ご本人とお話する際、弁護士も立ち会いで聞いておりまして、仕事を同じ職場に１０年以上、きちんとお勤めをしている方で、収支の確認をさせていただきまして、年間の収入、過去５カ月の平均の収入、月の一番低い収入の金額および一番多いときの金額など全て勘案しまして。","id":"exchange-053"},{"speaker":"南委員","kind":"意見","question":"そうであるなら、様々なご事情がもちろんあったことだと思うのですけれども、平成１９年３月以降の支払いがなかったのは、どういったご事情だったのか、差し支えない範囲でいいのですけれどもお知らせいただければと思います。","respondent":"廣田子ども家庭支援課長","answer":"連帯保証人は母親になっておりますが、母親が全て返還するものと思っていて、連絡をしていたのですが、借受人ご本人は返答をしなかったとおっしゃってあります。話し合った結果、連帯保証人ではなく、自身でお支払いいただくというお話となっています。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/476060?Template=document&Id=4916#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":43484,"voices":177}},{"id":"h29-20170710-5","meetingId":"h29-cm07","date":"2017年7月10日","dateIso":"2017-07-10","committee":"総務委員会","time":"午前１０時００分～午後 ３時１７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件抜き出しています。","topics":[{"id":"topic-01","title":"「議案審査」を行います。 予定表では、(1)の第４２号議案からの審査でありますが、運営上、順番を入れ替えさせていただきまして","agenda":"「議案審査」を行います。 予定表では、(1)の第４２号議案からの審査でありますが、運営上、順番を入れ替えさせていただきまして","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"何点かお伺いします。八潮わかば幼稚園は開園しながらの改修になるわけですけれども、具体的にどこにどう動きながら改修が行われるのか、スケジュール的なものと、場所の移動なども教えていただきたい。子どもたちへの影響も最小にしながらの工事になると思うのですが、その辺が１点。図面なのですけれども、どういうところで作成されたのか、現場内の意見なども入っているのかどうか聞かせてもらえますか。","respondent":"小林施設整備課長","answer":"スケジュールにつきましては、工期が来年の１２月２８日です。こちらの説明資料にあります平面図で下の１階の平面図がありますけれども、半分半分工事を行う予定です。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１つ、工期が１期と２期と分かれるということですけれども、幼稚園のほうを先にやって、幼稚園が動いてから保育園なのですか。どちらの順番が先なのか教えていただきたいのと、図面のところ、主管課と話を進めてというのは、委託してやっているわけではなくて、主管課で図面をつくられているのか、そこの確認をさせていただきたいのが２点目です。","respondent":"小林施設整備課長","answer":"面積の比較につきましては、まことに申しわけないのですが、今ちょっと資料がないのですけれども、今の幼稚園のほうが、たしか私の記憶でいきますと、かなり大きくて、園庭も今日見てもらったと思うのですが、かなり大きいところで。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"平米単価のところは、ぜひ具体的に、こういう改修の場合、どのくらいかかるのかということが知りたいので教えていただきたい。私、必要面積がわからないので、もしわかったら教えてほしいのですが、保育園の場合は、１人３.３平米となっているのですけれども、この現状の園庭で、幼稚園と保育園両方の役割が果たせるのかどうか、その辺も教えてください。","respondent":"吉田保育施設調整担当課長、小林施設整備課長","answer":"保育園と幼稚園が一緒に使う形になるのですけれども、工事後の面積で足りるというふうに認識しております。今、平米単価というお話だったのですが、今ざっとはじいてみたのですが、スケルトン工事でありますので、おおよそ、２０万円ちょっと、２５万円とか、そこら辺だと思います。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"園庭なのですけれども、工事後の面積で足りるということなのですけれども、もしわかったら、幼稚園の必要面積はどうやって割り出しているのか教えてほしいのと、保育園の場合、１人３.３m2、両方足して十分足りるということなのか、もうちょっとそこを教えてください。","respondent":"吉田保育施設調整担当課長","answer":"幼稚園の必要面積につきましては、申しわけございません、今、細かい資料は持ち合わせがないのですけれども、保育園につきましては、もし不足する場合、近くの公園等を園庭として使うことが可能ですので、そちらを含めた形では十分足りた量というふうに認識しております。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後のところ、隣に公園があるので、本当に恵まれている場所で、そんなに心配はないと思うのですけれども、今の課長の言い方のニュアンスとすると、代替を含めるという意味にとれてしまうのですけれども、ここでまかなえているのか、代替、隣の公園も含めて足りるとしているのか、そこはとても重要なので聞かせていただきたいと思います。","respondent":"吉田保育施設調整担当課長","answer":"申しわけございません。詳細につきましては、手元にはないところがありますので、後ほど回答できればと考えています。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"後ほど数字がわかったら教えていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"須貝委員","kind":"質問・要望","question":"今回、落札価格が２億５,６７７万円ということなのですが、実際に見ると、改修工事ということで、躯体工事がなくて、内部改修工事が主な工事だと思うのです。それにしては随分金額が張るのかなと思うのですが、実際、何が一番費用的にかかっているのでしょうか。教えていただきたいと思います。","respondent":"小林施設整備課長","answer":"最大の要因は、１期工事と２期工事に分けたことです。これは使用しながらの工事だということで、まず工期もその分長いというところが最大の要因だと思います。それとあと、各部屋、壁、床、天井、これを全て撤去して、それからまた仕上げをします。","id":"exchange-007"},{"speaker":"須貝委員","kind":"質問","question":"もう１点だけ。いろいろ保育園の園児、また幼稚園の園児も１回移るわけですが、そういう費用も含めてということで、実質、工事だけという金額ではないということなのですか。その辺はどうなのですか。","respondent":"小林施設整備課長、吉田保育施設調整担当課長","answer":"ただ、今言ったように、うちの職員が手伝えるものは手伝っていくという形で行ったり、あと、主管課のほうと調整をしながら、別途大きいものについてはどうやっていくか、引っ越し関係は別途考えていくというところです。例えば、こちらの施設にはピアノがありますけれども、そちらのような大きいものに関しましては、移設のための委託費用等を組んであります。","id":"exchange-008"},{"speaker":"須貝委員","kind":"質問・要望","question":"現在、建物はあって、階層の上の方はそのまま住んでいる中で工事をやるということで、大がかりといっても、内部工事が主だと思うのです。その中でこれだけの金額をかけるということは、その他もそうですが、工事の安全に関しては十分配慮して、迷惑がかからないようにやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"吉田委員","kind":"確認","question":"今の須貝委員のご質問と微妙に関連するかと思うのですけれども、例えば、園庭のテラスへのウッドデッキ新設などというのは、私はこれは非常にいいなと思うのですが、例えば、ここで国産材を使ったりすれば、当然、契約金額が上がるだろうし、できることならそういうちゃんとした素材を使ってほしいと思うので、その辺の素材のこととか、それから、木製家具新設というのも、本当に木製はいいと思うのですが。","respondent":"小林施設整備課長","answer":"当然、既存の図面をまず確認しますので、それについてはアスベストという表記のものはないと私は認識しています。","id":"exchange-010"},{"speaker":"吉田委員","kind":"質問","question":"一方で税金を使いながらの工事ですし、使用するのが子どもたちなので、なるべくよい素材を使っていただけたらと、契約金額との兼ね合いはあるのですけれども、その辺がどうなのかなと思って質問させていただきました。これは意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"構造上のことで１点だけ確認をさせてください。これはスケルトンということで、天井の改修を当然すると思うのですけれども、先ほどの総合体育館と同じように、専門用語で済みません、軽天ではないと私は思っているのですけれども、その辺の天井のこと、当然、お子さんの安全が第一だと思うので、構造のことをお知らせいただきたいと思います。","respondent":"小林施設整備課長","answer":"既製品で、一昔前はなかったのですけれども、今は耐震の吊り天井とかもありますので、部分的にそういうものを使っていくということも手段かなと考えています。","id":"exchange-012"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"当然これ、規模によって、平米数によって、おっしゃったような吊り天井を鉄骨でつくるとかというのはわかるのですけれども、規模に関係なく、天井は、地震が起きたときに、吊り天井だとしても相当揺れが起きると思うので、その辺のところを耐震性を考えた下地をやっていただきたいと思います。これは要望です。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"ありがとうございました。１点だけ。そこのところも確認させていただきたいということと、あと、そこの住民の自治会の方のご理解、たしか昨年の文教委員会でもやった記憶が、この辺の話をした記憶があるのですけれども、住民の方は、これから重機等が入っていく、１階部分をスケルトンにするということに対してのご理解、説明会等について、どのようなご意見があったのか教えていただきたいと思います。","respondent":"小林施設整備課長","answer":"そちらのほうで意見があれば、それが組み込めるというか、設計の中で折り合いというか、なかなか難しいところもありますが、意見が出てくれば真摯に受けとめて、話し合いをもって設計を進めて今回に至りました。","id":"exchange-014"}]},{"id":"topic-02","title":"第４９号議案 中小企業センター空調設備改修第一期機械設備工事請負契約","agenda":"第４９号議案 中小企業センター空調設備改修第一期機械設備工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"この標題のところに「第一期」と書いてあるので、この意味を教えていただきたいと思うのが１点です。老朽化に伴うというご説明だったのですが、ここの空調設備はどのくらい経過をしているのかということと、今回の工事を行うことで、今後、どのくらい耐用年数があるのかということを教えてください。","respondent":"小林施設整備課長","answer":"ここも中小企業センターを使用しながら工事を行いますので、工事をやっているところについては、どこかへ引っ越してもらうということで進めていきますので、一期工事と二期工事、半分半分に分けて実施していくです。ここの建物は、昭和５５年竣工で３５年経過しております。","id":"exchange-015"},{"speaker":"飯沼委員","kind":"質問・要望","question":"資料の４ページのところに、地下１階からずっと書いてありますが、どういった順番で作業をされていくのか、あと、ここは代替の施設というか、集会室の代わりのところはなしでいくのかどうか、そこのところを教えていただきたいのと、ここもアスベスト関係は大丈夫かどうか教えてください。","respondent":"小林施設整備課長","answer":"それと、集会室の代替につきましては、集会所、会議室関係なのですけれども、一気に工事を行うのではなくて、１つずつ進めていく。アスベストについては、既に耐震工事をやったときにアスベストがありましたので、そちらについては撤去済みです。","id":"exchange-016"},{"speaker":"飯沼委員","kind":"質問","question":"代替施設というのは、１カ所ずつやるので、何とかやりくりをしていくということだと思うのですけれども、結果的には、工事を行うところを覆って、廊下とか階段とか共有のところは大丈夫ということで安全にご案内ができるということかどうか聞かせてほしいのと、あと、１つ、契約のところで、辞退が２件出ているのですが、この辞退の理由がわかったら教えてください。","respondent":"小林施設整備課長、立川経理課長","answer":"工事につきましては、当然、資材だとか職人の動線だとか、そういうものを考えて、ラップする場合については、そこのラップしたところの会議室については、残念ですが使用はできません。辞退の関係ですが、こちらは、入札申し込みをした企業において、他の工事との関連で技術者の配置の調整ができなくなったというものです。","id":"exchange-017"},{"speaker":"飯沼委員","kind":"質問・要望","question":"工事の進め方のところについて、やはり利用者が安全に使える部分は十分使っていただきたいということでは、工事のスケジュールがわかりやすく伝わることと、各会議室がどこがどう使えなくなっていくのかということをわかりやすくお知らせをしていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"確認","question":"１つ教えてください。なかなか異例のことだと思うのですけれども、企業努力と言えばそれまでなのでしょうけれども、ほかのところと比べても非常に低い金額で出していて、有名な企業ですから間違いはないと思うのですけれども、どういう事情があったのか。区議会の立場からすれば、しっかりとした工事がこんなに差があってできるのだろうかというところも含めて、そこについて確認させてください。","respondent":"立川経理課長","answer":"こちらの金額についてですけれども、委員ご指摘のとおり、企業努力の賜物というふうに考えております。","id":"exchange-019"}]},{"id":"topic-03","title":"第５０号議案 総合体育館大空間落下防止対策その他工事請負契約","agenda":"第５０号議案 総合体育館大空間落下防止対策その他工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"この標題が、総合体育館大空間落下防止対策となっているのですが、今までは地震の対策などで学校などで非構造部材の工事が行われていたのですが、この大空間落下防止、現地ではいろいろご質問があってお答えがあったのですが、改めてどういう工事なのかというところを教えてください。","respondent":"小林施設整備課長","answer":"大空間とは、いわゆる体育館部分のことを言いまして、建築基準法上では、特定天井という呼び名がありますが、床面積２００m2以上、かつ天井高が６ｍ以上のものについては、特定天井という名称になります。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問","question":"８ページの図面を見ると、半分が斜線なのですが、残り半分のことを教えてほしいのと、今日見せていただいたどこの部分から着手をして、どう進むのか、流れも教えてください。","respondent":"小林施設整備課長","answer":"アリーナは、９月ごろから養生をしながら工事を進めていくところです。その後、スケジュール的には追うような形になるのですが、今日視察した柔剣道場も含めて、後から工事が進んでいく。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問・要望","question":"例えば、今日、ダンスをされていた部屋とか、いろいろな方が利用されているのですが、やりくりというか、全く使えなくなってしまう期間が出てきてしまうのか、いろいろな場所を回しながらうまくやっていけるのか、その辺の調整等はどうなっているのか教えていただきたいのと、あと、この工事の今後の耐用年数はどのくらいか教えてください。","respondent":"池田スポーツ推進課長、小林施設整備課長","answer":"総合体育館の工事についての日程ですけれども、先ほどご説明がありましたように、アリーナから順次工事を行ってまいります。実際には、９月ごろからアリーナの工事をいたしまして、３月に全部オープンというような形になります。最後の質問のどのくらいということをお答えしますけれども、今回のこの特定天井の部分については、吊り天井ではなくて、鉄骨で組んでいきますので、いわゆる鉄骨造みたいな形の下地になりますから、耐用年数でいいますと。","id":"exchange-022"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"大空間ということなので、そんなに区内にも多くはないのかなと思うのですけれども、総合体育館以外にこういったいわゆる特定天井といわれるようなものがあるのかどうか、そこの改修はどうなっているのかを教えていただきたいのと、この工事内容のその他で、ガラス飛散防止フィルム等々が出ているのですが、これは今までやっていなくて、今回こういうものがあるから一緒にやろうというのか。","respondent":"小林施設整備課長","answer":"過去の事例を見ますと、地震の際にガラスが割れて鋭利になったところで裸足では逃げていけなかったという事例もあったものですから、文科省の指導に基づいて、今回はフィルムを張れるところについてはフィルムを張っていくというところで。","id":"exchange-023"},{"speaker":"石田（し）委員","kind":"質問","question":"実際、東日本大震災のときも、この施設、区役所もガラスが割れたりして、私はやっていないのではないかということを再三言ってきているのだけれども、ほかの施設においても、フィルムを張っていないところが存在するのかどうかだけ教えてください。","respondent":"小林施設整備課長","answer":"フィルムについての答弁なのですが、以前、多分お話をしたのが、強化ガラスを設置している小学校、中学校については、製品ができてから１回焼き付けをしますので、一般のガラスより強固になっています。それが割れた際は、粉々に豆粒みたいになります。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問・要望","question":"それと、このその他のところは、特定天井ということで、こういう工事が必要となったついでというか、そういうときを捉えて地震に備えるということと、そのほかにも、こういう工事をする機会に、いずれ必要になる工事ということで入れているということだと思うのですが、金額的には全体の主な工事に比べれば少ないものなのかもしれないのですけれども、この必要とされる時期というか。","respondent":"小林施設整備課長","answer":"ガラスの部分につきましては、プールの関係で廊下からプール側にサッシがあるのですが、そこの部分のガラスを予定しております。","id":"exchange-025"},{"speaker":"吉田委員","kind":"質問","question":"ガラス飛散防止ですけれども、必要とされるのは今はそれぐらいで、それで３０m2になってしまうということですか。ほかに必要とされるようなところはもうないというふうに考えてよろしいのでしょうか。","respondent":"小林施設整備課長","answer":"これは可燃物をそのまま張りつけるのと同じですので、防火の認定をとっているところについては、一切そういうものが張れないというところがありますので、張れるところについて、今回、工事を行っていくです。","id":"exchange-026"},{"speaker":"あくつ副委員長","kind":"提案","question":"先ほど、ご答弁の中にもあったのですけれども、文部科学省の提案でやっていますというお話があった。先ほど、石田しんご委員の質問の中でさまざまありましたけれども、区内にそういう施設があとどれぐらいあるのか、ざっとで結構ですけれども、もしわかれば、もちろんこれは進めていってほしいという観点での質問なのですけれども、今後の方針について教えていただきたいと思います。","respondent":"小林施設整備課長","answer":"１つの見方としては、オリンピック・パラリンピックの後に大規模に工事を進めていくのが望ましいのではないかということで、今現在、検討を進めているところです。","id":"exchange-027"},{"speaker":"あくつ副委員長","kind":"質問","question":"今日伺って、私も不覚ながら、「なんだ、総合体育館は耐震化が終わっていなかったのだ」というのが率直な印象だったのですけれども、学校については、先ほどおっしゃったように、文科省からはやりなさいというものが出ていて、先ほど、建築基準法の規定上、国交省の関係でやったほうがいいですというような感じで、品川区の独自の判断でこれは進めていくということなのかなと受けとめたのですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"}]},{"id":"topic-04","title":"者総合支援施設新築給排水衛生設備工事請負契約、第５４号議案 （仮称）品川区立障害児者総合支援施設新築空気調和設備工事請負契約","agenda":"者総合支援施設新築給排水衛生設備工事請負契約、第５４号議案 （仮称）品川区立障害児者総合支援施設新築空気調和設備工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"さっき、幼保一体化施設のところは、平面図でどういう中身かというのがざっくりとわかるのですけれども、外観がわかることも必要なのですけれども、どういった施設がどこに入って総合的な役割を果たしていくのかということがつかめないので、その辺を教えていただきたいのが１つです。この図面は、どこで作成されたのか。こういうところにあらわれてこない何か理由があるのかどうかを教えてください。","respondent":"小林施設整備課長","answer":"今回、図面で表現しきれなかったところは、こちらの計画建物と斜線が書いてあるところが建物の形なのですけれども、これを平面図に置いてＡ４で作っていくと、かなり細かくなってしまうところがありましたので、添付すると逆にわからないのかなと思いまして。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"新築の建物であるというところにおいて、地上６階、地下１階で新築工事にかかるここの平米単価がわかったら教えていただきたいのが１点です。変わっていって、結果的に退職金がもらえるのともらえないのではすごく違うので、ぜひこの建退共のところの制度の認知度を上げていただきたいと思うのですが、その辺は把握をされているのかどうかお聞きしたいと思います。","respondent":"立川経理課長、小林施設整備課長","answer":"私から、建退共についてご説明します。建退共につきましては、建設業者の退職者共済という制度でございまして、いわゆる一人親方の方に加入していただいております制度になっております。平米単価につきましては、こちらの建物は、約８０万円弱です。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"特に若い人への認知が進んでいないそうです。経験の豊かな方は、こういう制度があるということを知っていて、当然、利用されているというのですが、そういうことも公共工事というからには、企業の側でも、働いている労働者の側でも認知が進むための支援は、やはり区の重要な役割であると思うので、ぜひそこのところを進めてほしいのですが、いかがでしょうか。","respondent":"立川経理課長","answer":"工事中に建退共の共済手帳の提示を求められた場合は、速やかに対応することということで徹底しています。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問・要望","question":"いろいろされているとは思いますけれども、実際的には、どのくらい使われているのかというところで、実際動いているかどうかを見られると思うので、ぜひその辺の把握をしていただきたいのですけれども、いかがでしょうか。先ほど、全体の図面がどこでつくられたのかとお聞きしたので、そこを教えてください。","respondent":"立川経理課長、小林施設整備課長","answer":"先ほどのお話をしますけれども、掛金収納書を現場監督員、工事監督員に提出することになっておりますので、こちらは徹底されているかと考えているところです。設計事務所は、有限会社乾久美子建築設計事務所です。先ほどの平米単価は、建築と電気、給排水、空調と、新築工事なものですから、４業者の全てでお話をしたところです。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問","question":"１点だけ。さっき、建退共のところの掛金収納書を現場監督に出すというところで、でも、そこは出すことになっているということであって、そこに区がチェックをしていくということは含まれていないのですね。チェックをされているのかどうか教えてください。","respondent":"立川経理課長","answer":"必ず掛金収納書を現場の工事監督に提出しろという、そういう指示になっております。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"済みません、ちょっとそこがわからないのです。提出しろとなっているけれども、その中身は、区はチェックをしているのかどうか。ただそういうシステムになっていますというだけではなくて、そこに区がどのくらい関与できて、労働者のための手立てになっているのかという、そこの思いを酌んでいただいて、ご答弁をもう１回お願いします。","respondent":"立川経理課長","answer":"区としましては、事業者のほうに、必ず一定の掛金収納書を購入することということを義務づけておりますので、ですから、現場の職人が工事の監督員、現場の施工責任者に申し出てくれれば、それは証紙がそこで配付されると区としましては認識しています。","id":"exchange-034"},{"speaker":"高橋（伸）委員","kind":"質問","question":"建築工事の構造の部分でお伺いしますけれども、鉄骨造で一部鉄骨鉄筋コンクリートとなっているのですけれども、１６ページの配置図を見ますと、一体化している構造物だと思うのです。一部鉄骨鉄筋コンクリート造というのは、どこの場所になるのか教えてください。","respondent":"小林施設整備課長","answer":"一部鉄骨鉄筋コンクリート造、これはいわゆる地下部分です。地上部分になりますと、鉄骨造に変わるというところです。","id":"exchange-035"},{"speaker":"高橋（伸）委員","kind":"質問","question":"地上は鉄骨ということで、結構これは凹凸のあるような建物だと思うのです。見る限り、この配置図だと、一番下の右のところが入り口になるかと思うのですけれども、交通事情等々いろいろ問題があると思うので、その辺のところをわかっている限りで構わないので教えてください。","respondent":"小林施設整備課長","answer":"こちらは、配置図のほうに駐車場を右下にかいてあるのですが、東側のほうから、大きい道路から入ってくるエントランスはどこだというお話ならば、東から入ってくるアプローチになっております。","id":"exchange-036"},{"speaker":"吉田委員","kind":"質問","question":"こういう設計とかはよくわからないのですけれども、障害児者総合支援施設ということで、非常階段、階段とは限らないですね、どのような非常用設備を予定しているのか。一部、消火設備とか、そういうことについては概要のところに出ているのですけれども、配慮が必要だと思うのですが、逃げるための設備がどのように設計されているのか教えてください。","respondent":"小林施設整備課長","answer":"それと同時に、ここの用途が障害児者総合支援ということもありますので、エレベーターは３基あるのですが、そのうちの１基を非常用エレベーターにしております。エレベーターで避難ができるような経路を確保しています。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"エレベーター、そこだけ電気系統が独立しているとか、そういう意味なのでしょうか。ごめんなさい、設計のことがよくわからないので、もうちょっと詳しく教えていただきたいのですが。","respondent":"小林施設整備課長","answer":"委員おっしゃるとおりです。発電設備を設けておりますので、発災時に電気がとまった場合には、自前の発電機が動いて、７２時間は動きますので、そちらのほうでエレベーターが稼働するような設計をしておるです。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"もう１つ、さっき一緒に聞けばよかったのですけれども、屋上に発電設備というふうにあるのですが、これはどういう設備で、どれくらいの発電量を予定されているのか教えてください。","respondent":"小林施設整備課長","answer":"屋上に５.５キロワットの太陽光パネルを設置しております。どの程度といいますと、大体５.５キロワットといいますと、計算上、曇りもありますので、年間８０％ぐらい稼働するとすると、アンペア数にすると、約３０アンペア。","id":"exchange-039"},{"speaker":"吉田委員","kind":"質問","question":"ばらばら聞いてごめんなさい。いつも私、こういうエネルギーのことで、再生可能エネルギーのことをよく聞くのですけれども、もう１つ、品川区は、今年度、環境３計画の見直しの年だと思うのですが、この前の計画のときに、わりとこういう設備で雨水の利用を進めているということが出ていたのですけれども、その辺の活用は、この新築の建物について考えられていないのか、その辺を教えてください。","respondent":"小林施設整備課長","answer":"どういうところに使うのだと言ったら、先ほどと同じなのですが、全館の照明、それとコンセント、全館の照明を間引きして最低限にすれば、その分、７２時間使用できるところが少し伸びていくというところで、現在のところは。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"参考にお聞きしたいのですが、このぐらいの規模の障害児者総合支援施設ということなのですが、これぐらいの規模になると、防犯上、いろいろな対策が、防犯カメラ等も含めてそうなのでしょうが、警備とか、それはどのぐらい対応しているのでしょうか。電気が通る通らないにかかわらずあるのですが、障害者にとってはエレベーターだけが避難経路で、配備は１基だけなのでしょうか。","respondent":"小林施設整備課長","answer":"防犯につきましては、ここは職員が２４時間いる施設です。それとあと、防犯については、防犯カメラを外部や共有部分だとか、エレベーター内とか、そういう要所のところに設置を予定しているというところです。","id":"exchange-041"},{"speaker":"須貝委員","kind":"質問","question":"もう１つ、例えば、お体が不自由な方もいらっしゃると思うのです。そういうときには、もちろん一般の非常階段は使えないわけですが、そういう方たちの避難するようなスロープとか、そういうものは、この施設で設けているのでしょうか。","respondent":"小林施設整備課長","answer":"スロープ等は設けておりません。ただし、先ほど私も言い漏れて申しわけないのですが、こちらについては、全館、火災が起きたときには、自動で消火に当たる天井づけのスプリンクラーがありますので、基本的にはまずそれで対応する。","id":"exchange-042"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"一番最初に厚生委員会で説明を受けたときは、設計事務所はたしか２つあったと思うのですけれども、これが恐らく今は１つになってしまったのかなというところで、今後、先ほど、高橋伸明委員からもありましたけれども、先ほどのかなり多様なサービスのせいなのか、また、乾久美子さんという方はアールブリュット美術館等の設計をされている方ですから、デザイン性が豊かといいますか。","respondent":"小林施設整備課長、中山障害者福祉課長","answer":"それとあと、エレベーターだとか、上の階に行ったりだとか、縦の動線を、このエレベーターは誰でも使えるわけではなくて、カードリーダーで対応するだとか。かなりでこぼこがあって、そういう意味では心配なところも多少あるにはあるのですが、ただ、やはり居心地のよさですとか。月に１回、月例会がありまして、今後は主管課も交えてやっていきますので、設計事務所ないしはゼネコン関係、今のＪＶ関係ですが。","id":"exchange-043"},{"speaker":"あくつ副委員長","kind":"意見","question":"本当に期待していますし、日本の福祉事業者、また障害当事者の方からは、本当に非常に期待がかかっている施設だと思いますので、ぜひまた注力をしていただいて、日本に冠たる施設をつくっていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]},{"id":"topic-05","title":"の(10)第５６号議案 しながわ区民公園中央ゾーン（西側）改修工事請負契約の変更","agenda":"の(10)第５６号議案 しながわ区民公園中央ゾーン（西側）改修工事請負契約の変更","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"公共工事設計労務単価の運用に係る特例措置に基づいて、新労務単価に変更ということなのですが、これは１００万円余です。この辺の計算が、賃金水準が、例えば働いている人にどうこれが影響するのかということがちょっとわからないので、もうちょっと詳しく教えてください。","respondent":"立川経理課長","answer":"いわゆる公共工事の設計労務単価につきましては、平成２５年以降、毎年上昇しております。最近の傾向ですが、この３年間で東京都では平成２７年２月が２.５％、平成２８年２月が２.８％、今回の平成２９年３月が１.６％の上昇です。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"そうすると、この案件以外にも出てくるということでしょうか。","respondent":"立川経理課長","answer":"第１回定例において議決いただいた契約案件において、この労務単価の変更により申請があったのは、この１件だけです。","id":"exchange-046"},{"speaker":"あくつ副委員長","kind":"質問","question":"今のお話なのですけれども、申請があったのが１件だけということなのですが、これは区のほうから、労務単価の変更があったから、どうですか、申し出てくださいというお声がけをして、ほかの業者にも全部しているのかどうか。前にもたしか同じような質問をしたことがあると思いますけれども。","respondent":"立川経理課長","answer":"こちらにつきましては、個々に契約した事業者、また、区のホームページを使いまして、労務単価の変更がありましたので、どうぞ申請していただきたいということで周知しています。","id":"exchange-047"},{"speaker":"須貝委員","kind":"質問・要望","question":"意見だけなのですが、逆に、これは区のほうにも要望したいのですが、やはりこうやって労務単価が変わりました、上がりました。ですから再見積書を提出してくださいということならば、私は聞いたことはないのですが、逆に労務単価が下がったときに、必ず下げますと、下げましたというようなこともやっぱり必要ではないかと。公平公正な指導をすべきではないかというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"}]},{"id":"topic-06","title":"第４２号議案 職員の退職手当に関する条例の一部を改正する条例","agenda":"第４２号議案 職員の退職手当に関する条例の一部を改正する条例","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"お聞きしたいのですが、この条例は国のほうからこういうふうにしなさいと、雇用保険法等の一部を改正する法律が施行されたということで、そういうふうに来たということならば、これは職員の退職手当に関することですが、民間の一般の方、勤労者がこういうふうな状況になったときも、これは適用させれるということなのですか。","respondent":"黒田人事課長","answer":"法改正は雇用保険についてですので、公務員は雇用保険に入っておりませんので、原則として民間の雇用保険を受給される方の法改正がありまして、公務員は雇用保険に入っておりませんので失業手当は基本的に受けないのですが、就職して短い期間で退職しますと。","id":"exchange-049"},{"speaker":"飯沼委員","kind":"質問","question":"一番下のところに個別延長給付とあって、これが新しく追加をされたということですね。これができた背景がわかったら教えてほしいのと、対象の方は、今、課長がおっしゃったように、短期で退職をされて、民間のところで失業給付をもらえる方との差異が生じたところを埋めていくという理解でいいのか教えてください。","respondent":"黒田人事課長","answer":"雇用保険法の改正の趣旨につきましては、さまざまあるのですが、今回のところにつきましては、もともとリーマンショック時に創設した失業給付については暫定ということがございまして、その期限が平成２８年度末までとなっていたことから、必要な措置というところで。","id":"exchange-050"},{"speaker":"飯沼委員","kind":"質問","question":"文言の中身を教えてほしいのですが、Ａ４の１ページ目の表の中に書いてある※印がついている「所定給付日数を限度とする」というこの中身がわからないのと、あと、新旧対照表の第１３条第７項の(2)のところのアに「特定退職者」と書いてあるのですが、これの意味を教えてください。","respondent":"黒田人事課長","answer":"所定給付日数ですが、失業給付につきましては、年齢の区分ですとか、勤続した期間によって基本手当を支給される期間が違いますので、それは退職者の年齢とか、今申し上げた勤続年数に応じて、９０日であるとか、１２０日というような形で区分が分かれますので。","id":"exchange-051"},{"speaker":"飯沼委員","kind":"質問","question":"これまでのご説明だと、新たに加わる部分があって、退職者にとって不利益となることはないと今受けとめているのですが、１つ大もとのところの雇用保険法の改正の中身において、ちょっと気になっているのが、失業等給付に係る保険料率と、国庫負担率の時限的な引き下げ、両方とも下げるというところが３年間ぐらいあると書かれいるのですが、ここの問題は。","respondent":"黒田人事課長","answer":"先ほど申し上げたように、公務員は雇用保険に入っておりませんので、雇用保険料は、いわゆる事業主負担分も雇用者負担分も負担しないという意味において言えば、雇用保険料の改正については、公務員については直接影響するものではございませんが、当然。","id":"exchange-052"}]},{"id":"topic-07","title":"の(2)、第４３号議案 品川区特別区税条例の一部を改正する条例","agenda":"の(2)、第４３号議案 品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"飯沼委員","kind":"提案","question":"１つの条例改正案の中に７項目も入っているというのは、なかなかわからなくて、すごくわかりやすい資料をつくっていただいたので、この資料を見ながら質問したいと思いますが、まず１点目の軽自動車税のところで、Ａ３の横のところで、(1)の4)のところに、納税義務者が正当な事由なく申告をしなかった場合ということで、１０万円以下の過料を科するとありますが。","respondent":"榎本総務部長","answer":"１点目の軽自動車税の過料の部分ですけれども、これについては変更等はございません。それから、２点目の２％の部分ですけれども、今現在、軽自動車税の取得税が２％なので、環境性能が達成していないものについての２％の税率は従前どおりという形です。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問","question":"最後のところで、区への影響はプラスになるのかマイナスになるのか、その辺はざっくりわかるのでしょうか。","respondent":"榎本総務部長","answer":"基本的にこの配偶者控除の改正においては、区民税の減収が見込まれるという形になっております。","id":"exchange-054"},{"speaker":"須貝委員","kind":"質問","question":"ちょっとわかりにくいので、第４３号議案の(7)についてお聞きしたいのですが、配偶者控除・配偶者特別控除見直しに伴う規定整備ですが、従来と比べてどういうふうに変わるのですか。例えば、勤労者、ご主人が収入がある程度ある、１,０００万円を超えていると、やはりそこでいろいろ変わってくるのですか。お聞かせください。","respondent":"榎本総務部長","answer":"２ページ目の下の参考の表を見ていただきたいのですけれども、例えば、配偶者控除の場合ですと、配偶者控除、今までは世帯の年収に関係なく３３万円の控除が全員受けられた。","id":"exchange-055"},{"speaker":"須貝委員","kind":"質問","question":"ですけれども、今度、奥様に対して、普通は今までは配偶者控除があったのですが、それがなくなるというような解釈でよろしいのですか。違いますか。","respondent":"榎本総務部長","answer":"この限度額を超える人については控除額はなくなるという形です。","id":"exchange-056"},{"speaker":"須貝委員","kind":"質問・要望","question":"これ、品川区に対して、今、三位一体改革があって、所得税との絡みで、品川区の区民税が高いのではないかとよく私も言われるのです。品川区は区民と密接なかかわりがあるのですから、そういう説明もきちんとしていただけると助かります。意見で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"須貝委員","kind":"質問・要望","question":"区は区民にしっかり説明をしていただきたいと思います。今回は国から来た案件なので、賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"}]},{"id":"topic-08","title":"「」を聴取いたします。 平成２８年度品川区一般会計予算繰越明許費繰越計算書","agenda":"「」を聴取いたします。 平成２８年度品川区一般会計予算繰越明許費繰越計算書","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"済みません、１点わからないので教えてください。土木費の都市計画費のところで、大井町駅前と武蔵小山の駅周辺再開発事業が出てくるのですけれども、この繰越額が左の財源内訳で、国と都の支出金等と、さっき、国庫と言っていますね。それと一般財源と同額ずつ２つに分かれているのは、これはどういう意味があるのか教えてください。","respondent":"秋山財政課長","answer":"再開発補助金につきましては、国が２分の１負担というスキームになってありますので、補助金のうちの半額を国が国庫支出金ということで負担するということで同額ということになってあります。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"一般財源が同額、これはもともとは財調ですか。一般財源というくくりにしているのですけれども、財調から持ってきている一般財源なのですか。その中身を知りたい。","respondent":"秋山財政課長","answer":"財調につきましては、これは特定の財源ではございませんので、一般財源として入ってくるということになっておりますので、財源としては普通税とかと同じ一般財源というふうにお考えいただいて、ただ、財調の計算の中で。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"前に計算式を教わったことがあって、ああ、そうなのだと思ったときがあったのですが、今よくわからないので、再開発に対する財調からのお金の入り方とか、また後で教えてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"}]},{"id":"topic-09","title":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","agenda":"「その他」を行います。 まず、今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、総務委員会にかかわる項目","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"アトレで期日前投票者の２割が投票されたということで、やっぱり便利ということであるのかというふうに思うのですが、ここでいわゆる選挙割というものを試されたのですが、何かそういうものが利用された数というか、そういうのは把握が難しいやり方だったというふうには思うのですけれども、その辺を数字を把握されているようでしたら教えてください。","respondent":"安井選挙管理委員会事務局長","answer":"それ以降については、たまたま夏のセールをやるということで、２,０００人はそういった恩恵を受けたのではないかと考えています。","id":"exchange-062"},{"speaker":"吉田委員","kind":"質問・要望","question":"はこれ、アトレが取り組まれたということはとてもよかったというふうに思うのですけれども、若干案内が、私、実は行ったのです。気がつかないです。特に渡されるわけではなくて、そういうふうに意識して行った人が、「あれ？これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"飯沼委員","kind":"質問","question":"品川区の投票率が伸びたことはとてもよかったなと、これからもっと伸びてほしいなと思っているのですが、１８歳が有権者になってからのところで、地域の方からも若い人の関心はどうだったのかという質問を受けているので、１８歳とか１９歳の投票がどうだったのかということも、今日お話いただけるかなと思ったけれども、その辺も突っ込んで調査をして報告をしていただければ、また、どういう要因で。","respondent":"安井選挙管理委員会事務局長","answer":"投票の台帳を、期日前とかの集計も含めて全部一体化させるという作業がまだできていませんで、若年層の投票率はデータとしてはまだ出てきておりません。もう少しでそちらのデータを全部フォームアウトできるので、結果が出ればご報告したいと思ってあります。","id":"exchange-064"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"関連するのですけれども、先ほども局長のほうからあったのですけれども、開票のときに集計ミスがあったということで、これはうちの会派でも周知がされまして、必ず総務委員会で取扱うことだと思ったものですから、確認のために、質問ではなくて、重ね重ねの指摘になるのですが、その集計ミスの内容が、わかってみれば、そんなに大した内容ではなかった、大変な問題ではあるのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/577253?Template=document&Id=2080#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":47894,"voices":261}},{"id":"h29-20170711-6","meetingId":"h29-cm07","date":"2017年7月11日","dateIso":"2017-07-11","committee":"区民委員会","time":"午前１０時００分～午後 ０時０３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件抜き出しています。","topics":[{"id":"topic-01","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"中塚委員","kind":"質問","question":"今日はまず概要的なお話で、現在、品川区として取り組んでいる事業や支援策についてご説明があったと思います。文化振興とスポーツ振興と、一応２つの課に分かれているので、共通することもあるかと思うのですけれども、文化振興・スポーツ振興に当たっての現状の課題について、また、今後の支援や取組みの方向性について、それぞれまずお考えを伺いたいと思います。","respondent":"鈴木文化観光課長、池田スポーツ推進課長","answer":"したがいまして、今後の支援の方向性につきましては、様々な団体の方のご意見も伺いながら、少しでも活動しやすい環境整備と具体的な活動の支援が中心になるかと考えております。今後、競技スポーツにも多くの方が参加していただくよう力を注いでいきたいと考えているところです。","id":"exchange-001"},{"speaker":"中塚委員","kind":"質問・要望","question":"おっしゃるとおり、活動団体が増えれば、当然、施設がとりにくくなるという関係にもあるので、より一層の充実が必要だと思いますし、支援の内容やあり方についても、より充実が必要だと思うのですけれども、今日の資料の３ページ目に「懇話会の設置」がありまして、提言等を受ける機会として年１回やっているということですけれども、具体的に団体から近年どういうご要望があるのか。","respondent":"鈴木文化観光課長","answer":"各団体はかなり文化プログラムを意識しながら活動に取り組むなど、いろいろな新しい工夫をしていただいている中で、１つ出た大きな意見は、それぞれがしっかりとやっている内容を、今度は連携して実施することで。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問・要望","question":"多様な要望がありますので、このビジョン策定のときには随分詳細に、どういうニーズや区民の活動実態があるのか、アンケート調査を行いましたけれども、東京オリンピックに向けてという意味合いも含めて、改めて文化芸術・スポーツに関する区民アンケートを実施して、今の実態の把握や、個人であったり団体であったりアンケートのとり方は工夫が必要ですけれども、アンケート調査を実施して、支援の充実。","respondent":"鈴木文化観光課長","answer":"それから支援のあり方についてですが、それについても、その中で意見をいただいて、実は今やっている支援の拡充、充実させたり、また範囲を広げたりということも今後検討の必要があると認識しております。","id":"exchange-003"},{"speaker":"中塚委員","kind":"確認","question":"そういう意味でも、このような理念を、節目、節目でしっかり確認していくことは大事ではないかと思うのです。そういう意味では、世界人権宣言や文化芸術振興基本法、スポーツ振興基本計画の理念に触れる機会をつくっていただけたらどうかと、１点お伺いしたいと思います。そういう意味で、指導者の育成・確保の支援が大事ではないかと思うのですけれども、この点についてはいかがでしょうか。","respondent":"鈴木文化観光課長、池田スポーツ推進課長","answer":"確かに、今行っている支援の中では、その理念自体を取り上げる場面がありませんので、ご指摘のとおり、確かに好きでやっている方たちも多いのですが、それ以前に、このような理念に基づいて皆さんに文化に触れていただく。指導者の育成についてですけれども、指導者ということになりますと、少年少女のスポーツの指導をされている方が一番重要なポジションだと考えています。","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"それがひいては学校でのいじめの克服のきっかけにつながったり、難しい授業を１回やるよりも昼休みに一緒に遊ぶと学校全体が明るくなったり、運動会などの企画一つで学校全体がまとまるという力もありますので、ぜひその点についてはしっかり位置づけて進めていただきたいと思うのですけれども、改めていかがでしょうか。","respondent":"池田スポーツ推進課長","answer":"実際に、私どもとしましては、競技スポーツ、少年少女スポーツ、そして地域スポーツにおきましても、こういったことが一切ないようにということで、今後、各団体と話をいたしまして、最初の目的であります「いつでも、どこでも、だれでも、いつまでも」。","id":"exchange-005"},{"speaker":"渡辺委員","kind":"質問","question":"そのような前提で伺っていきますが、例えば文化のほうでいろいろな発表の場があると。コンテストの類い、審査の類いは、制約というか考え方の中であるのでしょうか、あるいはフリーなのですか。私は、できればこのようなものは活性化のために、やりがいのために、行政が一歩踏み込んでいってもいいのではないかという思いから、まず、それを最初に教えてください。","respondent":"鈴木文化観光課長","answer":"現在、区で実施している事業自体では、直接審査、それから順位をつけるという形のものはございませんが、区民の方に行っていただいている合唱祭や演奏会においては、専門の方から講評をいただいたり、今後の活動の参考になるような意見をいただくことはやっておりまして。","id":"exchange-006"},{"speaker":"渡辺委員","kind":"質問","question":"伺った中でこれからを考えたときに、地域スポーツ・競技スポーツ、文化と両面で聞いていきます。何を聞きたいかというと、数値目標をどう捉えるか。今、参加人数や競技人口、いろいろそれぞれ把握されていると思うのですが、それぞれスポーツの種別ごとに数値目標をどう考えるか。ひいては、それが多分、品川区全体のレベルアップになっていくと思うのです、その辺をまず教えてください。","respondent":"池田スポーツ推進課長","answer":"運動、地域スポーツ、それから競技スポーツを含めてですけれども、運動ということで考えますと、週１回運動する方の数値目標が、国では３分の２、約６６％、都では７０％を数値目標としています。","id":"exchange-007"},{"speaker":"渡辺委員","kind":"提案","question":"何か明確な目標値、３年計画、５年計画を立てるべきだと私は思うのですが、その辺の考え方をひとつ伺います。もう一つそれに関連して、やはりリーダー養成だと思います。この仕組みづくり、制度づくりは、掘り起こしも含めて行政がやるべきではないかと。それがまず一つ、その辺の拡充についてどうお考えか。少し提案ぎみなのですが、ぜひお考えをお知らせください、スポーツに限定します。","respondent":"池田スポーツ推進課長","answer":"最初に、リーダーの育成ですけれども、リーダーにつきましては今、私ども、地域スポーツの観点でいきますと、地域スポーツクラブが２カ所できていまして、今から残り２カ所つくって、全区ちょうど２０２０年には区内全域で地域スポーツクラブが完成する予定になってあります。","id":"exchange-008"},{"speaker":"渡辺委員","kind":"質問・要望","question":"ここでのネックは、上がっていけば上がっていくほど、費用も、日数も、取得に対してすごくかかる。野球で言えば打ち方を真似する。それはハイレベルなものを提供することで格好の普及になるのではないかという意味で、このプロ活用をどう考えられるのか、私はすべきという観点で伺いたいと思います。今もうまく時間のやりくりでやっていると思うのですが、もう一回これを見直されたらどうかと。","respondent":"鈴木文化観光課長、池田スポーツ推進課長","answer":"ただ今後、もう少しいろいろな分野、多くの方のプロに参加いただいて、また、それに触れる機会は、事業の中のプログラム一つにも組み込めるかどうかは、検討したいと考えております。スポ・レク組織に入っていない社会教育関係団体の方につきましては、調整会議に参加できないと、空いているところでの予約となっていますので、スポーツに関しては社会教育関係登録団体についてはプレミアといいますか。","id":"exchange-009"},{"speaker":"渡辺委員","kind":"質問","question":"それぞれありがとうございました。別にメジャースポーツだけでなく、ちょっとした文化的なものもそうですし、趣味でつながるのはものすごい絆になると思うので、これをもう少しレベルアップといいますか、掘り下げたらどうかと思うので、「交流」という観点から国際交流、そして区市町村交流、なおかつ文化とスポーツそれぞれでどう組み合わせたらいいのかという思いで伺いたいと思います。","respondent":"遠藤協働・国際担当課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"国際交流の面での文化・スポーツ、文化のつながりというお話だったかと思いますけれども、例えばポートランド市と姉妹都市を結んでいるところですが。あちらなどは全国の自治体と文化の白蛇というキーワードでつながるということで、個々の事業としては取組みが始まっているところですので、それを今後。ということで、交流事業につきましても、まず区民の方の使用を優先させていただいた上で、そういったものができるかどうかということについては。","id":"exchange-010"},{"speaker":"渡辺委員","kind":"提案","question":"これは、ポートランド市や今ある限られたものではなく、東京２０２０に向けて開けていくものという捉え方があるので、ぜひそういういい事例を他の種目、あるいは他の国に広げるべきと思うので、これは要望で終わりますが、ぜひお願いしたいと思います。それこそ地域資源の再発見などの格好の種なので、これをどう活かすか。最後は要望で終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問","question":"子どもたちは本当に一生懸命自分がどんどんうまくなるようにと練習を自主的に行っているので、その場の確保をほかの課とも連携して進めていってほしいと思うのですけれども、そのことに関してお伺いさせていただければと思います。","respondent":"池田スポーツ推進課長","answer":"スポーツの種目にもよるのですけれども、私どものスポーツ協会では、フリー教室、スポーツ教室がございまして、卓球やバドミントン、バスケットボール、バレーボールといったものが定期的に毎週、戸越体育館、総合体育館でフリーの利用ということで教室を行っておりますので。","id":"exchange-012"},{"speaker":"田中委員","kind":"提案","question":"公園なのですけれども、子どもたち、バスケットボールやサッカーや野球などを自主的に練習したいというときの場がないことがあって、土地の活用はなかなか子どもたちの声が届きにくいので、できれば子どもたちがスポーツを活発にできるような場所の提案というか、ほかの課、公園課などと一緒に、その中に意見として出していただければと思いまして、お願いします。","respondent":"池田スポーツ推進課長","answer":"港区と品川区のちょうど重なり合っている八ツ山のほうの公園にもう一カ所ございまして、そこでも３ｏｎ３というバスケットボールはできます。先ほど言いました体育館でもご利用いただければと思います。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問","question":"自分の家からは、こことここの公園が近いのだけれども、ここに行くと、ほかの学校の子がいてとか、仲良くやれるときとやれないときがある。そうすると、またもっと遠くの公園に行かなければいけないということもあるので、子どもたちがスポーツの自主練習をできる場所がもう少しできたらいいと思って質問させていただきました。","respondent":"池田スポーツ推進課長","answer":"野球についても、キャッチボールもできる公園が何箇所か区内にもありますので、そちらをご利用していただくということになってまいりますので、そこで区分けをいただければと思います。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"増えたらいいなと思っているので、公園課と連携して、もっと言っていただけたらと思います。要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"文化振興もスポーツ振興もぜひ振興していっていただきたいのですけれども、この２つに共通するのが、スポーツに関しては公益財団法人品川区スポーツ協会、文化に関しては公益財団法人品川文化振興事業団と連携して協力をしていくという形になっていますので、なるほどと思って質問するのですけれども、だからここの事務局には区役所を定年退職した方が数多く行かれているのですか。","respondent":"鈴木文化観光課長、池田スポーツ推進課長","answer":"ただ、すみません、人事に関することなので、そう考えられるというところまでは私からお答えできますけれども、具体的にどのように決めているかとか方針についてはお答えできないので。スポーツに関しても、どのようないきさつでこのような人事になっているかというところまでは全くわからない状況です。","id":"exchange-016"},{"speaker":"藤原委員","kind":"質問","question":"いや、その答弁でよくわかりました。もう少し踏み込んで言うならば、品川区においてのシステムの中で指定管理者という制度があります、この２つは指定管理者に入っているわけですよね。いろいろ指定管理でプロポーザル等をしたときに、このような形で偶然かもしれませんけれども、品川区の職員が行っているということが指定管理者を決めるときの採点というかポイントには、現実の意味であるのですか。","respondent":"鈴木文化観光課長、池田スポーツ推進課長","answer":"しっかりと区の施策に沿った事業を提案して実施できるかどうか、これに基づいて審査をしています。スポーツにおきましても同様にプロポーザルを行いまして、現在の指定管理者となっているところです。","id":"exchange-017"},{"speaker":"藤原委員","kind":"質問","question":"課長、それは当然でしょう。区の職員が行っているから指定管理者のポイントが上がりますとなるわけがないとわかっています。全く知らない方が申し込んではこないとは思うのですけれども、私はそれはいいという意味で質問をしているわけであって、指定管理を選ぶときの項目に区役所の元職員がいるのがプラスになるわけがないではないですか。答弁は要らないです、どうせわかりませんという答弁ですから。","respondent":"鈴木文化観光課長、池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"それから２点目で、関係する各課との連携による事業・取組みですが、これは既にご指摘の高齢者の方の部分や障害のある方の部分、高齢者福祉や障害者福祉等。今、設立準備を行っております荏原Ａ地域のスポーツクラブでは、学校を利用しているスポーツサークルだけではなく。","id":"exchange-018"},{"speaker":"藤原委員","kind":"質問・要望","question":"スポーツで伺いたいのですけれども、公益財団法人品川区スポーツ協会と協力・連携をしているわけですよね。何で公益財団法人になったかというと、私はコンプライアンスが一番大事だと思っているのですけれども、そのような意味において、これは要望でもあるのですけれども、答弁もいただきたいのですけれども、品川区スポーツ協会にはいろいろな協会が入っていますよね、連盟といいますか。","respondent":"池田スポーツ推進課長","answer":"今の財政的なお話だと思うのですけれども、私どもでは、品川区スポーツ協会から配下にあります連盟に配分している金額についてのお金が正しく使われているかどうかということでの把握をしているところでございまして、連盟独自の会費もしくは事業予算等についてまでは。","id":"exchange-019"},{"speaker":"木村委員","kind":"質問","question":"その中でテニスをするには狭すぎる。そういうものもすごくいいのではないかと思うのです。その方たちを外に出すためには、地域でスポーツを通じて、また、いろいろなレクリエーションを通じて外に出ていただく方法があろうかと思うのですが、今、区内の高齢者の方々でそういう閉じこもりの方はどのくらいいるのかとか、あとはそういうふうな考えはあるかどうか、何かあればお聞かせください。","respondent":"池田スポーツ推進課長","answer":"私どもで荏原Ｂ地域スポーツクラブがありますけれども、そちらで健康教室を毎週１回やっているのですが、午前中にもかかわらず、毎回８０人から１００人程度の方が参加するというようなことも定着していますので、毎回、定着したスポーツをやれば。","id":"exchange-020"},{"speaker":"木村委員","kind":"質問・要望","question":"ですから、指導者の皆さんにとっても、これはどこを基準にしていいのかということは大変難しいところであろうかと思いますけれども、今現在でも、体罰と捉えられるような指導が区でも多く行われているのかどうかがわかれば教えていただきたいと思います。","respondent":"池田スポーツ推進課長","answer":"体罰の線引きですけれども、これははっきり言って非常に難しいところだと思いますので、お答えできないかなと思っています。学校の部活動等については、具体例はあると思いますけれども、私どもで把握しているのは以上のところです。","id":"exchange-021"},{"speaker":"木村委員","kind":"質問・要望","question":"高齢者の皆さんにとっても１日でも元気に自分の足で歩くことができるよう、ご指導のほどをお願いしたいと思います、これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"体罰の定義をお答えできないというのは、これは重大だと思います。言葉による暴力、肉体的な暴力、相手の人権や尊厳を傷つけるもの、それを私は体罰だと思うのです。スポーツには厳しさは必要ですけれども、厳しさと体罰は明確に違いがあると私は思うのですけれども、その辺についてはしっかり体罰とは何か定義をご説明いただきたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そういうものの技術の習得だけでなくして、指導法を、徹底的にいろいろな指導をやっているところなので、そこら辺については明らかになっているとお答えします。","id":"exchange-023"},{"speaker":"塚本副委員長","kind":"確認","question":"特にこれからオリンピック・パラリンピックに向けてそういう機運が区の中で広まってくるということがあって、そういう見通しがあるかどうかを一つ確認したいのと、そういう行政需要が様々な中で、特にこのスポーツまた文化に対する区民のニーズを所管課としてどのように受けとめているのかというところについて、それぞれお伺いしたいと思います。","respondent":"安藤文化スポーツ振興部長","answer":"そしてまた、少ないところを皆さんの工夫でもって１つのところを２つに分けるだとか、両方合同で使うだとか、そういう工夫を利用者の皆さんで考え出している。それが先ほどから再三言っているスポ・レク推進委員会や総合型地域スポーツクラブ、そういうようなものなのです。","id":"exchange-024"},{"speaker":"塚本副委員長","kind":"意見","question":"確かに非常に難しい課題なので、あえて聞いたところもあるのですけれども、いわゆる区民のいろいろと様々な行政需要の中で、限られた資源、予算をどう充てていくかという問題等に直結することなので、今、部長にお答えいただいた思いというか、この文化・スポーツを振興しようとしていく方向に向けての様々な努力がうかがえる部分もありましたので、そういった方向で少しでも進んでいくように。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"}]},{"id":"topic-02","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"やはりそういう意味において、いろいろ九州という意味の自治体として、今、対応していると思うので、その辺を先方とのお話としてぜひ考慮をしていただきたいのと、もう一点は、秋という意味においても、気象という意味でまた大雨がという形においても、私も佐賀の２つの調査項目についてはすばらしいとは思いますが、そういう意味で大雨被害。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"}]},{"id":"topic-03","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"改めまして自民党の石田秀男議員の質問の２番の観光についての中で、今、委員長もお話しして下さいましたが、品川歴史館の学芸員の今後について、具体的な答弁をいただきたいので、よろしくお願いいたします。","respondent":"鈴木文化観光課長","answer":"それから本体の品川歴史館の施設も大分老朽化が進んでおりますので、トータルで今後、品川歴史館をどうするかというあり方を検討する中で、その規模や内容によって学芸員の体制、必要な数も変わってきますので。","id":"exchange-027"},{"speaker":"藤原委員","kind":"質問・要望","question":"もう少し踏み込んで答弁いただけるかと思ったのですけれども、この件に関しては、去年の決算特別委員会および今年の予算特別委員会でも要望・質問させていただいて、検討してください、まずしてくださるということ。ただ、もうオリンピック・パラリンピックは３年後ですよね。そういう意味においても、検討を１日も早くしていただいて具体的にどうしていくか。","respondent":"鈴木文化観光課長","answer":"今、検討を始めたところと申し上げましたが、今検討しているものを踏まえまして、８月以降の来年度予算編成に反映させるべく検討を急いでいるところですので、その辺の内容がしっかりとして方向性が見えましたら。","id":"exchange-028"},{"speaker":"中塚委員","kind":"質問・要望","question":"品川歴史館に指定管理者制度を導入したらどうかという質問に対して、答弁全体として検討するという流れだと思ったので、要するに学芸員を正規雇用化しても、指定管理者制度にしてしまったら、またその身分がどうなのかと、聞き間違えていたらごめんなさい、という思いがあって伺いたいのですけれども、要するに品川歴史館の指定管理者制度の導入を品川区は検討されているのかどうか。","respondent":"鈴木文化観光課長","answer":"ご指摘の指定管理ですけれども、これ自体は石田議員からのご質問は、茶室を改修して、そこにレストランをつくってはどうか、その部分についての指定管理ということでご質問いただきまして、それについては効率的な運営を検討する中で候補にしますというお答えであります。","id":"exchange-029"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"事件の解決を願うばかりなのですけれども、率直に言って続いているということで、近隣の方はすごく不安に思っていまして、重い空気が流れているというのでしょうか、それは私もすごく感じます。住民や町会や商店街の方々へ、情報を密にとってというのはそのとおりだとは思うのですけれども、この場で私が言えるのは、ぜひ丁寧に住民や町会や商店街に対応していただきたいとお願いだけしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"ちょうど昨日のその他で、私はコンビニのことを伺って、この頃続いていますと。その辺をもう一回よく考えていただいて、それで課長、偶然にもこの課長になる前に、大井警察署ではないですか。やはり地域をご存じの課長ではないですか、生活安全課の課長さんだったわけですから。","respondent":"菅生活安全担当課長","answer":"今後、またこの地域、私が大井署にいたときには非常に平和な地域だと思いましたけれども、最近、殺人だ、強盗だということで、少しずつ治安が悪化している状況ですので、また改めまして各部署と連携しながら、また町会の方、地域の方とも連携しながら。","id":"exchange-031"},{"speaker":"田中委員","kind":"意見","question":"４月２１日の区民委員会の中で、情報漏れに関する戸籍住民課から出された謝罪文書の扱いについて質疑をしました。その後、謝罪文書はどのような手続を踏んで管理されることになったのか、手続について詳細をご説明ください。","respondent":"提坂戸籍住民課長","answer":"今回の事案を踏まえまして、今後も個人情報の保護に細心の注意を払わせていただくとともに、仕事を進めていく上で文書の保管を適切に行うことと、職員相互の情報共有や円滑な引き継ぎについて努めてまいりたいと思いますので、よろしくお願いいたします。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/681247?Template=document&Id=2786#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":38355,"voices":86}},{"id":"h29-20170711-7","meetingId":"h29-cm07","date":"2017年7月11日","dateIso":"2017-07-11","committee":"厚生委員会","time":"午前１０時００分～午後 ０時００分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","topics":[{"id":"topic-01","title":"平成２８年度品川区介護保険制度の運営状況","agenda":"平成２８年度品川区介護保険制度の運営状況","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２ページです。この理由が何なのかということを教えていただきたいと思います。それから、認定が１件あたり幾らぐらいかかるのかということも、改めて教えていただけたらと思います。ケアプランの作成費というのは、総合事業対象の方と認定を受けた方の予防プランということでは、１件あたりのケアプランの作成費が違うのかどうか。そのことも教えていただけたらと思います。","respondent":"寺嶋高齢者福祉課長","answer":"今年度、上がったところにつきましては、実はまだ１年分しかデータがないので、今まさに分析はしているところではありますが、下がった部分に対して、人口増はそのまま続いているので、その比率で上がっているのではないかという考え方が１つ。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それと、１０ページの一番上の(2)徴収方法別対象者数の徴収率のところで、これについても毎回聞いているところなのですけれども、去年伺ったときも、滞納繰越分の徴収率があるので、７９.４％になっているということでご説明いただいていたのですが、実際は、滞納者数というのは、平成２８年度からずっとどれぐらいの人数がいるのかということ。その点についてもお聞かせいただきたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"実際、どういう対応をしているかということなのですけれども、制度上に書かれていることとしては、まず、２年で時効が成立するので、その後、「お金ができたから払いたい」と言っても、制度上お支払いいただけないのです。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"品川区としては、差し押さえや滞納処分は一切していないということですし、ペナルティーも課していないということで、ニュースを見ると、３割ぐらいの自治体がそういうペナルティーを課していると書かれておりましたので、ぜひそれは続けていただきたいと思います。その分、区民の負担増ということになると思うのですけれども、その総額がわかったら教えていただきたいのが１点です。","respondent":"寺嶋高齢者福祉課長","answer":"それ以外に、包括的支援事業と呼ばれるものと、任意事業と呼ばれるもの。この３つの組み合わさって地域支援事業となっておりますので、イコールではありません。総合事業は地域支援事業の中に含まれているという構築になっております。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、１２ページ、１３ページで総合事業の実施状況というのがあって、それ以外のところで、包括的支援事業と任意事業というのは、この資料の中でどこを見ればわかるのか教えていただきたいです。地域支援事業の中での総合事業の割合は幾らぐらいなのか、そういうものはわかるのでしょうか。それが、どういうことで増えたのかということもお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"地域支援事業の全体にかかる割合という意味でよろしいでしょうか。１１ページの歳出の円グラフに書いてあります地域支援事業の比率が全体の６.２％。これが地域支援事業の割合です。大変失礼しました。地域支援事業の中の総合事業の割合ですね。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"地域支援事業の中の総合事業が７割ということで、１２ページ、１３ページに載っているのが全て総合事業ということで考えていいわけですね。では、その３割の包括的支援事業と任意事業というのは、どんなものなのかを少し教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"包括的支援事業ですけれども、サービスといいますか、内部での体制づくりのようなものになりますけれども、在宅医療と介護の連携通信の事業にあてる経費といったものや認知症関係の対策、成年後見制度の利用支援が、この中で取り組むものです。","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この運営状況の中には、地域支援事業の３割にあたる包括的支援事業と任意事業の中身というのは、報告には入っていないということですか。１５ページ、９．品川区介護保険制度推進委員会の開催状況というものがあります。","respondent":"寺嶋高齢者福祉課長、永尾福祉部長","answer":"詳細について、何か個別の内容に関する意見ということではなくて、全体の取り組み方針として、第七期に向けてどういったことが課題になるか、どの点が重点項目になるか。この第４回を行った後も、国のほうでどんどん詳細が決まってきている状況になっておりますので、第七期の策定に向けては、その辺も注視しながら検討していきたいと考えております。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"第七期に向けてという点でも、インターネット等を見ると、本当にいろいろ国から基本方針などが出てくると思うのです。そういうものも含めて、またこの介護保険制度推進委員会の中で出されることなどもあわせて、大きくこういうところで検討するということがありましたら、ぜひ厚生委員会の中でもご報告いただきたいということで要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"１点だけ伺いたいと思います。３ページの(2)サービス給付実績と利用件数というところです。こうしたサービス内容、また環境について、区は特定施設のところをどのように捉えているのか。それから、やはり特養ホームが望まれていると思うのですけれども、今後の特養ホームの増設計画の見通しを伺いたいと思います。","respondent":"寺嶋高齢者福祉課長","answer":"そういう意味では、サービスについては、当然しっかりしたサービスが提供されるように、我々保険者としてもきちんと対応していくということは言うまでもないのですけれども、このサービスを見てご利用されている方もたくさんいらっしゃると聞いております。","id":"exchange-008"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"特養ホームと特定施設だけの比較選択肢でみるものではないという説明だったのですが、そうは言っても、困難な状況にあっても、お金があれば入れるのが特定施設で、特養ホームは要介護３以上にならないと申し込みすらできないという状況では、やはり格差があるのではないかなと私は思います。それで、先ほども伺ったのですけれども、今後の特養ホームの増設等々、第七期に向けてはどのようにお考えでしょうか。","respondent":"大串福祉計画課長","answer":"今のところの予定では、平成３１年開設予定ということで、聞いているところです。","id":"exchange-009"},{"speaker":"石田（ち）副委員長","kind":"質問・要望","question":"特定施設は、軽度者の方も入れるというところで、やはり特養ホームも要介護３からではなく、もう少し早い段階から入りたい人も多いと思うのです。それで、今も待機者がいる状況で、行き場のない高齢者も増えてきますので、ぜひ特養ホームの増設を国有地、都有地、区有地を使って積極的に進めていただきたいと私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"}]},{"id":"topic-02","title":"介護保険事業計画改定に伴う高齢者アンケート調査","agenda":"介護保険事業計画改定に伴う高齢者アンケート調査","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問","question":"対象者なのですけれども、要介護１から５の介護認定を受けていない６５歳以上の在宅の方は７,０００人ではなく７万人ではないのでしょうか。そして、そのうちの５％ということで、３,５００件なのかなと思ったのですけれども。","respondent":"寺嶋高齢者福祉課長","answer":"すみません。大変失礼しました。日本語が少しわかりづらいのですが、６５歳以上の在宅の方から７,０００人を選んでということなので、７万人のうち７,０００人を選んで、それで、回収はその半分の３,５００人で、全体の５％にあたるという趣旨です。大変失礼いたしました。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"７万人の中の１割の７,０００人を選んで、そこから５割ぐらいの回収が予定されるのではないかということで、３,５００人ぐらいの回答があるのではないかということなのですね。それから、要介護１から５の介護認定を受けていないというのは、この見える化システムの国の統計から、こういう方を対象にということで考えられているのかをお聞かせいただきたい。そのあたりを教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"今のサービスについてどうお考えになっているかといった満足度等、ニーズの内容が我々として一番メインで欲しいところで、在宅介護支援センターからの聞き取り状況なども全部集約できておりますので、そういったものとあわせて把握をしていくといったところです。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、モニタリングアンケートというのは、要支援・要介護でサービスを実際に受けている方の状況をつかむということで、３年に１回ぐらい回るということは、３割ぐらいの方を対象にやるということなのですか。そして、アンケートのまとめというのは、介護保険制度推進委員会の中で報告されているということであれば、それをいただきたいと言えばいただくことができるということでいいのでしょうか。","respondent":"寺嶋高齢者福祉課長、永尾福祉部長","answer":"これは、今までの品川区のモニタリング調査の中には入っていなかった部分で、ここは新規追加となるのですけれども、３年間で１回転するというモニタリング調査とは全く別に、この見える化システムに載せるために。それで、モニタリングアンケートの調査結果については、要約した部分になるのですけれども、３８ページと３９ページに載っているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"そういうところで、今回は見える化システムのためにアンケート調査をやるというところなのですけれども、これから、第七期介護保険事業計画が、そういうことも含めて立てられていくと思うのですけれども、厚生委員会に対して、どういう場面でどういうふうなご報告をいただけるのか。その辺の第七期介護保険事業計画のスケジュールをお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"それ以外につきましては、国から決定的なものが示されたり、区の方針など、一定程度固まった段階のものがありましたら、それはタイミングを逃さずご報告させていただきたいと考えております。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"毎回私、要望させていただいているのですけれども、パブリックコメントだけでなく、説明会を開いていただいて、３年ごとの計画というところで、区としてもこうやっていきたい、それから、地域の方の要望も聞くといういい機会として、ぜひ説明会もやっていただきたいと思うのですけれども、その点もあわせてお聞かせください。","respondent":"寺嶋高齢者福祉課長","answer":"説明会につきましては、情報発信・提供はしっかりやっていきたいと考えていますけれども、今の段階で説明会というところは、特段の予定はありません。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ厚生委員会にも出せる部分、情報はご報告いただきたいということ。それから、説明会については、改めて、ぜひやっていただきたいということで要望させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"確認","question":"中身の問題ではなくて、用紙の問題で確認があるのですが、アンケートをとるときに、この調査票の用紙で出るのですか。急にこれが届いたときに、受け取る人は、この用紙ではわからないのではないかと思いました。アンケートを何の目的に使うかなど、記載内容は変わるのかどうか教えてください。","respondent":"寺嶋高齢者福祉課長","answer":"今回郵送を考えているのですけれども、非該当の要支援の方は、ケアマネジャーと接することになりますので、個別の口頭での説明も含めて、わかりやすくご案内させていただいて、アンケートの協力を依頼したいと考えています。","id":"exchange-017"},{"speaker":"石田（ち）副委員長","kind":"意見","question":"見える化というのは、誰にとっての見える化なのかをお知らせください。","respondent":"寺嶋高齢者福祉課長","answer":"保険者は全ての情報が見られると理解しております。それから、国からの情報ですけれども、全てではないのですが、地域の状況や現状の把握というカテゴリーにつきましては一般公開を予定していると聞いております。","id":"exchange-018"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"そうすると、一般に公開されて、それをいろいろな方が見たときに、意見を言える場所になっているということなのでしょうか。","respondent":"寺嶋高齢者福祉課長","answer":"ただ、これによって見えることになれば、それに対する意見をお持ちの方が、各保険者に対し問い合わせや指摘があるということは想定しておりますので、そちらについては十分やっていきたいと考えております。","id":"exchange-019"}]},{"id":"topic-03","title":"グループホーム金子山の開設","agenda":"グループホーム金子山の開設","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"意見","question":"入居者の決定というのは、それだけたくさんの方が応募されたときに、公平公正な選定をどう考えられているのかということ。それから、９月中旬に入居者選考委員会がつくられるということなのですが、このメンバーはどういう方なのか。福栄会の中に、この選考委員会がつくられるのか。品川区がどうかかわるのかについてもお聞かせください。","respondent":"中山障害者福祉課長","answer":"ただ、あまり重たい方ばかりがこちらに入られても、当初スタートからの地域との関係もありますので、重度の方もいらっしゃれば、比較的就労されているような軽度の方も含めて、幅広い層で対応していきたいと考えております。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"改めて、前のときに総事業費と補助金の関係でお聞きしたときに、総事業費はざっくり１億２,０００万円で、東京都からの補助金が５,０００万円で、区からは３５０～３６０万円ということだったのですけれどもこれは、改めて、建設が進んだ段階でも、ほぼ同じなのかというのと、区の３５０～３６０万円というのは、そういう基準というか、補助金要綱みたいなものがあって。","respondent":"中山障害者福祉課長","answer":"東京都の施設整備、グループホームを建設あるいは改修するときの基準額がありまして、東京都は、その基準額の８分の７を支出することになっています。区のほうは、８分の１を補助することで、できるだけ皆様にグループホームを設置していただきたいと考えているところです。","id":"exchange-021"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"１億２,０００万円のうちの５,０００万円というのは、８分の７にはならないと思うのですが。それは、対象になるものが全てというわけではないということだと思うのですがその点と、実際に１億２,０００万円のところで、５,３５０～５,３６０万円となると、残りの６,０００数百万円が負担になってくると思うのです。その辺の計算ができていたら教えてください。","respondent":"中山障害者福祉課長","answer":"ただ、東京都も補助金を入れているので、家賃についてはあまり自由に設定はできないことになっております。まだ決定はしていないのですが、おおむね２万円から３万円の間で設定することになると考えているところです。","id":"exchange-022"},{"speaker":"石田（ち）副委員長","kind":"質問","question":"私も前回の議事録を読ませていただいたのですが、やはり家族の方からは、グループホームに入る前の体験的なところを増やしてほしいというのは、ずっと出ているとおりなのです。体験のようなことをしてから本入所というのは、どこで、どのように、どれぐらいの体験できる場所があるのかを伺っていいですか。","respondent":"中山障害者福祉課長","answer":"この１０床についての体験については、そうしたことも含めて、福栄会と打ち合わせをしていきたいと考えております。","id":"exchange-023"}]},{"id":"topic-04","title":"品川区障害児福祉計画策定のための実態・意向調査の実施","agenda":"品川区障害児福祉計画策定のための実態・意向調査の実施","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害児福祉計画。これは、初めて立てるということになると思うのです。それから、委託業者というのは、「公募による調査業務委託事業者決定」というのが６月のところに書かれているのですが、その中で決定したのがバトン・プランニングというところなのでしょうか。公募でどれぐらいのところが来て、なぜここにしたのかということもお聞かせいただきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"３点いただきました。アンケートの対象者と、ヒアリングの対象事業者と、公募での業者選定のところです。その３点ということです。アンケート調査としましては、郵送を予定しまして、調査対象は、今回は障害児ということなので、１８歳以下のお子さんを対象にしております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"事業者のヒアリングですけれども、児童学園や戸越ということだけではなく、民間の放課後等デイサービスや、子どもたちにかかわる事業者も、区が実際にそういうところをつかむというところからしても、ぜひ私はヒアリングをすべきなのではないかなと思うので、その点をお聞かせください。あったらどこなのかということも教えていただきたいと思います。","respondent":"飛田障害者施策推進担当課長","answer":"その後、１２月にパブリックコメントを予定していますが、自立支援協議会が終わったときに、アンケートの骨子案をこちらのほうで報告させていただければと考えています。","id":"exchange-025"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"自立支援協議会で策定委員会を兼ねるということになってくると思うのですが、策定委員会という形で、これだけ重大な計画を策定するわけですから、それはぜひ区民に公開した場で議論いただきたいと思うのです。自立支援協議会が策定委員会という形でこういう計画を立てる委員会であるにもかかわらず、なぜ公開されないのかということについてもお聞かせください。","respondent":"飛田障害者施策推進担当課長","answer":"そういうところで、幅広い観点からご意見をいただき、それを計画に反映させていただきたいと考えているところです。今後は、自立支援協議会の公開も考えていきたいと思います。","id":"exchange-026"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そのごとに、私たちのことを私たち抜きで決めないでというのがあると思うのです。そういう点からしても、団体だけではなくて、障害の方々、家族の方々の意見を十分に聞いていただきたい。ぜひ聞く場面もつくっていただきたいと思いますし、自立支援協議会が策定委員会になるということであれば、これを公開していただきたいということを強く求めたいと思います。区民の公募委員の人数だけ教えてください。","respondent":"飛田障害者施策推進担当課長","answer":"区民委員というところです。今回、２名の方にお願いしております。１名の方は、発達障害をお持ちの保護者の方です。もう一名が、全国社会福祉協議会に長くかかわっていた方で、大学でも教鞭をとられた方がいらっしゃいましたので、その方２名にお願いしております。","id":"exchange-027"},{"speaker":"浅野委員","kind":"質問・要望","question":"第四期もあったわけですけれども、こちらは平成２９年度までということで、この目標の達成状況と言うのでしょうか。それが達成できるのかどうかということを１つお伺いしたい。やはり目標が設定されておりまして、障害者福祉計画と第一期の障害児福祉計画に出てくるのです。この辺の目標の設定についての考え方が厚生労働省から明確に出ているのかどうかも含めて教えていただければと思います。","respondent":"飛田障害者施策推進担当課長","answer":"例えば、移動支援の利用者が増加しましたけれども、利用時間が計画より少なかったこと、また、今後の障害者の高齢化を考えると、訪問系のサービスが必要とされるのかなというところを、今後のところで検討していきたいと考えております。","id":"exchange-028"},{"speaker":"浅野委員","kind":"質問・要望","question":"今後も進めていく中で、目標達成をするために、障害を持たれている方や対象の方が苦労されるようなことがやはり懸念されますので、それがないように進めていただいていると思いますけれども、確認のため、しっかりと障害を持たれている方を守りつつ、この目標を達成していくという観点で計画を進めていっていただきたいと思いますので、その点、よろしくお願いします。もう一言お願いできればと思います。","respondent":"飛田障害者施策推進担当課長","answer":"そういうところで、今後、障害児者総合施設が建てられます。その後、戸越ルームのあり方も、今後検討していかないといけないのかなと思います。ですので、そういうところもいろいろ見回しまして、今回、計画を策定できればなと考えております。","id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/549442?Template=document&Id=3482#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":36134,"voices":96}},{"id":"h29-20170711-8","meetingId":"h29-cm07","date":"2017年7月11日","dateIso":"2017-07-11","committee":"建設委員会","time":"午前１０時００分～午前１１時５３分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を44件抜き出しています。","topics":[{"id":"topic-01","title":"旗の台駅周辺地区バリアフリー計画の策定","agenda":"旗の台駅周辺地区バリアフリー計画の策定","exchanges":[{"speaker":"横山委員","kind":"質問・要望","question":"２０ページのところで１点だけお伺いさせていただきたいのですけれども、こちらの計画の基本目標のところで、「徒歩や車いす、ベビーカー利用者をはじめとするすべての人にやさしい、安全で、だれもが安心して快適にゆったりと回遊できるまちなかを実現することを基本目標とします」とあるのですけれども、こちらのまち歩き点検調査の当事者参加ということで。","respondent":"中村都市計画課長","answer":"場合によっては、非常に重要なところがあれば、そういったところもベビーカーの利用者の方の意見を踏まえた対応といったことも考えております。","id":"exchange-001"},{"speaker":"横山委員","kind":"質問","question":"ベビーカー利用者の方、双子のベビーカーですとか、いろいろな形状もありますし、まちの車椅子ですとか、それぞれの利用者の方のご意見等、伺っておりますので、ぜひそれも反映していただきながら進めていただけたらと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"新妻委員","kind":"確認","question":"ご説明ありがとうございました。パブリックコメントにもあったのですけれども、今回、旗の台が対象だけれども、ほかにもまたやってもらいたいという声が上がっていました。平成２６年度に大井町駅周辺のバリアフリー計画が出されて、本年度この旗の台ということで、考え方として、３年目安ぐらいでそういう地域ごとのバリアフリー計画が立つのかなというところを、まず先に確認させてください。","respondent":"中村都市計画課長","answer":"こちらは策定のペースが決まっているということではなくて、計画を立てて様子を見ながら次の計画を立てていくというところでございまして、区内全域に取り組んでいきたいとは考えておりますけれども、大井町駅で策定をいたしまして、そして駅のホーム柵を設置することになったり。","id":"exchange-003"},{"speaker":"新妻委員","kind":"質問・要望","question":"車椅子の方などは特に、小さいところには入れなくて、大きいところしか使えないけれども、普通の人がそこに入っているという中で、そこら辺をもう少し意識啓発といいますか、そういうところも取り組んでいただきたいというところと、また教育の中で障害のある人を大切にしていこうという心を育てていくというところとか、そこも区で対処してもらいたいなという声をいただいておりますので。","respondent":"中村都市計画課長","answer":"そういったものもしっかりと整備が進められるように、区でもまちづくりの部署や、あるいは建築行政の部署と連携して、バリアフリー化がしっかり行われるように、引き続き取り組んでまいります。","id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"心身障害者福祉会館の階段の始まり部分に、注意喚起用の点字ブロックをぜひ設置してほしいという意見もあったりするのですけれども、まだまだ酌み取り切れていない声というのがこれから出てくると思うのです。そういう場合というのは、積極的に計画に入れていくのか、あるいは計画に入っていなくても、改善していくべきだと思うのですけれども、そういうことではいかがでしょうか。","respondent":"中村都市計画課長","answer":"前の大井町駅バリアフリー計画の策定の中身との違いですけれども。","id":"exchange-005"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、ＰＤＣＡサイクルの話があって、見直しの部分、チェックの部分で、３９ページでは、「品川区やさしいまちづくり推進協議会を活用」とあるのですけれども、そうしたチェックというときとかにも当事者の方の意見が当然必要だと思うのですが、その構成なのですが、どれだけ障害者の方が入っていらっしゃるのかお伺いします。","respondent":"中村都市計画課長","answer":"まち歩き点検は、こちらの参加者の資料が手元にないので、後ほど答えさせていただきたいと思います。次の質問につきましては、策定の協議会の構成メンバーということでしょうか。","id":"exchange-006"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、文面が変わったのかというのはどうなのでしょうか。パブコメを経て、何か変わったところがあったのかどうかというのを、もう少しわかるように教えてください。","respondent":"中村都市計画課長","answer":"パブリックコメントにおける変更点があるかですけれども、パブリックコメントの中では主に、既に記載をされたようなことだとか、あるいは、今後考え方として進めていくということがありますので、特に、この意見を踏まえながら計画は進めておりますけれども。","id":"exchange-007"},{"speaker":"安藤委員","kind":"質問・要望","question":"わかりました。そういった意味で、パブコメの件数が非常に少ないです。ですから、全体的に、非常に当事者参加の意識がまだまだ品川区は弱いのではないかなと思うのです。ですから私は、団体の代表の方もよくわかっているとは思いますけれども、そうした方だけの参加にとどめず、パブコメ時には説明会などを開くなどして、区民参加をもっと重視していただきたいと思うのですけれども、いかがでしょうか。","respondent":"中村都市計画課長","answer":"そういった中で、これから長期にわたりまして、さまざまなご意見をいただきながら進めていくというところでは、最初の周知のところで説明会を開いたとしても、どこまでが十分な周知なのかというと、これは非常に難しいところがあります。","id":"exchange-008"},{"speaker":"筒井委員","kind":"確認","question":"パブリックコメントについてですけれども、確認になってしまうかもしれないのですが、１カ月の実施期間でおやりになられたのですけれども、品川区としては、パブリックコメントの実施期間というのは、何日やるという規定というか、決まりがあるのでしょうか。","respondent":"藤田都市環境部長","answer":"パブコメの期日の関係ですけれども、最長で１カ月という形になってございまして、その期間をたっぷりとった形で、今回も実施しているものです。","id":"exchange-009"},{"speaker":"筒井委員","kind":"質問","question":"品川区としては、それは根拠規定というのがあるような形でしょうか。","respondent":"中村都市計画課長","answer":"パブリックコメントにつきましては、広く区民の意見を聞くためのものとして、庁内での基準が定められてあります。","id":"exchange-010"},{"speaker":"筒井委員","kind":"質問","question":"急激に日数を増やしたからといって意見が増えるとは思えないのですけれども、まだ少しは増える可能性があるということで、パブリックコメントの実施期間をもうちょっと長くするとか、そうしたことをやっていいのかなと思うのですけれども、区のご見解としてはいかがなのでしょうか。","respondent":"たけうち委員長","answer":"建設委員会というよりも、別のところでやる話だから、ここで聞いても多分、お答えできないと思います。他の場でやっていただいたほうがよろしいかと。","id":"exchange-011"},{"speaker":"筒井委員","kind":"質問・要望","question":"ということで、当委員会ではないかもしれないのですけれども、いろいろな期間を延ばすことや、さまざまな区民のお声をぜひ聞いていただいて、あと、この計画を策定してから、先ほど課長がおっしゃったように、常に区民のお声を収集していって、よりよい計画にしていっていただけたらと思います。これは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"大沢委員","kind":"意見","question":"旗の台駅のバリアフリー計画の策定ということで、計画の概要ということで、「２０２０年オリンピック・パラリンピック開催を契機に国際都市として発展をする」ということが書いてありますけれども、国際都市ということで、都市計画課では、ここの部分が国際都市となる、それを見据えるということですけれども、では具体的に、どのように担当の課では国際都市の絵をこの場所に描いているのか、お教えください。","respondent":"中村都市計画課長","answer":"この旗の台におきましては、主に生活に密着した商店街ですとか、あるいは住居が中心ですので、こういったところにおきましては、外国人の方が区内において、あるいは日本国内において就労される方がお住まいになったりですとか、あるいは買い物に来られたりですとか。","id":"exchange-013"},{"speaker":"大沢委員","kind":"質問・要望","question":"資料によりますと、ここの旗の台地区というのは、いつなのかわからないのですけれども、品川区の外国人が住むパーセンテージに比べると、旗の台地区に外国の方が住んでいるパーセンテージが低いということで数字が出ておりますけれども、今後そういう意味では、バリアフリー化を含めて、そのパーセンテージを増やす、外国の方が定住できる。","respondent":"中村都市計画課長","answer":"その中でも、このバリアフリーの取り組みの中では、外国人の方も含めて、本国、日本の方も、全ての人に優しいまちですので、そんな中で外国人の方が増えてくれればいいかなと考えております。","id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"いろいろハード的な整備がかなり盛り込まれているようなのですが、それはどういう関係になっていくのかというのと、１６ページぐらいでしょうか、生活関連施設という地図が載ってありますけれども、この中においても、既に改築をされているところも当然あるし、まだされていないところもあるし、結局この中のバリアフリー計画の中に、それらを組み込んだ形で改築を考えられていこうとしているのか。","respondent":"中村都市計画課長","answer":"この計画と、改築だとか建替えとの関連ですけれども、バリアフリー計画をやるために施設を改築するとか、そういったバリアフリーと改築は、直接はこの計画には強制力はありませんので、直接的な関連はございませんけれども、大規模改修や改築などの機会を捉えて。","id":"exchange-015"},{"speaker":"西本委員","kind":"質問","question":"進み具合というのは、どれだけお金がかけられるかというところにあると思うのです。品川区の財源から全て出していく状況になるのか。一応、短期・中期・長期という形でされているわけですから、具体的な形で進めていかなければいけないという立場もあり、ただお金もない、理解もなかなか難しいという状況だと、この計画は何なのですかという話になってしまうので、その辺の展望はいかがなのでしょうか。","respondent":"中村都市計画課長","answer":"そういった意味からしまして、この策定にあたりましては、交通事業者も一緒に参加して計画の策定をして、そしてしっかりと意識を持ってやっていただくような形で、策定というものを通して事業者に認識をしてもらうというところもやっているところです。","id":"exchange-016"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろと計画する中で、国、都もあるのかもしれませんけれども、そこからの補助金等々があるような感じがしましたので、そこはしっかりと、速やかにとっていただきたいなと。それと、協力がないと進められないことですので、ぜひ、これから計画の中で、どれだけ事業者にも協力を得られるかなということで、最大限頑張っていただきたいなと思っていますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"いながわ副委員長","kind":"質問","question":"最後に１点、僕が区議会議員になってちょうど１０年たつのですけれども、当初、よくある話が、歩道と車道の際目というのでしょうか、歩道を歩いてくると１cmぐらいの段差があって、それがないと、視覚障害者の方がステッキがひっかからないので、歩道と車道の区別がなかなか難しいという話があって、それをつくれば、今度は車椅子が上りづらいという話を僕はよくした覚えがあるのですけれども。","respondent":"中村都市計画課長、多並道路課長","answer":"段差の考え方ですけれども、こちらは委員のご指摘のように、さまざまな対応が、ある人にとっては使いにくかったり、ある人にとっては使いやすかったりというご指摘のとおりですが、段差につきましては担当課からお答えします。ただ、今の委員のお話にございましたような、車椅子の方にも配慮する整備ということで考えますと、工事の中で、例えば全体的には２cm段差ですが、ある一部分、車椅子が通る部分だけをゼロ段差にするとか。","id":"exchange-018"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"事業所に改善を求めることも含めているという話なのですが、例えば１８ページの昭和大学病院で、詳しいことはわからないのですけれども、オストメイト対応トイレの設置というのは、通常、病院だったら必ず、設置する・しないの議論の前に、しっかりそういう患者さんを、そういう科がなければあれなのかもしれないけれども、こういうのも早急に改善できるような感じもするので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問","question":"エスコートゾーンの話で１点だけお伺いしたいのですけれども、結構、障害者団体の方から、区内あちこちで、音響信号はあるけれどもエスコートゾーンがないですとか、そこにエスコートゾーンが必要なのにないということで伺っているのですけれども、先ほどの中で聞きましたが、計画をつくらないと都がつくらないみたいな話があったのですけれども、なかなか進まないところというのは。","respondent":"中村都市計画課長","answer":"エスコートゾーンにつきましては、限られた予算の中で設置をしているということで、計画を立てることによって、優先順位として上げていただける効果があるのかなと考えています。","id":"exchange-020"}]},{"id":"topic-02","title":"平成２９年８月都営住宅入居者募集","agenda":"平成２９年８月都営住宅入居者募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"改めてお伺いしたいので、お聞きします。３つ目は、募集周知なのですけれども、都営住宅ですから東京都から周知が来たなという、東京都が周知しているなという印象があまりないのですけれども、区が主にやっているのかなと思うのですが、区が行っている募集の周知は、どのような形で行っているのか、実際にこういうこと、これこれだよというのを全部挙げてほしいのですけれども。","respondent":"長尾住宅課長","answer":"区で行っている業務に関してですが、こちらの募集に関して、都から募集の案内が送られてまいりますので、こちらを配付資料にあります配布場所に置きまして、皆様に配布していくところです。その際に、書き方であるとか、内容に関してのご質問にもお答えしているところです。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問","question":"わかりましたけれども、周知のところですが、広報とホームページしか品川区はやっていないのですか。チラシとか掲示板とかではやっていないのでしょうか。","respondent":"長尾住宅課長","answer":"募集に関しての周知という意味で言いますと、先ほど申し上げました広報とホームページになりますが、募集期間外になりますと、どういった住宅があるかというチラシを窓口で配布したりといったことは、日常的に行っております。","id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"多くの方に、こういった募集を行っているということの周知は、もう少し強めていただきたいなと常に思っているのですが、広報とかホームページに限らず、スペースも関係あるのであれですけれども、統合チラシですとか、何月のしながわとか、ああいうポスターですとか、そういったところでも、ぜひ充実をしていっていただきたいなと思います。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"}]},{"id":"topic-03","title":"事業系生ごみ処理機の購入助成","agenda":"事業系生ごみ処理機の購入助成","exchanges":[{"speaker":"新妻委員","kind":"質問・要望","question":"なかなかお金のかかることですので、難しいとは思うのですけれども、大体見込みがどうなのかというところと、今後、もし非常に反応がよくて、多くの募集があった場合には、予算をもう少しつけて拡大をしていくなりのお考えがあるのかどうかというところと、これはあくまでも個人での事業者に１個で、例えば商店街で１個を購入してというようなこともあり得るのか、確認をさせていただきたいと思います。","respondent":"工藤品川区清掃事務所長","answer":"機器がかなり高価だというところから、よほど環境意識が進んでいる方でないと、採算という部分でもなかなか難しいなと思ってありますが、今回５件の部分につきましては、私どもも鋭意努力してＰＲしながら、何とか購入をしていただくような形で進めてまいりたいと思ってあります。","id":"exchange-024"},{"speaker":"新妻委員","kind":"質問","question":"それは単体でというふうに、ごみの移動ができないという話でしたけれども、例えば区内にあるチェーン店が１つ入れて、チェーン店の中でまとめるということもできないということなのですか。","respondent":"工藤品川区清掃事務所長","answer":"そこのチェーン店、区内にある店舗の中で出てきているもののみの処理という形になりますので、幾ら区内といえども場所が離れているところの部分を集めるという形になりますと、当然、収集事業者が集めるという形になりますので、そういった意味では、難しいと考えています。","id":"exchange-025"},{"speaker":"新妻委員","kind":"質問・要望","question":"でも、まずこの５件が活用されるように、ぜひ周知も徹底をしていただきながら進めていただきたいと思います。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"機械が高価だというお話がありましたけれども、処理量が１０kg以上の機器と、処理量が１０kg未満の機器と、それぞれ大体平均どのくらいのお値段になるのでしょうか。もしご存じでしたら教えてください。","respondent":"工藤品川区清掃事務所長","answer":"１０kg未満の機器であれば１５万円の助成ですので、大体５０万円前後で販売されているです。５０万円と１２０万円を超えるです。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"これは事前にニーズ調査というのはされていますか。こういう事業所の中でごみ処理をするということの、いろいろ法律が変わってきているわけですから、当然認識はあるのではないかなと思うのですが、この辺の事業者の中で、こういうのがあったらいいなというリサーチをかけた経緯はありますでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"例えば、大量に食品廃棄物が出ます弁当屋とかそういったところから、購入はしていただけるかどうかわかりませんけれども、そういったご相談があることはあります。現状としては、そのようなお話を聞いているところです。","id":"exchange-028"},{"speaker":"西本委員","kind":"質問","question":"事業系の生ごみがどのぐらいあるかは把握されているはずですよね。これぐらいの事業系のごみが出てくる、それを処理するためには、これが普及していくのと、それによって大体どのぐらいの件数をやると目的を達成できるというのが、計算で出てくるのではないかなと思うのですけれども、その辺の見立てはどうなっていますでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"ただし、これを使ってゼロにしようというわけではなくて、私どものこの補助金というのは、ある部分で環境意識を高めるとか、そういった部分の狙いがございまして、そういった意味では、５台購入していただいて、例えば４台が１０kg。","id":"exchange-029"},{"speaker":"西本委員","kind":"質問","question":"今回の反応を見てとか、とりあえず５件とかいうふうになってしまうと、啓発するためには、どういうふうに啓発をしていって、補助金がなくても自分のところで生ごみをきちんと処理するのですよというところの義務化をするみたいなところまでの意識づけを、どうやってやっていくのですかというところまで、私は進めてもいいのではないかと思うのですが、その辺はいかがでしょうか。","respondent":"工藤品川区清掃事務所長","answer":"そこの部分で今回、ある部分で機器購入のイニシャルコストとランニングコストというのはかかってくるのですけれども、どれぐらいの部分で削減できたかという部分をうまくＰＲすることによって、興味を持たれる方、購入を考える方がまた出てくるかと思いますので。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"処理された後というのは、堆肥とかいろいろできるのですよね。土になったり、いろいろされると思うのですが、循環という意味では、今回の機種とかというのは、そういう規定はあるのですか。最終的な処理されたものをどうするかというところまで考えられていますか。","respondent":"工藤品川区清掃事務所長","answer":"機器をもって、どうリサイクルするのかというご質問かと思います。考え方として２つございまして、機器にかけまして減容化をして、堆肥化するという方法が１つ。もう一つが、バイオ菌等をかきまぜながら消滅させる、水と一緒に流してしまうという部分です。","id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"堆肥化する場合は、循環するわけです。自分たちが後始末もきちんとやっていますよ、しかもそれは地球に優しくなっているのですよという、事業所の姿勢というのもＰＲできる１つの方法だと思いますので、それもあわせてＰＲを、ぜひ進めていただきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"大沢委員","kind":"質問","question":"生ごみや事業系のごみを減量ということなので、啓発活動だというお話をお聞きして、５件ということですよね、機械自体が。１０kg以上が４０万円を上限での補助、もう一方が１５万円まで。ごみを処理するお金も、確かに現にかかっているわけだけれども、飲食店を取り巻く環境を考えた場合に、飲食業界の方たちが、はい、そうですかと、この機械に１２０万円なり５０万円を投資するものか。","respondent":"工藤品川区清掃事務所長","answer":"そういった部分で、衛生面でもかなりメリットがあろうかと思ってありますので、そういったメリットの部分と、投資した部分をどれぐらいで回収できるのかという部分をしっかり説明して、購入につなげたいと思っているところです。","id":"exchange-033"},{"speaker":"大沢委員","kind":"質問","question":"申込ですから、あくまでも、こちらが説明をするという部分に関しては、こちらが主体。","respondent":"工藤品川区清掃事務所長","answer":"まさに委員からご指摘がありましたように、その辺が一番難しいところです。興味を示していただかなければ、私どももなかなか説明もできないですので、そういった意味ではＰＲというか、そういった活動が重要だと思ってあります。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問・要望","question":"当然メーカーのご協力も、そのステッカーとかも費用がかかることですから。ですから、ごみ処理機メーカーとかのご協力をいただいて、全体的にお店がこの機械を購入するインセンティブ、メリットというのを与えていく仕掛けというのが必要だと思いますので、ぜひやっていただきたいと思います。この点、区のお考えというか、どのように取り組まれようとしているのか、お答えいただければと思います。","respondent":"工藤品川区清掃事務所長","answer":"今環境課でも、ＳＨＩＮＡＧＡＷＡ“もったいない”プロジェクトという形で、いろいろとそういったＰＲ等もやってありますので、そういったところとの連携ができないのかどうかという部分も今後考えていきたいと考えています。","id":"exchange-035"}]},{"id":"topic-04","title":"品川区営自転車等駐車場の改修工事","agenda":"品川区営自転車等駐車場の改修工事","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"製造したからには、製造した人間というか会社の、法人の責任もあるわけであって、つくりました、ではこちらに全部、置く場所はしわ寄せでというので、結局、役所の費用がかかっているわけですから、そこらの何か手だてというか、会社なり、もっと大きな部分でのお話ができないのかというのが１つ。教えてください。","respondent":"桑波田交通安全担当課長","answer":"広報活動につきましては交通安全係で、いろいろな自転車に対する交通安全マナー、ルールといったものを、子どもに限らず一般の方にも周知していますので、そういったところは警察と、また連携をとりながら実施していきたいと考えております。","id":"exchange-036"},{"speaker":"安藤委員","kind":"確認","question":"それと、整備スケジュールのところにありますけれども、下の青と緑のところは改修ということなのですが、区内で多くの箇所に残っている狭いところを改修するというのは、赤のところで全部終わるということなのでしょうか。何カ所ぐらい、幅を広げる整備というのを考えていて、いつまでに完了するかという点では、この赤いところでよろしいのですかという確認です。","respondent":"桑波田交通安全担当課長","answer":"駐輪台数の関係ですけれども、先ほどご説明しましたが、使えなかったものが使えるようになりますので、総体的には６６０台ぐらい、さらに今まで使っていなかったものが使えるようになるです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"この整備というのは、定期利用ですか。それとも、一時も全部のことでしょうか。","respondent":"桑波田交通安全担当課長","answer":"整備につきましては、主に大規模にやるのは定期利用でありますけれども、当日利用についても、場所的に古いものとかありますので、当日利用のほうも一部、幅を広げたりして整備する箇所もあります。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問","question":"それに加えて、水神のほうは同じ台数を整備するということになると、かなり解消されるのかなという思いがあるのですけれども、大森のほうの周辺の自転車の状況がわかりましたら教えてほしいなと思います。西大井駅のほうは増設というと、次の定例会で条例改正になるのでしたら、大体どの辺に増設されるのでしょうか、教えてください。","respondent":"桑波田交通安全担当課長","answer":"地下駐輪場ですけれども、こちらは６月末なのですが、今、６０％ほど台数、利用者、契約者が増えてきましたので、今後また増加していくものと思われますけれども、今のところは順調に進んでおりますし、これによって放置のほうも大分解消できるのではないかと考えております。","id":"exchange-039"},{"speaker":"西本委員","kind":"質問","question":"西大井駅のロータリーという部分、具体的によくわからないところがあるのですけれども、景観上の問題もあるので、できれば、西大井駅は結構人通りが激しいので、その人通りにあまり影響ないところの場所であるとか、西大井広場のほうはいいと思うのですが、西大井広場は若干スペースがあると思うので、そこはいいのですけれども、西大井駅のところが何かちょっと不安なのですけれども、景観上を含めて。","respondent":"桑波田交通安全担当課長","answer":"西大井の関係は、地元も町会関係６町会、周辺全てお声がけしまして説明させていただいて、ご意見を聞きながら進めさせていただいているところですので、その辺はまだ計画もしておりますので、十分意見を聞きながら進めさせていただけると考えております。","id":"exchange-040"},{"speaker":"西本委員","kind":"質問・要望","question":"西大井駅は非常に交通が、朝とかが非常に人通りが激しいところなのです。これもいろいろあると思うのですが、これを含めて、町会というよりは、使っている人たちとか、特に広い意味で意見聴取をしていただきたいなと考えていますので、今後検討していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"こういうのは、どういうものをお考えなのか。要するに、アシスト自転車はスタンドを立てなければ、多分無理なのです。そうなると、両方アシストが入ると、この２台というのは固定になってしまうわけではないですか。そうすると、真ん中というのは、この４０cmというのだと、絶対入るという幅なのですか。そこをお聞かせいただきたいと思います。","respondent":"桑波田交通安全担当課長","answer":"現在の設置間隔は３０cmなのですけれども、これを１０cm、両脇を合わせますと２０cm広げることになりますので、こういったもので対応できるようになりますし、あと、タイヤのほうも、そういった大型車で、今まで４cm幅のタイヤしか入らないようなところも。","id":"exchange-042"},{"speaker":"いながわ副委員長","kind":"質問・要望","question":"僕もアシストに乗っているし、子どもを乗せることのがあるのですけれども、いろいろなところへ行って駐輪場にとめると、スタンドをしないとどっちかに傾いてくるわけです。しかも、もともとの入れるラックが固定されていないですから、そうすると、ふらふらしていて、結局、幅があったとしても、なかなかそういうのが入れづらくなるのではないかなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"安藤委員","kind":"意見","question":"全体としてはいいのですけれども、一つ一つ、特に糸魚川のところとかは、すごく研究しがいがあるというか、話題のところだと思うので、ちょっと盛り込まれ過ぎなのかなという印象が若干あるのです。自転車とかはかぶっているところもあるので、思い切って。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/169461?Template=document&Id=4206#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":36500,"voices":135}},{"id":"h29-20170711-9","meetingId":"h29-cm07","date":"2017年7月11日","dateIso":"2017-07-11","committee":"文教委員会","time":"午前１０時００分～午後 ０時０５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件抜き出しています。","topics":[{"id":"topic-01","title":"城南小学校・幼稚園改築工事にともなう遺跡発掘調査の見学会","agenda":"城南小学校・幼稚園改築工事にともなう遺跡発掘調査の見学会","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"それで、説明員なのですけれども、その場の状況によって説明を行うということでしたけれども、何人ぐらいいらっしゃるのか、聞きたいという方がきちんと聞けるようになっているのか、伺いたいと思います。そして、今後この発掘作業が終わった後、発掘したものはどうなっていくのか、どこかに保存されるのかということも含めて伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"説明のタイミングですけれども、決まった時間にやるのではなく、それぞれ午前、午後、２時間ずっと開いていますので、お集まりいただいた状況を見ながら、ある程度お客様がおいでいただいた段階で、随時説明をしていくということを考えているところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"保護法に基づいて、壊すものは壊す、残すものは残すということでしたので、できる限り、歴史の勉強にも役に立つようなものとか、残せるものは残していっていただきたいなと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-002"},{"speaker":"南委員","kind":"意見","question":"様々な建物を建てるに当たって、掘り返すと遺跡が出てきたという状況で発見されることが結構多いのですけれども、ここのところは明治時代の校舎ということもあるので、事前にある程度のことはわかっていたのかなと、ちょっと思ったりするのですけれども、そのあたりの、当初からわかっている場合と、そうではない場合とあると思うのですけれども。","respondent":"篠田学校計画担当課長","answer":"委員ご指摘のように、実際に掘り返したりしたときに出てきたという場合は、出てきた時点でその対応をきちんとしていくということで、基本的には埋蔵文化財保護法によりまして、開発者の責任においてきちんとした調査をして、出てきたからといって。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"特にここの学校のところについては、明治時代の建物を７２歳の方まで使っておられたというのも、非常に親近感を覚えるし、また、特に子ども、児童・生徒にとってみれば、自分の学校がそういう経過があるのだということで、誇りとか、地域に対する様々な思い入れというか、そういう気持ちが育つという非常に大事な状況かなと、伺っていて思ったのですけれども、先ほどの質疑にもあったように。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"渡部委員","kind":"質問・要望","question":"逆にまた、様々なものが出続けることによって、今予定している工期よりもどんどん遅れていくことも想定されるのかなというところで、その辺の見通しをあわせて教えていただきたいのと、例えば文化財保護法に基づいて様々やっていく中で、当然その経費というのがどんどんかさんでいくと思うのですけれども、その辺の財源はどういう形で動いていくのか教えてください。","respondent":"篠田学校計画担当課長","answer":"発掘調査の今後の予定ですけれども、先ほども申し上げたとおり、新校舎の全ての部分に関して発掘調査をかける必要がありますので、範囲がおよそ２,０００m2となります。","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"予定はわかりました。確かにこの辺の地域は前からお話を伺って、始める前から、何か出るぞという話を地域の方がされていて、会派の中でも話題になっていて、案の定出てきてというところで、これから見学会などをなさっていくのでしょうけれども、今も平成２９年１１月を目途にということで、ある程度期間を区切っている。","respondent":"篠田学校計画担当課長","answer":"ですので、今回どのぐらいお見えになるかはわからないですが、例えばご要望があって、この先もっとやってほしいというお話が出てくれば、場合によっては、まだ１１月まで時間がありますので、周知期間等を含めましても、まだ必要に応じては対応できるかなと考えているところです。","id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"今の渡部委員の関連になりますけれども、見学の日時です。この時間帯を、午前中はわかるのですが、午後が３時で終わってしまうという、この時間の選定の理由と、雨天中止なので、今のお話からいくと、１１月まで区民の皆さんに公開することによって、意識啓発と普及を図るという目的でするのであれば、他の日にちを設定するということがあってもいいのかなと思うのですが、その点はいかがでしょうか。","respondent":"篠田学校計画担当課長","answer":"なお次回以降につきまして、ご要望が非常に強ければ、開催できるような体制はとっていくつもりですので、必要に応じてそういったところも対応していきたいと考えているところです。","id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今回の区民の方々への見学会は大変すばらしい企画で、よろしいと思うのですが、１つお尋ねしたいのは、在校生がどのようにしてこの遺跡を、すでに見学をしたのかもしれませんけれども、計画を含めて教えていただきたい。せっかくの機会ですので、在校生が保護者とそれを見られるといいと思います。","respondent":"篠田学校計画担当課長","answer":"今、学校に在籍されている子どもたちに関しては、また別の機会に、随時授業の中でという形で見学をしていただくということで考えているところです。こちらは学校の中と、教育委員会との間で日程調整を様々しています。","id":"exchange-008"},{"speaker":"松永委員","kind":"質問","question":"説明ありがとうございました。見学方法について、１点お伺いしたいと思うのですけれども、これは品川区民だけではなく、様々な地域から来るかもしれないのですが、そういう方たちも受け入れ可能なのか。自由に出入りできるのか。発掘調査員と一緒に行かないと、遺跡は見ることができないのか、それとも自由に歩いて見学できるのか、その点について伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"今回の見学方法につきましては、この公開時間、午前中２時間・午後２時間、随時こちらは入り口を開けておいて、受け付けをしたのちに、中を自由に見ていただくという形を考えています。","id":"exchange-009"}]},{"id":"topic-02","title":"学事制度審議会第６回～第９回の報告","agenda":"学事制度審議会第６回～第９回の報告","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"昨年から始まって、私どももずっと要望をしていて、平成２０年のころから比べて状況が変わったので、何とかしなければというところが会派の中でもありまして、順調にここまで推移しているのだなということが確認できて、これからまだ積み残しているところもあると思うので、しっかりとお願いします。そこだけ確認させてください。","respondent":"篠田学校計画担当課長","answer":"こちらの中間答申に関しましては、速やかに委員の皆さまにご報告をしていきたいと考えているところです。","id":"exchange-010"},{"speaker":"渡部委員","kind":"質問・要望","question":"できれば第３回定例会のときにでも出していただければ、逆にここで何を議論というお話でもなくて、報告を受けてですので、そこで９月に、委員長にお願いですけれども、中間答申が出たら少し議論をできれば、そのときに機会を設けてもらえるといいのかなということで要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"のだて委員","kind":"提案","question":"選択制のところでは、先ほどご説明が少しあって、ちょっとわかった感じもしますけれども、小学校段階で隣接した学校を選択できるということが、まとめのところで書いてありますけれども、これは事務局の提案ではどういった案だったのか、もう少し詳しく説明できる部分があれば、ご説明いただきたいと思います。","respondent":"篠田学校計画担当課長","answer":"アンケートに関するクロス分析の結果ですけれども、実はこの分析に関しましては、全部で６０ページぐらいにわたる資料になっていますので、なかなかこれを一言でご説明するのは難しいのですけれども、例えば特徴的な部分で申し上げますと。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"以前の答弁では小学校・中学校の単独のところでも、同じカリキュラムだと区では言っていたと思うのですけれども、まさに独自カリキュラムを行えるとなると、義務教育学校がエリート校というのでしょうか、特別校になっていくことで、格差が義務教育のところで生まれてきてしまうという懸念があるのですけれども、区の考えを伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"なかなか具体的なお話はこの場ではしていないのですけれども、今考えているのは、先ほどもちょっと申し上げたのですけれども、学区域の見直しの中で、現状、小学校から複数の中学校に分かれてしまうような、うまくかみ合っていない状況がありますので。","id":"exchange-013"},{"speaker":"のだて委員","kind":"質問・要望","question":"カリキュラムのところでは、義務教育学校では別のカリキュラムでやっていくことはないということでいいということですね。それを改めて確認させていただきたいと思います。単独の小・中学校と同じカリキュラムでやっていくということでいいのか、確認させていただきたいと思います。","respondent":"熊谷指導課長、篠田学校計画担当課長","answer":"ただ、義務教育学校が９年間の義務教育ということで、より特色を出していった場合に、単体の小学校から７年生に転編入したときに、教育内容を含め、不安なくついていけるような制度や体制を保障していきたいと考えているところです。小中グループを出ていく場合の対応です。こちらは、仮に出ていったとしても、行った先できちんと教育的なフォローをするというのは当然の話でございまして、それはやらないということにはならないです。","id":"exchange-014"},{"speaker":"南委員","kind":"質問","question":"私も６回から９回の議事録を読ませていただきました。要点なので、なかなかしっかりつかめていない状況なのですけれども、その中で、ちょっと気になったところがあったので伺いたいと思うのですけれども、教育委員会としては、この議事録の中では、義務教育学校について６校に限らず、増やしていくということも考えているという表現が何カ所かあったので、その点について改めて伺いたいと思います。","respondent":"篠田学校計画担当課長","answer":"そういった点を踏まえまして、例えば地域の方々から強い要望をいただいているとか、あるいは具体的に今後の品川の教育を進めていく中で、必要性ですとか、そういったものを勘案した上で、どうしても今後まだ義務教育学校が必要であるといった結論に達するようなことがあれば。","id":"exchange-015"},{"speaker":"南委員","kind":"確認","question":"義務教育学校６校のほうですけれども、６校以上に増やしていく考え方はあるということ、そこは議事録でも何回か述べていらっしゃるので、そういう考え方を持っているのだということは確認していいのですか。そこを１つ確認をしたいと思います。さきほどのご答弁では、わからなかったので、申しわけないのですけれども、もう一度答弁をしていただければと思います。","respondent":"篠田学校計画担当課長、品川庶務課長","answer":"義務教育学校の今後の話ですけれども、これから先、増やしていこうということではないです。ただ、必要に応じて、増やすことも視野に入れた検討をしていくです。地域のかかわりについて、今、庶務課でスタンプカードという事業を進めているところで、１年生から６年生までやっているところですけれども、効果というところでは、確かに全体の町会の中で。","id":"exchange-016"},{"speaker":"南委員","kind":"質問・要望","question":"義務教育学校については、増やすという方向に、まだ立っているわけではないと。しかしさきほどの答弁では、私の誤解かもしれないけれども、単独小学校から義務教育学校に転編入する際に、平準化というのでしょうか、学力などにおいて、ついていけないことがないよう様々取組みを行うのだと。その辺を解消したいと思っているので、答弁をしていただきたいと思います。","respondent":"熊谷指導課長","answer":"ただ、どこの小学校、中学校、義務教育学校に行っても、それぞれ特色がありますし、また、施設が一体となっている義務教育学校においては、子どもたちが９年間の学びを継続して行っていくですので、そういった中で、７年生で編入するというときには。","id":"exchange-017"},{"speaker":"南委員","kind":"質問","question":"それぞれの学校の特色があるのは、あっていいと私も思います。歴史の違いや地域の違いなど当然あると思います。例えば、東海道の入り口のところにある学校は、その地域の雰囲気があるわけだし、一方で、八潮みたいに新しくできたまちは、東海道とは全く違う雰囲気です。なのでもう一回伺いたいと思っているのですけれども、その点について、もう一回お願いします。","respondent":"熊谷指導課長","answer":"繰り返しになりますが、品川区立学校教育要領に基づいてカリキュラムを、どこの学校も編成しておりますので、それぞれ学校のやり方ですとか、進め方等、若干の違いがあるのが特色だと考えております。","id":"exchange-018"},{"speaker":"南委員","kind":"質問・要望","question":"未解明なところを解明させていただきたいので、すみません、長くなってしまって悪いのですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"南委員","kind":"確認","question":"子ども一人一人、それぞれ様々な部分で違いがあります。なので、別に義務教育学校に行かずに、地域の中学校に行くにしても、違いがあるのは当然だと思うのです。けれども、そういうことで理解していいのかしらと、何か違いがあるような気がしてならなかったので、くどく聞いたのですけれども、では同じなのだなと理解していいのかどうかを確認したいなと思ったのが１つです。","respondent":"本城教育次長","answer":"教育の質を高めるためには、特色ある教育を進めていく中で達成できるという意味で、今まで義務教育学校あるいは小学校単独校など、もろもろありましたけれども、それらが特色ある学校をつくるということ、あるいは地域とともにある学校づくりを推進していく中で。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"全体としては、とりあえず受けとめておきたいと思います。それで、格差なんて絶対にあってはならないということを思います。それと、教育改革として様々取組まれる中で、地域との連携が希薄になるという状況はつくってほしくないし、そこのところは、この間の教育委員会としての真摯な検討が必要なのではないかなと私は思っておりますので、このことは要望と意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"渡部委員","kind":"確認","question":"今、確認したのは、今回学事制度をやっている中で、学校選択制というものに対してですとか、学区域というものが俎上に上がってきている中で、主役は子どもなわけです。そういうところというのも、せっかくの機会だったから、もう間に合わないかもしれないけれども、何か取り入れていって、意見として反映できてくれば、また様々な方策が変わってきたのかなとちょっと思ったりしていたので考え方はどうですか。","respondent":"篠田学校計画担当課長","answer":"子どもの意見という部分です。例えば、中学校の選択制のお話を先ほどさせていただいたのですけれども、どういうふうにするのか、なかなか難しい部分がありますので、今、検討しています。","id":"exchange-022"},{"speaker":"渡部委員","kind":"確認","question":"ありがとうございました。具体的な細かいところというのは、中間答申が出てこないとというところでありますので、この後どうこうというのはないのですけれども、子どもの意見を最大限取り入れられるようなものにしておかないと、大人の理屈で動いてしまうと、いいことがないなとちょっと思ったものですから、それだけ確認させていただきました。","respondent":"熊谷指導課長","answer":"最も重視したところは、「地元で通学上便利だから」を選んだ子どもが５０％近くいたです。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"さっき質問を忘れてしまったのですが、パブリックコメントを９月下旬から１０月という時期が示されているのですが、期間的には２週間から３０日でしたか、それぐらいの期間があるのですけれども、私は、保護者の皆さんもこういった問題についての関心が高いので、短期間ではなくて、できるだけ長く期間をとってパブリックコメントを実施していただきたいなと思っているのですけれども。","respondent":"篠田学校計画担当課長","answer":"パブリックコメントに関しましては、中間答申を審議会でいただいた後に実施するということまでは決めていますけれども、具体的にどういった形で、期間なども含めてまだ検討している段階です。ただ、きちんとご意見を聞けるような形で実施をするということは考えているところです。","id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"確認","question":"１つ確認したいのですけれども、９回目のところのまとめの一番下の行に、「中間答申の検討時に、他の制度との整合性も含め、改めて整理」とあるのですが、他の制度ということについて、幾つか具体的な制度をご説明いただければと思います。","respondent":"篠田学校計画担当課長","answer":"あるいは、先ほどもお話し申し上げた義務教育学校で、そもそも学校選択制が導入されたときに、義務教育学校というのは存在しておりませんでしたので、この間、新たな学校種として義務教育学校というものができたこともありますので、そういったことを踏まえた上で。","id":"exchange-025"}]},{"id":"topic-03","title":"平成３０年度新入学者の受入枠","agenda":"平成３０年度新入学者の受入枠","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"ご説明ありましたけれども、中学校において、７年生が、３５人で学級編制ができるようになっているというお話でしたけれども、下の表を見るに、８年生、９年生も同じように編制されていくのかなと思うのですけれども、学校編成の考え方がどうなっているのか伺いたいと思います。伺いたいと思います。","respondent":"有馬学務課長","answer":"基本的には、４月１日現在での数字で２,４２６名おりますので、それに対応した５９クラス分を設定しているということです。","id":"exchange-026"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"城南小学校が１クラス増えたという今のご説明だったのですけれども、この別表をざっと見てみると、ほかにも増えている学校が随分あるのだけれども、これはどういうことですか。","respondent":"有馬学務課長","answer":"要するに去年は城南小は２クラスでしたけれども、今年は３クラス増になっている。これは、主な要因は人口が増加している、就学人口・入学予定者の人数が増になっているということで、２クラスではおさまらないだろうということで３クラスにしたものです。","id":"exchange-027"},{"speaker":"鈴木（博）副委員長","kind":"質問","question":"とすると、平成２９年度は実績の数を書いているので、受入可能数の数で言うと、城南小学校以外は同じクラスの数だということですか。","respondent":"有馬学務課長","answer":"昨年度の受入可能数は、平成３０年度、平成２９年度と、城南小学校以外は同じクラス数で設定をしております。これは中学校のほうも同様です。","id":"exchange-028"}]},{"id":"topic-04","title":"平成２８年度品川区立学校における体罰等の実態把握","agenda":"平成２８年度品川区立学校における体罰等の実態把握","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"２ページの表に、非該当という分類があるのですけれども、これはどういったものなのか伺いたいと思います。そして、不適切な行為が２件あったということで、これは大変残念に思いますけれども、今後当然ないようにしていただきたいと思うのですが、この２件についてはどういった対応をされたのか、指導などを伺いたいと思います。","respondent":"熊谷指導課長","answer":"それから２点目ですけれども、対応ですが、この不適切な行為をした教員２名につきましては、校長を含め、それから指導課長である私からも指導を行い、二度とないようにということで対応してきたところですけれども、あわせて、校長連絡会を通じて全ての校長。","id":"exchange-029"},{"speaker":"のだて委員","kind":"質問・要望","question":"今後もこういったことがなくなるように力を尽くしていっていただきたいと思います。そして、３ページの取組事例のところで、山中小学校では毎週金曜日に連絡会を行い、生徒の状況を共有しているということで、情報を共有化することで、教員同士も何がいけないのかなどについて、互いに注意し合えると思いますので、こういった取組みを広げていっていただきたいと思いますがお考えを伺いたいと思います。","respondent":"熊谷指導課長","answer":"実は毎年７月から８月が体罰防止月間となっておりまして、教職員全員に対して校長が研修を行うとともに、一人一人に面談を行うことで、教員の様々な状況を見るとか、悩んでいることといったことも聞き出しながら、体罰防止に向けた取組を行っているところです。","id":"exchange-030"}]},{"id":"topic-05","title":"しながわ子ども食堂ネットワークの立ち上げ","agenda":"しながわ子ども食堂ネットワークの立ち上げ","exchanges":[{"speaker":"高橋（し）委員","kind":"質問","question":"前回のフォーラムもそうですけれども、社会福祉協議会のほうで、事務局なのでしょうか、中心になって進められていると思うのですが、そちらと家庭支援課との調整や連絡というのは、どのような形で連携をとりながらやられていくのでしょうか。","respondent":"廣田子ども家庭支援課長","answer":"区としましては、安全・安心に向けた支援について区が中心に行うという形で考えてあります。","id":"exchange-031"},{"speaker":"南委員","kind":"質問・要望","question":"資料の一番下に企業１社と書いてあるのですけれども、差し支えない範囲で、どういう企業なのかも教えていただきたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"企業におけるしながわ子ども食堂ネットワークへの参加予定につきましては、ひとり親の学習支援のときにご協力いただいた丸亀製麺を運営するトリドールホールディングスという企業がございまして、具体的に決まっているのはそのようなところです。","id":"exchange-032"}]},{"id":"topic-06","title":"保育園用地の取得","agenda":"保育園用地の取得","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、保育園のために購入するということで、敷地面積が５６５m2ということになると、園庭などは確保できるのか、伺いたいと思います。そして、地下にある防火水槽は解体してしまうということになるのか、今後の扱いについて伺いたいと思います。その場合、幾らなのか、また、建設の補助が幾らなのかについてもお伺いしたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"現在１００名を予定しておりますので、そうなると、屋外遊技場として設定すると、２５０m2ほど必要となってきますのでちょっと難しいかなと考えています。ただ、水遊び等ができるスペースを設置したいと考えておりますが、この点について現時点では未定です。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問","question":"わかりました。補助がないのですね。では、購入する額である３億２,４００万円は時価総額なのか、周辺と比べて相応の金額なのかなども伺いたいと思います。あわせて、これは区が買ったのち、私立園になるのか、貸し出して保育園をつくるということになるのかについて伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"金額につきましては都のほうにも、区と同じように財価審がございまして、適正な金額で契約をしたと聞いております。それから、保育園ですが、基本的には民設民営で考えております。ただ、保育需要の推移や地域のニーズなど総合的な観点から、現在最終的な調整をしています。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"園庭は考えていないという話なのですけれども、水遊びスペースの設置については未定なのですが、この間、水遊びスペースを確保してきている方向にあると思うのです。特に、しながわ区民公園の中にできる保育園には、確保していると地域の説明会で聞いておりまして、保育園における園庭の重要性について、どういうふうに区は認識しているのかと思います。そういう点ではどうなのでしょうか。","respondent":"大澤待機児童対策担当課長","answer":"保育園に園庭をつくりたいという区としての姿勢はもちろんありますので、この間、できるだけ狭くても何とかスペースをとるように努力はしていますが、先ほど申し上げましたように、全体の敷地から２５０m2を屋外遊技場としてとってしまうと。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"つくりたいという意思はあるということを聞いて安心しましたけれども、保育園をつくる際に、園庭をつくるということは大前提で考えていただきたいと思っています。園庭については、保育園の施設をつくるに当たって、園庭は必要不可欠なスペースだという、条件だという認識はあるのかどうか、最後に確認で伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"屋外遊技場を必ずつくると決めてしまいますと、７００m2以上の敷地がなければ保育園をつくれないということになってしまいますことから必ずそれをつくらなければいけないという縛りができるような状況でもございませんので、今後の件に関しましても。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"私は、例えば様々な工夫があっていいと思うのです。スペースから考えて、つくれないよというところから計画するのではなくて、どうやったらつくれるかという、そこのところに知恵を絞るべきだと、専門のご担当の所管なのですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"高橋（し）委員","kind":"質問","question":"そうすると、プロポーザルにおいて５年でなどの要件についてと、それから、予算書をきちんと見ていなくて申しわけないのですけれども、３億円余りの購入予算ですが、もともと計上していたものなのでしょうか。それとも、そうでないとすると特別会計のほうからというところなのですか。２点、お願いします。","respondent":"大澤待機児童対策担当課長","answer":"開設期間につきましても現在調整しているところではありますけれども、５年や１０年など短期間では考えておりません。方向性としては長期間で検討しているところです。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/476060?Template=document&Id=4918#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":41692,"voices":128}},{"id":"h29-20170711-5","meetingId":"h29-cm07","date":"2017年7月11日","dateIso":"2017-07-11","committee":"総務委員会","time":"午前１０時００分～午後 ５時０７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を51件抜き出しています。","topics":[{"id":"topic-01","title":"「議案審査」を行います。 説明に入る前に、各所管委員会における審査結果","agenda":"「議案審査」を行います。 説明に入る前に、各所管委員会における審査結果","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"保育園関係の事業のキャリアアップと処遇改善のことなのですが、区内私立保育園とか小規模保育のところは名目がきちんと入っているのですが、１３ページの真ん中の保育事業助成追加分の認証保育所運営費等助成のキャリアアップが歳入でどこになっているのか教えてください。","respondent":"秋山財政課長","answer":"それは、１１ページの８節児童保育費の区内私立保育園経費ほか３事業の、ほか３事業のところに入ってあります。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"キャリアアップ、保育事業のところなのですが、１３ページです。その両方において、ネックになっているのが研修のあり方だと思うのですが、研修がどのくらい課せられているか、わからないですか。全体的に、処遇改善のところは、公定価格に乗っていくと思うのですけれども、結果的に、一人一人の職員の方に賃金アップがされることになっているのかどうか。わかったら教えてください。","respondent":"秋山財政課長","answer":"その内容については、区としても報告を求めて、今後、確認をすると聞いております。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問","question":"１３ページの一番上の国民年金事務費追加分のところで、国民年金関係届出書等電子化のところの予算が計上されているのですが、この中に、マイナンバー制度にかかわる部分が入っているのか、入っていないのか、そこのところを教えてください。","respondent":"秋山財政課長","answer":"今回のものにつきましては、一連の法改正で、書式の変更等もある中で一部の書類については、今まで紙で持っていたのを電子にするということなので、この変更については、マイナンバーがスイッチを押したわけではないのです。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"書式の変更にかかわるということですか。紙ベースで。","respondent":"秋山財政課長","answer":"変更された様式も含めて、紙で送っていたものをＤＶＤという媒体で、電子データで送るという改善になりますので、マイナンバーと関係があるかというと、なくはないけれども、直接、マイナンバーが入ったからということではないと認識しています。","id":"exchange-004"},{"speaker":"須貝委員","kind":"質問","question":"１つお聞きしたいのですが、衛生費の中で、今回、ＡＥＤ設置補助、補助金を出すわけですが、民間業者への助成というのは初めてなのでしょうか。それとも、ほかでもやっているのでしょうか。それについて、１点だけお聞かせください。","respondent":"秋山財政課長","answer":"保育園等で、運営費の中でＡＥＤの設置補助があったと記憶しておりますが、健康課から民間事業者にというのはこれまではないと考えています。","id":"exchange-005"},{"speaker":"須貝委員","kind":"意見","question":"今回、民間の業者に補助金という形で出すのは、別にそれは構わないと思うのです。２４時間、周りの人も、そこのお風呂屋に来た人は、それで使える。その時間帯。でも、もちろん休業日もあります。もし、助成という形でＡＥＤを普及、設置させていくならば、２４時間使えるような仕組みに対して助成をしていくのが筋ではないかと思うのですが、その辺はどう思われますか。","respondent":"秋山財政課長","answer":"２４時間ではないにしても、夜間、深夜まで使えるという点で補助をするという考えになっています。","id":"exchange-006"},{"speaker":"須貝委員","kind":"意見","question":"これはずれてしまうのですけれども、一応、考え方として、今、各町会でも、場所によって、２４時間設置をしたいという話も聞いているのです。そういうこともあるので、有効に活用できるような、地域の町会役員を含めて知っているような、２４時間、ここに行けばＡＥＤがあるという仕組みづくりを今後、助成をするならば、そういうほうに資金を出していただければありがたい。意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-007"},{"speaker":"あくつ副委員長","kind":"確認","question":"厚生委員会の中で質疑があったかもしれません。確認してこなくて申し訳ないです。ＡＥＤは、通常、今はリースでやっていると思うのですけれども、７００万円という金額、２７で割ると、大体２５万円ぐらいなのです。２７浴場で１台ずつ、年間のリースとメンテナンス契約も入れてという予算計上なのかどうか。そこだけ確認をさせてください。","respondent":"秋山財政課長","answer":"今回は、購入費の助成でありまして、メンテナンスは組合が行うという仕分けになってあります。","id":"exchange-008"}]},{"id":"topic-02","title":"「」を聴取いたします。 初めに、(1)全国シティプロモーションサミット","agenda":"「」を聴取いたします。 初めに、(1)全国シティプロモーションサミット","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"今のご説明だと、テーマとかは今、調整中と。イメージが浮かばないと思って、伺おうと思ったのですけれども、調整中ということで、昨年のテーマで印象的なものがあったら教えていただければと思います。","respondent":"木村報道・プロモーション担当課長","answer":"定住人口を増やすのか、観光で人を集めるのか、あるいは外国人の方々へのご案内みたいな部分など、いろいろな観点があるのです。そういう観点別に講演、セミナーを企画、実施されたところです。","id":"exchange-009"},{"speaker":"石田（し）委員","kind":"質問・要望","question":"２点お伺いします。１点目は、参加自治体の募集についてですが、どのように募集をかけていくのか。実際に、昨年行かれてみて、何がよかったのか、何がよくなかった、これは自分たちが区でやるときには必要ないみたいなものがあったら、ぜひ教えていただきたいと思います。そういったものを活かして、よりよいもの、昨年以上のもの、ぜひ成功していただきたいという思いから質問します。","respondent":"木村報道・プロモーション担当課長","answer":"１点目、募集の方法ですけれども、まず、募集サイトのようなものを立ち上げる予定にしています。それから、次に、実際に中身が固まってまいりましたら、いわゆるダイレクトメールを全国の自治体にお送りして、募る形を考えております。","id":"exchange-010"},{"speaker":"石田（し）委員","kind":"意見","question":"こういった全国の方たちが集まるところで、刺激を受けながらというのがその１つだと思いますけれども、それをきっかけに、例えば他自治体との連携が深まって、観光以外にもさまざまなもの。これは意見で終わります。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問・要望","question":"まだ全然イメージがわかない感じで、今後のスケジュールが７月の下旬に参加自治体募集開始ということなのですが、そこで募集サイトを立ち上げて、ダイレクトメールをしてということだと思うのですけれども、いつぐらいまでに基調講演の中身を固めて、先進事例講演はどういうところにお願いするのか、そういう全体のスケジュールを教えていただきたいのが１点。その辺も教えてください。","respondent":"木村報道・プロモーション担当課長","answer":"先ほどご説明した区内見学の中で、例えば商店街を見にいく、あるいは水辺のコースに行って、そこでそれぞれ、その地元でご活躍されている方々がいらっしゃいますので、そういう方々にご案内をいただきながら、ご紹介をするというつくりも考えてあります。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"いろいろな自治体の方が品川区に来ることで、どういうふうに自分のところの自治体をＰＲしよう、サミットを利用しようと思ってくださるのは、とてもありがたいと私は思うので、ぜひ、それに応えられるような、区民全体がこれを盛り上げているというつくり方を期待したいと思います。その辺について、もし何か、今、既に考えていらっしゃることがあったら、少し教えていただきたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"例えば商店街でありますとか、町会、自治会でありますとか、そういうところに、直接、こういうことをやりますというお話をしながら、ご理解をいただきながら、ご協力もいただきながらという動きをしてまいりたいと思ってあります。","id":"exchange-013"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"今後、詳細についてはお示しいただけるということなのですけれども、今現在、これから参加自治体の募集を開始するということで、参加対象者がどれぐらいいらっしゃるのか。大体、想定している人数をお知らせいただきたい。武蔵小山パルム商店街などがありますけれども、ほかの商店街も幾つかいろいろありますが、そういったところも考えているのかどうか、お知らせいただきたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"実際には、２３区、それから市部分に関しまして、そういう意味では、坂井市で実施するよりも、いわゆる声かけをしやすい部分、来ていただきやすい部分もありますので、そういう部分はＰＲをしていこうと思ってあります。","id":"exchange-014"},{"speaker":"高橋（伸）委員","kind":"質問","question":"坂井市のときは１２３団体ということで、当然、全国からいらっしゃると思うので、品川区でも提携しているホテルとか、そういうものがあると思うのですけれども、そういうことも、このサミットにおいてお知らせをしていただくのかどうか、それだけお聞きしたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"かなり宿泊施設が混雑することが想定されます。これから、旅行事業者と連携をとりまして、宿泊先についてのご案内につきましても、今は考えてあります。","id":"exchange-015"},{"speaker":"須貝委員","kind":"意見","question":"シティプロモーションはいろいろあるとは思うのですが、私が思うのは、たまたま品川区の立地条件がよかった、大企業の本社機能が都会に集中している。防災機能もそれぞれよくなった。でも、これはすごく品川区が先鞭、全国の先駆けとして、地域の再生、活性化に貢献した、１つ、すごいアピールだと私は思うのです。でも、それを言っていいのかどうかという問題はあるのですが、感想だけ言わせていただきます。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-016"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"今回は５回目ということで、記憶では、尼崎市、弘前市、相模原市、坂井市。品川区の場合は、プロモーションサミットについては、どういう事業者にお願いをしているのかを確認させていただきたいということが１つ。知らせるべきだと私は思っているのですが、そこについて、全てにどういう手段で知らせていくのかを１つ教えていただきたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"運営の事業者ですけれども、委託をして運営をすることを考えております。株式会社宣伝会議が主として行う予定です。","id":"exchange-017"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"せっかく品川区でやっていただけるということですから、幅広くお知らせをしていただきたいと思います。先ほど１、目的の(2)の説明であったとおり、品川区としてのシティプロモーションの絶好の機会でもあると思いますし、２３区、また東京都の中で、今、本当に先頭を走っているのは品川区だぐらいの気概でやっていただきたい。その辺についてのお考えを聞かせていただきたいと思います。","respondent":"木村報道・プロモーション担当課長","answer":"そういう引きの部分につきましては、十分に検討してまいりたいと思ってあります。それから、先ほどご紹介いたしました事業者、株式会社宣伝会議ですけれども、「事業構想力の研究」という雑誌を出しておりまして、こちらは全国の自治体の首長に献本をしています。","id":"exchange-018"},{"speaker":"あくつ副委員長","kind":"質問・要望","question":"前々から申していますけれども、特別区の全国連携プロジェクトがあると私は思っています。では、本当にやってくれるのですかという問いかけがあったときに、ばっちりと、わかりました、しっかりそういうお話し合いをしましょうという体制もしっかりつくっていただきたい。これは企画になってしまうかもしれないのですけれども、そこについてのお考えをお聞きしたいと思います。","respondent":"木村報道・プロモーション担当課長、中山企画部長","answer":"ぜひ、そういうところはつながっていただけるように、あるいは、そういう体制をとる、当たり前ですが、これからになりますけれども、そういう心持ちで、ご出展をいただきたいと考えております。品川区の地を使ってやってもらう。そういう面で言えば、ある意味、ウィン・ウィンの関係ですので、この場所を使って、全国との関係を広げる１つのきっかけにするような意識も持って、今回のイベントに臨みたいと思っています。","id":"exchange-019"},{"speaker":"飯沼委員","kind":"質問・要望","question":"６ページのところに未満という表示があるのですが、ほかにももう１カ所あったのですが、この未満はどういう基準で未満なのかを教えていただきたい。改修工事に係っての代替施設の考え方を聞かせていただきたい。","respondent":"立川経理課長","answer":"未満ですが、こちらは、品川区では平成２６年の１０月から、予定限度額１,０００万円以上の工事請負契約について、最低制限価格を設けております。今回、この未満となったのは、その最低制限額を下回ったものです。","id":"exchange-020"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１,０００万円以上の工事で、最低制限の価格を下回っているもので、６ページの電気設備工事は、最低制限の価格は幾らだったのかを教えていただきたい。代替施設のところは、この間、あちこちで出ているので、基本的な考え方をぜひ教えていただきたい。所管がどこかわかりませんが、区有施設の工事に伴う施設の不足についての代替の考え方の部分で、どなたかお答えできるのではないでしょうか。","respondent":"立川経理課長、小林施設整備課長","answer":"最低価格です。こちらは非公表です。私から、代替施設についてお答えします。先ほどの非公表の件で補足ですが、基本的な算出の方法がございまして、詳細は当然、非公表ですけれども、基本的な考え方ということで話をします。","id":"exchange-021"},{"speaker":"飯沼委員","kind":"質問","question":"計算は難しいということですね。それはそうですね。予定価格を算出するのも大変なので。でも、それは基本的に、大体、モデルが出ているということにおいては、ある程度は予測ができるということです。それでも未満になってしまうケースがある。厳しくその辺は見ているという評価でよろしいのでしょうか。そのことに対して、近隣施設をご案内すればいいというところにとどまらないと思うのです。","respondent":"柏原企画調整課長","answer":"枠としての限界がある部分がありますので、そういったところをどうやって工夫していくかというのは、これからの課題であろうと考えています。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"課題と捉えてくださっているので、従来どおりのご案内だけでは足りないところにおいて、さらなる工夫をしていただきたいと思っています。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"吉田委員","kind":"意見","question":"基本的なことになってしまうのですけれども、この建物の改修は必要だというのはよくわかるのですが、大体、どれくらいの改修のスケジュールにのっとった、どのレベルの工事なのか。そういうことがこの場合、あるのかないのか。何年に１度、この改修が行われるとか、そういうこととあわせてお答えいただけますか。","respondent":"小林施設整備課長","answer":"大体、目安的には２０年とか３０年で大規模改修をやるのがベストかと考えています。","id":"exchange-024"},{"speaker":"吉田委員","kind":"質問","question":"昭和５７年に建った後、初めての大規模改修ということですか。この時期に一気にいろいろ更新する。そうすると、この後、見込みがありますね。今回の改修で、どれくらいは持たせるという言い方がいいかどうかわかりませんけれども、その辺のスケジュールもあったら教えてください。","respondent":"小林施設整備課長","answer":"現在、もう３５年経過して、ふぐあい等は、若干、小さなものはあるのですが、今回、全てやりますので、その間の修繕だとか維持管理というのはまた別途ありますけれども、おおむね３０年ぐらいの年数を考えております。","id":"exchange-025"}]},{"id":"topic-03","title":"の(5)冨士見台中学校外壁改修その他工事請負契約","agenda":"の(5)冨士見台中学校外壁改修その他工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"１３ページの工事内容のところなのですが、外壁の改修が主な内容ですけれども、学校の外壁の改修の基準は、どういう状況になったら改修を行っていくことになっているのか。その下の建具改修、校舎外部側で７９カ所が何なのかわからないので教えていただきたい。その下のところの被服室を特別支援教室に改修する中身も教えていただきたい。","respondent":"小林施設整備課長","answer":"外壁改修についての耐用年数に基づいて、１０年だとか１５年だとか、いろいろ見方はあるのですけれども、基本的には、教育委員会で工事を進めているのは、夏休みに集中して工事をやっていける範囲で工事を発注している。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"外壁工事をやれる範囲で進めているということなのですが、冨士見台中学校の場合は、何年経過して、今回の改修になるのか、わかったら教えてください。","respondent":"小林施設整備課長","answer":"外壁は現在２０年以上経過していると私は聞いています。","id":"exchange-027"},{"speaker":"吉田委員","kind":"質問","question":"先ほどのご質問の中の特別支援教室が必要になったということはわかるのですけれども、被服室の機能はもう必要ないということなのか、どこか別のところで確保されているのか、その辺がもしわかったら教えてください。","respondent":"小林施設整備課長","answer":"特別支援教室については、いろいろな仕切りだとか、用途に適した改修をしていきますので、被服室の造りのままでは使えなかったと思います。被服室は代替があると聞いております。","id":"exchange-028"}]},{"id":"topic-04","title":"八潮団地内区道歩道拡幅整備工事（第４工区）請負契約","agenda":"八潮団地内区道歩道拡幅整備工事（第４工区）請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"きのう八潮に伺ったときに、周りの歩道なども目に入ったのですが、結構、狭くて、車椅子は通れないようなところが何カ所かあったので、歩道を広げていくのは本当に待たれていると思うのです。ご意見が届いたのが、結局、歩道を広げるために車道が狭くなっている。自転車の通行が危険とか、そういう声は届いていますでしょうか。","respondent":"立川経理課長","answer":"他の所管もありますので、その辺は把握していません。さまざまなご意見があるということで、質問があったということは所管に伝えていきたいと思いす。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"必要な内容なので、ぜひ、お伝えいただきたい。車道を利用している自転車の通行のところの安全対策も、そっちにも目を向けていただいて、整備をしていただきたいと思いますので、よろしくお伝えください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"吉田委員","kind":"質問","question":"今のご意見とかぶるところがあって、一応、お伝えするだけお伝えしておきます。歩道の拡幅自体は本当によかったと思うのですけれども、その辺のルールの徹底というのでしょうか。それから、六十何歳以上も通ってもいいということなので、この拡幅というところにはそういうことが伴うので、それについて意見を述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"}]},{"id":"topic-05","title":"大井第一小学校校庭整備工事請負契約","agenda":"大井第一小学校校庭整備工事請負契約","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"２０ページのところに工事内容が書かれているわけなのですが、校庭の改修のところで、人工芝生化とゴムチップ舗装と書いてあるので、この辺がどういうふうに整備されることになるのか、教えていただきたいのが１点。","respondent":"立川経理課長、小林施設整備課長","answer":"人工芝生化についてなのですけれども、学校については、基本的には、今後、人工芝生化をしていくと聞いております。砂場の周りとか、走り幅跳びをするところにゴムチップを敷いたりとか、遊具の周りにゴムチップを敷いたりとか、そういうふうにやっているケースが多いです。","id":"exchange-032"},{"speaker":"吉田委員","kind":"質問","question":"今の人工芝生のことなのですけれども、人工芝生は今、すごい進化していると聞いておりまして、お値段もさまざまなようです。これから人工芝生化するという方向だということは、今のご答弁でわかりましたけれども、どういうものを選ぶのかとか、予算はどれくらいかというのは決まっているのでしょうか。今回の人工芝生は、どんな人工芝生か、わかっていらっしゃいますか。","respondent":"小林施設整備課長","answer":"今回採用する人工芝はロングパイルという、ちょっと長い毛の人工芝で、その中に緑のゴムチップみたいなものが入って、あと砂も入って、それで中を攪拌しているような人工芝の構造になっいると聞いております。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"一番心配なのは、子どもの足への負荷とか、それから、けがとかだと思うのですけれども、どういうメリットを考えて、これを採用したのか。学校によって使われ方も違うと思うのですけれども、学校の希望を入れられて、ここはこの学校での決定ということになったのか。その辺も、もしあれば教えてください。","respondent":"小林施設整備課長","answer":"学校の要望というわけではなくて、これは教育委員会で何校もやっておりますので、その中から、この工法が一番適しているということで、統一されてやっていると思います。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問","question":"さっきお値段のことも言いましたけれども、安い人工芝は、更新も早くしなければいけなかったりして、どれくらいの更新頻度を見込んでの今回の工事なのか教えてください。","respondent":"小林施設整備課長","answer":"人工芝は、私も経験がないのですけれども、大体、目安的には１０年だとか１５年でメンテナンスを入れるような状況を把握していて、手入れが必要になってくれば、どこに手を入れるかとか、そういう点検が多分、１０年から１５年かけてやられると思います。","id":"exchange-035"},{"speaker":"須貝委員","kind":"質問","question":"１点だけ。工期が１０月３１日となっておりますが、小学校で工事期間中、グラウンドが使えないではないですか。教育現場としては、夏休みとか、そういうときに実施できたらよかったと思うのですが、さりとて、では、夏休みに全部やるとなると、もちろん業者が一斉にやるというわけにはいかないと思うのです。その辺の配慮というのはあったのでしょうか。","respondent":"小林施設整備課長","answer":"その代替というのは、一般的に、夏なものですから、まずはメインがプール、あと体育館、一部、屋上も使う。どうしても校庭といえば、また校長会とかで近隣の学校に協力依頼をするのが一般的なものですから、そういうところで対応していると思います。","id":"exchange-036"}]},{"id":"topic-06","title":"しながわ区民公園便所新築その他工事請負契約","agenda":"しながわ区民公園便所新築その他工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"今回、老朽化ということで、新築なのですけれども、この工事内容だけを見ると、トイレの附帯の工事ということなのでしょうか。その辺をまずお伺いしたいと思います。","respondent":"小林施設整備課長","answer":"５番の関連工事の中に電気設備工事と機械設備工事があるのですけれども、そちらのほうで、附帯の設備だとか、そういうものは全て新しく更新するということになっております。","id":"exchange-037"},{"speaker":"吉田委員","kind":"質問・要望","question":"ちなみに、どういうトイレになるのかお聞かせいただきたいのです。その中でも、最近、ベビーベッドまでは、おむつ交換用のものがつくのですけれども、乳幼児を超えてしまうと、障害児であっても交換ができないという状況を踏まえて、新築のときには、ぜひその辺をとお願いしてきたのですが、その辺について、いかがでしょうか。","respondent":"小林施設整備課長","answer":"基本的な考え方は、男女別々のトイレがありまして、その中に、誰でもトイレというのを今回も設置を計画しております。ご質問のあったベッドにつきましては、多目的ベッドというのを今回セットしました。","id":"exchange-038"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１棟を解体して、新たに３カ所トイレができます。公園は広いので、あまり気にしなくて、大事なところにトイレが設置できるというところにおいて、吉田委員もおっしゃったのですが、誰でも利用できるトイレというのを、今ある誰でもトイレよりも、もっと幅を広げて考えていただきたいのです。レインボーマークがついているトイレをどこかに配置してほしい。どういうことなのか、わかったら教えてください。","respondent":"小林施設整備課長","answer":"最初の質問のＬＧＢＴ等については、いろいろ難しいところはあります。この誰でもトイレというのは、字のごとく、誰でも使えるトイレができるわけなので、防犯上や何だかんだと、いろいろな問題はあるのです。","id":"exchange-039"},{"speaker":"飯沼委員","kind":"質問・要望","question":"トイレのところは、サインを１つつけるところからしても、工夫というか、大事なトライだと思うのです。ぜひ工夫をしていただきたいと思います。緑の件は、周りの方の意見を聞いたり、どういうふうにしていくのかとか、担当のところにぜひお伝えをしていただきたいと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"あくつ副委員長","kind":"意見","question":"今回の工事は、解体と新築工事ということで、トイレに直接関係ない管理事務所の解体と車庫の解体等も入っているのです。今回、たしか保育園もこの地域につくるということになっていて、工期が１月３１日までとあるので、そんなに時間がないという中で、解体と新築、また保育園等も入ってくると思うのですが、そこら辺の調整というのはしっかりできていらっしゃるのかどうか。","respondent":"小林施設整備課長","answer":"部分的な建築工事、今の便所だとか保育園というのは、全体的な打ち合わせ会議を開いて、工事の動線がダブらないように、ダブる際は日にちをずらしたりだとか、そういう打ち合わせをしながら進めております。","id":"exchange-041"}]},{"id":"topic-07","title":"原動機付自転車ご当地ナンバープレートデザイン募集","agenda":"原動機付自転車ご当地ナンバープレートデザイン募集","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"話題を呼びそうな企画だと思うのです。(3)のところに最優秀賞１作品、優秀賞２作品ということなのですが、ナンバープレートは２,０００枚つくるということなのですが、具体的にどう選んでいくのか。２,０００枚つくって、なくなったら終了してしまう取組みなのか。予算的にどのくらい考えているのかを教えてください。","respondent":"榎本総務部長","answer":"表彰としては３作品選ぶのですけれども、ナンバープレートとしては１種類、その中から１つをつくる予定です。これは先着順で交付を考えておりまして、その後、もし、それを超えるような応募があれば、また来年度以降の予算の中で対応を考えていきたいと思っています。","id":"exchange-042"},{"speaker":"石田（し）委員","kind":"意見","question":"１点だけ。この表彰で最優秀賞と優秀賞、３作品を選ぶ。この方たちに何か区として、スケジュールを見ても出てこないのですけれども、例えば発表をする、この人たちが描きましたみたいに、受賞された方たちへの特典の記載がないので、そういったものは一切考えていないのか。","respondent":"榎本総務部長","answer":"表彰につきましては、賞状と、副賞として図書カードの贈呈を考えております。表彰状と副賞という形での表彰をしたいと考えています。","id":"exchange-043"}]},{"id":"topic-08","title":"新公会計制度の導入スケジュール等","agenda":"新公会計制度の導入スケジュール等","exchanges":[{"speaker":"飯沼委員","kind":"質問","question":"１点だけ。これから勉強しなくてはいけないと思って聞かせていただいたのですけれども、１つ、決算書でも予算書でも、説明の欄がかなり大きくありますが、このところの並び方、いろいろな事業がどういう並び順で並ぶのか。今までの予算書と決算書の並び方と違ってくるのか。ここの説明のところも教えてください。","respondent":"秋山財政課長","answer":"その課の並びにつきましては、長期基本計画の体系を参考に、並び順等は決めていきたいと考えています。ただ、必ずしも長期基本計画に全部出ているわけではないので、その並び順は個別に考えていきます。","id":"exchange-044"},{"speaker":"飯沼委員","kind":"質問","question":"予算説明書の丸が１、２、３、４、５と並んでいる、長期基本計画の施策体系別に整理という、ここを先に聞かなくてはいけなかったのですが、体系別というのは、具体的に、もうちょっとかみ砕いてご説明いただくと、どういうことですか。","respondent":"秋山財政課長","answer":"それを課ごとにまとめてきて、その並びで整理をしたというのが率直なところで、予算の事業で言うと、長期基本計画の項目とは、今のところ、一致をしている部分とそうでない部分がありますので、その辺を長期基本計画の体系ごとに整理をしていくということで、この際に。","id":"exchange-045"},{"speaker":"飯沼委員","kind":"質問","question":"施策ごとにまとまって並んでいくということになるのですか。課ごとに違ってくるから、今までの並び方とは全く違ってくるということですね。そういった意味では、事業ごとにまとまって見れるふうに変わっていくという捉え方でよろしいですか。","respondent":"秋山財政課長","answer":"長期基本計画の施策体系で行くのですけれども、その前段として、課ごとにまずまとめますので、その並びを長期基本計画の順番にしていく、そのほうが見やすいであろう、そういう考え方ですので、事業ごとにあるということではないです。","id":"exchange-046"}]},{"id":"topic-09","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"委員長が今読み上げた部分は後でいただきたいと言ったのですけれども、ちょっと漠然としていますけれども、あまり狭めないで、大きなテーマなので、これから委員の意見を取り入れて、深めていただきたいと思いますが、いかがでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"}]},{"id":"topic-10","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"もうちょっと多様性があってもいいのではないか。私は、人権のところで、多様性なり、いろいろな人々の人権を尊重していくような自治体になってほしいと思って、関西のほうでもかなり先進的な自治体があるので、希望したのです。テーマが特化し過ぎではないかという印象を受けたので、ぜひ、みんなが満足するような視察にしていただきたいと思うのです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"須貝委員","kind":"意見","question":"委員長、副委員長にお任せしたのですが、あまりにもシティプロモーション色が強い。本当に武蔵小杉駅前付近を調査したいという強い願望があったのですが、シティプロモーションの報告が終わった後、こういうシティプロモーションという形で出ているのですが、私も、ちょっと一方に偏り過ぎているのではないかとは感じました。一応、意見だけ、どうなのかという疑問を感じました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-049"},{"speaker":"石田（し）委員","kind":"意見","question":"基本的には、正副に任せている前提で、皆様から具体的な案が出ていない限り、僕は、正副がここまでまとめていただいたので、その方向で行っていただければよろしいのではないかということです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"須貝委員","kind":"意見","question":"本来、我々も、どこの場所で、どういう視察をというのは出したのです。一応、出してくださいということで。今日はそれを若干、意見交換するのかと思ったのです。それが一気に来てしまったので、ショックを隠せない。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/577253?Template=document&Id=2082#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2017-01-01&TermEnd=2017-12-31"}],"sourceMeta":{"pages":0,"characters":36252,"voices":170}}]);
